// The painted map: the whole walk seen along the path, from the first clearing at the bottom to Old
// Ember's glowing cave at the top (MAP_ART, from tools/scenes/build_map.py). It has five clearings
// and the cave: a walk of up to six glades uses them (a shorter one skips a clearing or two; see
// stopOf), only a longer one keeps the drawn map.
// Alive like the other painted screens: the trees at the sides sway, the blue mushrooms and the
// lanterns glow and fade, the cave's light breathes, and the glades you've cleared keep a lantern lit.
import { MAP_ART } from "./map-art.js";
import { paint, paintBg } from "./pics.js";

const A = MAP_ART;
export const MAP = A;

/** Whether this walk fits the painted map (a clearing for each glade, the cave for Old Ember). */
export const paintedMapFits = (floors) => floors >= 2 && floors <= A.stops.length;
/** The painted stop for a glade: Old Ember's is always the cave, the others spread over the clearings. */
export function stopOf(f, floors) {
  const clearings = A.stops.length - 1;
  if (f >= floors - 1) return A.stops[clearings];
  return A.stops[floors <= 2 ? 0 : Math.round((f * (clearings - 1)) / (floors - 2))];
}

/**
 * The scene. done: which glades are cleared (they keep a lantern lit). night: the walk to Old Ember.
 * The markers, the traveller and the "You are here" tag go in the overlay, pinned by fitMap().
 */
export function mapSceneHtml({ done = [], night = false, floors = A.stops.length }) {
  // By night: the painted moonlit map when there is one (build_map.py), else the day one darkened.
  const painting = night && A.night ? A.night : A.img;
  const rnd = (i, k) => ((Math.sin(i * 12.9898 + k * 78.233) * 43758.5453) % 1 + 1) % 1;
  const shrooms = A.shrooms
    .map(([x, y, r], i) => `<span class="ts-glow cyan" style="left:${x - r * 1.6}px;top:${y - r * 1.6}px;width:${r * 3.2}px;height:${r * 3.2}px;--sp:${(2.6 + rnd(i, 1) * 3).toFixed(2)}s;--d:${(-rnd(i, 2) * 5).toFixed(2)}s"></span>`)
    .join("");
  const lamps = A.lamps.map(([x, y], i) => `<span class="art-glow" style="left:${x - 50}px;top:${y - 50}px;width:100px;height:100px;--c:#ffcf7a;--sp:${2.4 + i * 0.7}s"></span>`).join("");
  const cleared = done
    .map((f) => {
      const [x, y, w, h] = stopOf(f, floors);
      return `<span class="mp-cleared" style="left:${x - w * 0.7}px;top:${y - h * 1.2}px;width:${w * 1.4}px;height:${h * 2.4}px;--d:${(-f * 0.6).toFixed(1)}s"></span>`;
    })
    .join("");
  const [cx, cy] = A.cave;
  const edge = 700; // the trees on each side, which sway
  const canopy = (x0, x1, dir) => `<div class="ts-canopy" style="left:${x0}px;width:${x1 - x0}px;height:${Math.round(A.h * 0.62)}px;${paintBg(painting)};background-size:${A.w}px ${A.h}px;background-position:${-x0}px 0;--dir:${dir}"></div>`;
  return `<div class="scene art map-art${night ? (A.night ? " night painted-night" : " night") : ""}" data-scene="map-art" role="img" aria-label="The walk ahead: a path winding through five clearings, past a pond and a stream, to a cave glowing gold at the top.">
    <div class="art-world" style="width:${A.w}px;height:${A.h}px">
      ${paint(painting, `class="art-bg" alt="" draggable="false"`)}
      ${canopy(0, edge, 1)}${canopy(A.w - edge, A.w, -1)}
      <span class="mp-night"></span>
      <span class="mp-cave" style="left:${cx - 170}px;top:${cy - 150}px;width:340px;height:300px"></span>
      ${lamps}${cleared}${shrooms}
    </div>
    <div class="art-ui"><canvas class="art-particles" aria-hidden="true"></canvas></div>
  </div>`;
}

/** Sparkles rise from the cave and the lanterns. */
export const mapSources = () => [[A.cave[0], A.cave[1], "#ffd890"], ...A.lamps.map(([x, y]) => [x, y, "#ffcf7a"])];
export const mapArea = { x0: 700, y0: 200, x1: A.w - 700, y1: A.h - 40 };

/**
 * Where the world goes: the painting covers the window (or its left part, cover, when a panel's
 * backdrop covers the rest), and the whole walk (the clearings and the cave) fits in the room above
 * the panel (roomH), below the top (top) and left of a panel beside it (free), centred across.
 */
export function mapView(vw, vh, { roomH = vh, top = 0, free = vw, cover = vw } = {}) {
  const xs = A.stops.map((s) => s[0]);
  const ys = A.stops.map((s) => s[1]);
  const f = { x0: Math.min(...xs) - 240, x1: Math.max(...xs) + 240, y0: Math.min(...ys) - 150, y1: Math.max(...ys) + 110 };
  // It covers the room above the panel; below that the panel's own backdrop takes over.
  const s = Math.max(cover / A.w, roomH / A.h, Math.min(free / (f.x1 - f.x0), (roomH - top) / (f.y1 - f.y0)));
  let tx = free / 2 - ((f.x0 + f.x1) / 2) * s;
  let ty = top + (roomH - top) / 2 - ((f.y0 + f.y1) / 2) * s;
  tx = Math.min(0, Math.max(cover - A.w * s, tx));
  ty = Math.min(0, Math.max(roomH - A.h * s, ty));
  return { s, tx, ty };
}

/**
 * Where you stand by a clearing (world units): on the path at its edge (the path runs up the middle of
 * the map), your feet a little below its centre.
 */
export function travellerAt(f, floors) {
  const [x, y, w, h] = stopOf(f, floors);
  const side = Math.sign(1200 - x) || 1;
  return [x + side * w * 0.36, y + h * 0.22];
}

// The markers keep a fixed size on screen while the map scales (so the portraits stay readable),
// shrinking a little on a small map so the clearings don't pile up. Sizes and places below are in
// screen pixels.
export const markerSize = (k) => Math.round(Math.max(26, Math.min(34, k * 100)));

/** The x that keeps a figure (half: half its width) beside the marker at bx, on its own side, off it. */
export function besideMarker(x, bx, half, mk, gap = 3) {
  const side = Math.sign(x - bx) || 1;
  return Math.abs(x - bx) < mk / 2 + half + gap ? bx + side * (mk / 2 + half + gap) : x;
}

/**
 * The y (feet) that keeps a figure (x ± half wide, h tall) from standing with its head over a marker
 * above it (before Old Ember, hers): it steps down the path until its head clears.
 */
export function underMarkers(x, y, half, h, marks, mk, gap = 3) {
  for (const [mx, my] of marks) {
    if (Math.abs(mx - x) >= half + mk / 2 || my > y - h / 2) continue;
    if (y - h < my + mk / 2 + gap) y = my + mk / 2 + gap + h;
  }
  return y;
}

/**
 * The x for a tag centred at x (tw × th, its bottom edge at bottom), nudged sideways off any marker
 * ([x, y] centres) it would cover, and kept inside 0..free.
 */
export function tagOffMarkers(x, { tw, th, bottom, marks, mk, free, gap = 3 }) {
  for (const [mx, my] of marks) {
    if (bottom <= my - mk / 2 || bottom - th >= my + mk / 2) continue;
    if (Math.abs(mx - x) >= tw / 2 + mk / 2 + gap) continue;
    x = mx > x ? mx - mk / 2 - gap - tw / 2 : mx + mk / 2 + gap + tw / 2;
  }
  return Math.max(tw / 2 + 4, Math.min(free - tw / 2 - 4, x));
}
