// Puts a forest scene on the page, HD-2D style: the pixel picture, a blurred copy of it at the top
// and bottom (the tilt-shift that makes it read as a miniature), whoever stands in it, and then
// the light, in three overlays: shade, glow (screen-blended) and the colour grade with a vignette.
import { SCENES, SPRITES, PORTRAITS, RELIC_ART, PORTALS, FORK_SPOTS, HERO_ART, EMBER_ART } from "./art-data.js";
import { paint } from "./pics.js";
import { SHADOW_PLACED } from "./shadow-placed.js";

let uid = 0;
const f = (n) => +n.toFixed(3);

/** The light layers of a scene, in its 390-wide space. */
function lightSvgs(s) {
  const L = s.light;
  const W = s.w * 3;
  const H = s.h * 3;
  const i = ++uid;
  const vb = `viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-hidden="true" focusable="false"`;
  const radial = (p, k) =>
    `<radialGradient id="g${i}_${k}"><stop offset="0" stop-color="${p.color}" stop-opacity="${p.o ?? 0.5}"/><stop offset=".45" stop-color="${p.color}" stop-opacity="${f((p.o ?? 0.5) * 0.45)}"/><stop offset="1" stop-color="${p.color}" stop-opacity="0"/></radialGradient>`;
  const all = [...L.pools, ...L.glows];
  const shade = `<svg class="sc-shade" ${vb}><defs><linearGradient id="c${i}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#05030a" stop-opacity="${L.ceiling}"/><stop offset="1" stop-color="#05030a" stop-opacity="0"/></linearGradient></defs><rect width="${W}" height="${H}" fill="${L.ambient.color}" opacity="${L.ambient.o}"/><rect width="${W}" height="${Math.round(H * 0.34)}" fill="url(#c${i})"/></svg>`;
  const glow = `<svg class="sc-glow" ${vb}><defs>${all.map(radial).join("")}<filter id="b${i}" x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur stdDeviation="9"/></filter></defs>${L.pools
    .map((p, k) => `<ellipse cx="${p.cx}" cy="${p.cy}" rx="${p.rx}" ry="${p.ry}" fill="url(#g${i}_${k})"/>`)
    .join("")}${L.rays.map((r) => `<path d="${r.d}" fill="${r.color}" opacity="${r.o ?? 0.18}" filter="url(#b${i})"/>`).join("")}${L.glows
    .map((g, k) => `<circle cx="${g.cx}" cy="${g.cy}" r="${g.r}" fill="url(#g${i}_${L.pools.length + k})"/>`)
    .join("")}${L.dust.map(([x, y, r, o, c]) => `<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" opacity="${o}"/>`).join("")}</svg>`;
  const grade = `<svg class="sc-grade" ${vb}><defs><radialGradient id="v${i}" cx=".5" cy=".48" r=".72"><stop offset=".55" stop-color="#000" stop-opacity="0"/><stop offset="1" stop-color="#05030a" stop-opacity="${L.vignette}"/></radialGradient></defs>${L.grade ? `<rect width="${W}" height="${H}" fill="${L.grade.color}" opacity="${L.grade.o}"/>` : ""}<rect width="${W}" height="${H}" fill="url(#v${i})"/></svg>`;
  return { shade, glow, grade };
}

/**
 * Where something of this many grid pixels stands, as percentages of the scene. Its depth (z-index)
 * is where its feet are: nearer the bottom is nearer you, so it stands in front (see occluders).
 */
export function place(sceneId, [x, y], w, h, lift = 0) {
  const s = SCENES[sceneId];
  return `left:${f(((x - w / 2) / s.w) * 100)}%;top:${f(((y - lift - h) / s.h) * 100)}%;width:${f((w / s.w) * 100)}%;height:${f((h / s.h) * 100)}%;z-index:${depth(y)}`;
}
/** A depth for the z-index from a ground line (grid pixels down the scene). */
export const depth = (y) => Math.round(y * 10);

/**
 * The parts of a painted scene in front of whoever stands behind them: the same painting again,
 * clipped to the part (a bridge's near rail), at the depth where that part meets the ground. Only a
 * figure whose feet are further back is covered; to everyone else it's the painting it already is.
 */
function occludersHtml(s) {
  return (s.occluders || [])
    .map((o) => `<div class="sc-front" aria-hidden="true" style="z-index:${depth(o.z)};clip-path:polygon(${o.poly.map(([x, y]) => `${f((x / s.w) * 100)}% ${f((y / s.h) * 100)}%`).join(",")})">${paint(s.img, `class="sc-px" alt="" draggable="false"`)}</div>`)
    .join("");
}

/** The scene's light on a figure: two layers shaped like its picture (see .a-light and .a-key in
 * scene.css): one that shades it, one that lights it. */
const maskOf = (src) => `-webkit-mask-image:url('${src}');mask-image:url('${src}')`;
/** A sprite's baked rim for light from one side (tools/scenes/make_rims.py): art/c-goblin.png → art/rim/c-goblin-ur.png. */
export const rimSrc = (src, side) => `art/rim/${src.replace(/^art\//, "").replace(/\.png$/, "").replace(/\//g, "-")}-${side}.png`;
/**
 * The light layers on a figure: one that shades it (.a-light), one that lights it (.a-key), and its rim
 * (.a-rim): the sprite's own edge pixels that face the light, baked per sprite and side (rim).
 */
export const lightLayer = (src, _w, _h, rim = null) =>
  `<span class="a-light" aria-hidden="true" style="${maskOf(src)}"></span><span class="a-key" aria-hidden="true" style="${maskOf(src)}"></span>${rim ? `<span class="a-rim" aria-hidden="true" data-rim="${rim}" style="${maskOf(rimSrc(src, rim))}"></span>` : ""}`;
const relight = (el, src) =>
  el.querySelectorAll(".a-light, .a-key, .a-rim").forEach((l) => l.setAttribute("style", maskOf(l.dataset.rim ? rimSrc(src, l.dataset.rim) : src)));

/**
 * How a figure is lit where it stands (tools/scenes/figure_light.py, read from the painting): the
 * direction and colour of the light, its shadow side, rim, haze and contact shadow, as CSS variables.
 * Returns [class, style] to add to the figure, or ["", ""] where there's no such light.
 */
export const figureStyle = (lit) =>
  lit
    ? [
        " lit",
        Object.entries(lit)
          .filter(([k]) => k.startsWith("--"))
          .map(([k, v]) => `${k}:${v}`)
          .join(";") + ";",
        lit.rim || "u",
      ]
    : ["", "", null];
/** A figure's light in a scene, in this light (mood), at its role's spot ("monster" or "you"). */
export const figureLight = (sceneId, mood, role) => sceneArt(sceneId, mood)?.figures?.[role] || null;

/**
 * A figure's idle loop (tools/creatures/idle/<id>.txt, played by public/css/idle.css): { cls, attrs, style,
 * img }. idle: its { img, n, holds } (SPRITES[id].idle, EMBER_ART.idle, FORK_IDLE[k]); id: the figure;
 * slot: where it stands (a fork's second path is 1). It starts its loop at a moment of its own, from its id
 * and its slot, so no two figures blink together. lead: the other guardian at a fork ({ idle, id }, for
 * slot 1): it starts half its own loop after that one's moment, so two guardians whose loops are as long
 * (two of a kind, or two species with the same rhythm) never breathe in step; loops of other lengths
 * drift in and out of step on their own. A figure whose loop isn't drawn yet stands still (no idle, img
 * null). at: how far into its loop it is when the page starts (ms).
 */
export function idleOf(idle, id, slot = 0, lead = null) {
  if (!idle) return { cls: "", attrs: "", style: "", img: null, at: 0 };
  const ms = idle.holds.reduce((a, b) => a + b, 0);
  let at;
  if (lead?.idle) at = (idleOf(lead.idle, lead.id).at + ms / 2) % ms;
  else {
    let h = 2166136261;
    for (const c of String(id)) h = Math.imul(h ^ c.charCodeAt(0), 16777619);
    at = (((h >>> 0) / 2 ** 32 + slot / 2) % 1) * ms;
  }
  return { cls: " idle", attrs: ` data-idle="${id}"`, style: `--pq-d:-${f(at / 1000)}s;`, img: idle.img, at };
}

/**
 * A creature's contact shadow, in pixel art like the creature: an ellipse on the creature's own pixel
 * grid (whole sprite pixels, hard edges, a darker core and a lighter rim), used as a mask over the
 * place's shadow colour. Where it sits: SHADOWS[look] = [middle x, feet y above the sprite's bottom,
 * width], in sprite pixels (set by hand in placing mode: shadow-placed.js), else from the sprite's own
 * footprint (SPRITES[look].sh, tools/creatures/unground.py).
 */
let SHADOWS = { ...SHADOW_PLACED };
/** Placing mode tries shadows out live. */
export const setShadowTry = (look, v) => {
  if (v) SHADOWS[look] = v;
  else SHADOWS = { ...SHADOW_PLACED, ...Object.fromEntries(Object.entries(SHADOWS).filter(([k]) => k !== look && !(k in SHADOW_PLACED))) };
};
/** Where a creature's shadow is: [middle x, feet y, width] in its sprite's pixels. */
export function shadowOf(look) {
  if (SHADOWS[look]) return SHADOWS[look];
  const sp = SPRITES[look];
  if (!sp) return null;
  const sh = sp.sh || [0.5, 0.8, 0];
  return [Math.round(sh[0] * sp.w), Math.round((sh[2] || 0) * sp.h), Math.max(4, Math.round(sh[1] * sp.w * 1.06))];
}
const shadowMasks = new Map();
/** A pixel ellipse w×h sprite pixels: its core 1, its rim 0.55 (a PNG data URL, made once per size). */
function shadowMask(w, h) {
  const key = `${w}x${h}`;
  if (shadowMasks.has(key)) return shadowMasks.get(key);
  let url = "";
  if (typeof document !== "undefined") {
    const c = document.createElement("canvas");
    c.width = w;
    c.height = h;
    const g = c.getContext("2d");
    const img = g.createImageData(w, h);
    for (let y = 0; y < h; y++)
      for (let x = 0; x < w; x++) {
        const dx = (x + 0.5 - w / 2) / (w / 2);
        const dy = (y + 0.5 - h / 2) / (h / 2);
        const r = dx * dx + dy * dy;
        img.data[(y * w + x) * 4 + 3] = r <= 0.45 ? 255 : r <= 1 ? 140 : 0;
      }
    g.putImageData(img, 0, 0);
    url = c.toDataURL();
  }
  shadowMasks.set(key, url);
  return url;
}
export function shadowHtml(sp, look) {
  const s = look && shadowOf(look);
  if (!sp || !s) return `<span class="a-shadow"></span>`;
  const [cx, up, w] = s;
  const h = Math.max(2, Math.round(w * 0.2));
  const m = shadowMask(w, h);
  const pct = (v, of) => f((v / of) * 100);
  const mask = m ? `-webkit-mask-image:url('${m}');mask-image:url('${m}');` : "";
  return `<span class="a-shadow px" data-look="${look}" style="left:${pct(Math.round(cx - w / 2), sp.w)}%;width:${pct(w, sp.w)}%;height:${pct(h, sp.h)}%;--up:${pct(up - Math.floor(h / 2), sp.h)}%;${mask}"></span>`;
}

/** A monster standing at a spot. `far` is the smaller size used at the fork. */
export function actorHtml(sceneId, monster, spot, { far = false, happy = false, cls = "", attrs = "", mood = "night" } = {}) {
  const m = SPRITES[monster];
  const [litCls, litVars, rim] = figureStyle(!far && (spot === SCENES[sceneId]?.spots?.monster || spot === SCENES[sceneId]?.spots?.perch) ? figureLight(sceneId, mood, "monster") : null);
  // A painted glade can seat its creature further off (actorScale), where its stage is.
  const s = (far ? m.fork : m.room) * (SCENES[sceneId]?.actorScale || 1);
  const w = m.w * s;
  const h = m.h * s;
  // Waiting, it plays its idle loop (its sheet of frames); won over, it's its happy picture.
  const idle = idleOf(m.idle, monster);
  const still = idle.img || m.img;
  // Won over, it stays itself (its sheet's happy pose was another drawing of it, not a frame).
  const src = still;
  return `<div class="actor${far ? " far" : ""}${happy ? " happy" : ""}${m.float ? " floats" : ""}${m.emits ? " emits" : ""}${litCls}${idle.cls} ${cls}" data-m="${monster}"${idle.attrs} ${attrs} style="${litVars}${idle.style}${place(sceneId, spot, w, h, far ? Math.round(m.float * 0.6) : m.float)}">
    ${shadowHtml(m, monster)}<img class="a-img" src="${src}" data-happy="${m.happy}" data-img="${still}" alt="" draggable="false" />${lightLayer(src, m.w, m.h, rim)}</div>`;
}

/** You, walking into the scene as your character, at the scene's "you" spot. */
export function youHtml(sceneId, hero = "wanderer", mood = "night") {
  const h = HERO_ART[hero] || HERO_ART.wanderer;
  const sc = SCENES[sceneId];
  const spot = sc?.spots?.you;
  if (!spot) return "";
  const [litCls, litVars, rim] = figureStyle(figureLight(sceneId, mood, "you"));
  const k = sc.youScale || 1;
  return `<div class="actor you${litCls}" data-hero="${hero}" style="${litVars}${place(sceneId, [spot[0] + (h.w / 2 - h.ax) * k, spot[1]], h.w * k, h.h * k)}"><span class="a-shadow"></span><img class="a-img" src="${h.img}" alt="" draggable="false" />${lightLayer(h.img, h.w, h.h, rim)}</div>`;
}

/** A character's portrait, for diamonds and the camp. */
export const heroPortrait = (hero) => (HERO_ART[hero] || HERO_ART.wanderer).portrait;

/** Old Ember is the size of her whole scene. */
// Old Ember's picture is the size of the whole scene; her feet are here in it.
export const EMBER_FEET = EMBER_ART.feet;
export const EMBER_BOX = { w: EMBER_ART.w, h: EMBER_ART.h };

/**
 * Old Ember on her hoard. In a painted hollow she sits where its stage is, at its scale (the
 * picture moved so her feet are on the spot); in the drawn one her picture covers the scene.
 */
export function emberHtml(happy = false, sceneId = "hollow", mood = "night") {
  const sc = SCENES[sceneId];
  // Asleep on her hoard she plays her idle loop, if it's drawn; won over, her happy picture.
  const idle = idleOf(EMBER_ART.idle, "ember");
  const still = idle.img || "art/ember.png";
  const src = happy ? "art/ember-happy.png" : still;
  let box = "left:0;top:0;width:100%;height:100%";
  if (sc?.painted && sc.spots?.monster) {
    const k = sc.actorScale || 1;
    const [sx, sy] = sc.spots.monster;
    const pct = (v, of) => f((v / of) * 100);
    box = `left:${pct(sx - EMBER_FEET[0] * k, sc.w)}%;top:${pct(sy - EMBER_FEET[1] * k, sc.h)}%;width:${pct(336 * k, sc.w)}%;height:${pct(187 * k, sc.h)}%;z-index:${depth(sy)}`;
  }
  const [litCls, litVars, rim] = figureStyle(sc?.painted ? figureLight(sceneId, mood, "monster") : null);
  return `<div class="actor ember${happy ? " happy" : ""}${litCls}${idle.cls}" data-m="dragon"${idle.attrs} style="${litVars}${idle.style}${box}"><img class="a-img" src="${src}" data-happy="art/ember-happy.png" data-img="${still}" alt="" draggable="false" />${lightLayer(src, 336, 187, rim)}</div>`;
}

/** Win a creature over: its eyes close in a smile, it blushes, hops for joy, hearts float up, and it
 *  steps aside to let you through. */
export function happyActor(el, { aside = true } = {}) {
  const img = el?.querySelector(".a-img");
  if (!img || el.classList.contains("happy")) return;
  el.classList.add("happy");
  // Only Old Ember turns to her happy picture (painted to match her); a creature's sheet "happy" poses
  // were other drawings of it, not a next frame, so it stays itself and hops for joy.
  if (el.classList.contains("ember")) {
    img.src = img.dataset.happy;
    relight(el, img.dataset.happy);
  }
  if (!el.querySelector(".a-hearts")) el.insertAdjacentHTML("beforeend", `<span class="a-hearts" aria-hidden="true"><i></i><i></i><i></i></span>`);
  if (aside && !el.classList.contains("ember")) setTimeout(() => el.isConnected && el.classList.add("aside"), 1100);
}

/** Back to how it was (the admin preview). */
export function calmActor(el) {
  const img = el?.querySelector(".a-img");
  if (!img) return;
  el.classList.remove("happy", "aside");
  img.src = img.dataset.img;
  relight(el, img.dataset.img);
  el.querySelector(".a-hearts")?.remove();
}

/** One of the paths at a fork (see PORTALS), with its warm light. */
export function portalHtml(sceneId, type, side, time) {
  const p = PORTALS[type];
  const [x, y] = FORK_SPOTS[side];
  const s = SCENES[sceneId];
  const g = p.glow;
  const glow = `<span class="portal-glow" style="left:${f((x / s.w) * 100)}%;top:${f(((y + g.dy) / s.h) * 100)}%;width:${f(((g.r * 2) / s.w) * 100)}%;--c:${g.color}"></span>`;
  // The same tilt-shift blur as the scene behind it, so the path sits in the same miniature.
  const [t0, t1, t2, t3] = s.light.tilt.map((t) => `${Math.round(t * 100)}%`);
  const mask = `linear-gradient(180deg,#000 0,#000 ${t0},transparent ${t1},transparent ${t2},#000 ${t3},#000 100%)`;
  const src = `art/p-${type}-${side}-${time}.png`;
  return `<img class="portal" data-portal="${type}" src="${src}" alt="" draggable="false" /><img class="portal tilt" src="${src}" alt="" draggable="false" style="-webkit-mask-image:${mask};mask-image:${mask}" />${glow}`;
}

/** The tap target over a path, in scene percentages. */
export function portalHit(sceneId, type, side) {
  const { hit } = PORTALS[type];
  const [x, y] = FORK_SPOTS[side];
  const s = SCENES[sceneId];
  return `left:${f(((x + hit.x) / s.w) * 100)}%;top:${f(((y + hit.y) / s.h) * 100)}%;width:${f((hit.w / s.w) * 100)}%;height:${f((hit.h / s.h) * 100)}%`;
}

export function relicHtml(sceneId, relic, spot, i, color = "#fff0c0") {
  const r = RELIC_ART[relic] || RELIC_ART.clover;
  // It bobs over its stone (magic); its shadow stays on the stone.
  return `<span class="relic-shadow" aria-hidden="true" style="${place(sceneId, [spot[0], spot[1] + 1.5], r.w * 2, 3)}"></span><span class="relic-art" data-i="${i}" style="${place(sceneId, spot, r.w * 2, r.h * 2)};--c:${color}"><span class="glow"></span><img src="${r.img}" alt="" draggable="false" /></span>`;
}

/**
 * A scene in a light: the painted glades come by moonlight (their own picture) and at dusk (a
 * variant: its picture and its light). Scenes without that variant are the same in any light.
 */
export function sceneArt(id, mood = "night") {
  const s = SCENES[id];
  const v = s?.variants?.[mood];
  return v ? { ...s, ...v } : s;
}

/**
 * The whole scene. `inner` goes between the picture and the light (actors, relics); `over` goes on
 * top of the light (tap targets, labels). `mood`: "dusk" or "night" (see light.js).
 */
export function sceneHtml(id, { inner = "", over = "", cls = "", label = "", mood = "night" } = {}) {
  const s = sceneArt(id, mood);
  const L = s.light;
  const [a, b, c, d] = L.tilt.map((t) => `${Math.round(t * 100)}%`);
  const mask = `linear-gradient(180deg,#000 0,#000 ${a},transparent ${b},transparent ${c},#000 ${d},#000 100%)`;
  const { shade, glow, grade } = lightSvgs(s);
  const shadows = s.shadows.length
    ? `<svg class="sc-shadows" viewBox="0 0 ${s.w * 3} ${s.h * 3}" preserveAspectRatio="none" aria-hidden="true">${s.shadows.map(([cx, cy, rx, ry, o]) => `<ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="#000" opacity="${o}"/>`).join("")}</svg>`
    : "";
  // The scene is a window onto a wider world: normally it shows the middle (core) columns, and it
  // shows more of the world when it zooms out or the screen is wide.
  return `<div class="scene ${cls}${s.painted ? " painted" : ""} lit-${s.variants || s.painted ? mood : "day"}" data-scene="${id}" style="--sw:${s.core || s.w};--ww:${s.w};--sh:${s.h};--blur:${f((L.blur / 3 / s.h) * 100)}cqh" ${label ? `role="img" aria-label="${label}"` : `aria-hidden="true"`}>
    <div class="sc-world">
    ${paint(s.img, `class="sc-px" alt="" draggable="false"`)}
    ${paint(s.img, `class="sc-tilt" alt="" draggable="false" style="-webkit-mask-image:${mask};mask-image:${mask}"`)}
    ${shadows}
    ${glow}
    <div class="sc-inner">${inner}${occludersHtml(s)}</div>
    ${shade}${grade}
    <div class="sc-dark"></div>
    <div class="sc-motes" aria-hidden="true">${motes(id, s.night, s.spots?.monster)}</div>
    ${over}
    </div>
  </div>`;
}

/** A few fireflies or sun-motes that drift, on top of the pre-scattered dust. */
function motes(id, isNight, stage) {
  const night = isNight ?? /hollow|ring|dusk|title|night/.test(id);
  const n = night ? 26 : 18;
  const s = SCENES[id];
  // Not on the creature: skip any mote that starts where it stands.
  const clear = (x, y) => !stage || !s || Math.abs((x / 100) * s.w - stage[0]) > 26 || (y / 100) * s.h < stage[1] - 50 || (y / 100) * s.h > stage[1] + 6;
  let out = "";
  for (let k = 0; k < n; k++) {
    const x = (k * 37 + 11) % 96 + 2;
    const y = 30 + ((k * 53) % 55);
    if (!clear(x, y)) continue;
    out += `<i style="--x:${x}%;--y:${y}%;--d:${(5 + (k % 5) * 1.3).toFixed(1)}s;--delay:${(-k * 1.7).toFixed(1)}s;--dx:${(k % 2 ? 1 : -1) * (8 + (k % 4) * 5)}px"${night ? ' class="ff"' : ""}></i>`;
  }
  return out;
}

export const scene = (id) => SCENES[id];
export const portraitSrc = (id) => (id?.startsWith("hero-") ? (HERO_ART[id.slice(5)] || HERO_ART.wanderer).portrait : PORTRAITS[id] || PORTRAITS.spirit);
export { SCENES, SPRITES, PORTRAITS, RELIC_ART, PORTALS, FORK_SPOTS, HERO_ART, EMBER_ART };
