// The light in the wood. Every painted place comes in two lights: the fork's own soft teal dusk with
// warm sunbeams through the leaves, and deep moonlight. The player picks in Settings:
//   auto  – dusk into night: the walk starts in the last of the daylight and goes on into the night
//   dusk  – always the soft dusk
//   night – always moonlight
import { store } from "../store.js";

export const LIGHTS = {
  auto: { name: "Dusk into night", note: "The walk begins in the last light and goes on into the night." },
  dusk: { name: "Always dusk", note: "Soft teal light and warm sunbeams through the leaves." },
  night: { name: "Always moonlight", note: "Moonlight, lanterns and glowing mushrooms." },
};

/**
 * The light for a place in the walk: "dusk" or "night".
 * place: "title" | "map" | "fork" | "glade" | "nook"; floor: the glade (0-based) or the fork's glade.
 * The map passes last = true before Old Ember.
 */
/** The dev shortcuts (#/dev/…?light=) show a screen in one light without touching Settings. */
let override = null;
export const setLightOverride = (light) => (override = light === "dusk" || light === "night" ? light : null);

export function moodFor(place, { floor = 0, floors = 6, last = false } = {}) {
  const pref = override || store.lighting;
  if (pref !== "auto") return pref;
  switch (place) {
    case "title":
      return "night"; // the round door under the moon
    case "map":
      return last ? "night" : "dusk";
    case "nook":
      return "dusk"; // between glades 2 and 3: the last of the light
    case "fork":
      return floor > (floors - 2) / 2 ? "night" : "dusk";
    default:
      // The glades: the first half by dusk, the rest (and Old Ember's hollow) by moonlight.
      return floor < floors / 2 ? "dusk" : "night";
  }
}
