// Shadows (#/shadows, from Settings): each animal's contact shadow, set on the animal alone (not in any
// place: one shadow per animal, used in every glade and at every fork). The animal is drawn big on plain
// ground; drag its shadow by whole sprite pixels, − and + for its width, then copy to send on. Nothing
// here changes the game; your shadows are kept in this browser until you clear them.
import { SPRITES } from "../forest/art-data.js";
import { shadowOf, shadowHtml, setShadowTry } from "../forest/scene.js";
import { CREATURES } from "../rules.js";
import { esc } from "../util.js";

const KEY = "pocketquest:shadows";
export const loadShadows = () => {
  try {
    return JSON.parse(localStorage.getItem(KEY)) || {};
  } catch {
    return {};
  }
};
const save = (v) => {
  try {
    localStorage.setItem(KEY, JSON.stringify(v));
  } catch {}
};

export function renderShadows({ view, setCleanup }) {
  const looks = Object.keys(CREATURES).filter((l) => SPRITES[l]);
  let shadows = loadShadows(); // { look: [middle x, feet y above the sprite's bottom, width] }, sprite px
  for (const [l, v] of Object.entries(shadows)) setShadowTry(l, v);
  let li = Math.max(0, looks.indexOf(sessionStorage.getItem("pq:shadow-look")));
  document.body.dataset.view = "place";

  view.innerHTML = `<div class="placing shadows">
    <div class="place-bar">
      <a class="btn ghost small" href="#/" aria-label="Leave">✕</a>
      <select id="sh-look" aria-label="Animal">${looks.map((l) => `<option value="${l}">${esc(CREATURES[l].name)}</option>`).join("")}</select>
      <button class="btn ghost small" id="sh-prev" type="button" aria-label="Previous animal">◀</button>
      <button class="btn ghost small" id="sh-next" type="button" aria-label="Next animal">▶</button>
      <button class="btn ghost small" id="sh-narrow" type="button" aria-label="Narrower shadow">−</button>
      <button class="btn ghost small" id="sh-wider" type="button" aria-label="Wider shadow">+</button>
    </div>
    <div class="place-stage shadow-stage"><div class="shadow-ground"><div class="actor shadow-actor" id="sh-actor"></div></div></div>
    <div class="place-foot">
      <span id="sh-info" class="small-note"></span>
      <button class="btn small" id="sh-copy-look" type="button">Copy this animal</button>
      <button class="btn small" id="sh-copy" type="button">Copy all</button>
      <button class="btn ghost small" id="sh-reset" type="button">Reset this animal</button>
      <button class="btn ghost small" id="sh-clear" type="button">Clear all</button>
    </div>
    <textarea id="sh-out" readonly rows="4" aria-label="Your shadows"></textarea>
  </div>`;
  const $ = (s) => view.querySelector(s);
  const stage = $(".shadow-stage");
  const actor = $("#sh-actor");
  let px = 8; // screen pixels per sprite pixel

  function text(only = null) {
    const list = Object.entries(shadows).filter(([l]) => !only || l === only);
    const what = only ? CREATURES[only].name : "all animals";
    if (!list.length) return `No shadows set yet for ${what}.`;
    const lines = list.map(([l, [x, y, w]]) => `shadow ${l}: middle ${x}, feet ${y}, width ${w}`);
    return `Shadows, ${what} (sprite px):\n${lines.join("\n")}\n\n${JSON.stringify({ shadows: Object.fromEntries(list) })}`;
  }

  function draw() {
    const look = looks[li];
    const sp = SPRITES[look];
    sessionStorage.setItem("pq:shadow-look", look);
    $("#sh-look").value = look;
    // As big as fits, in whole screen pixels per sprite pixel.
    px = Math.max(2, Math.floor(Math.min((stage.clientWidth - 40) / (sp.w + 8), (stage.clientHeight - 60) / (sp.h + 8))));
    Object.assign(actor.style, { width: `${sp.w * px}px`, height: `${sp.h * px}px` });
    actor.innerHTML = `${shadowHtml(sp, look)}<img class="a-img" src="${sp.img}" alt="" draggable="false" /><div class="place-handle shadow" id="sh-handle"><span>shadow</span></div>`;
    const sh = actor.querySelector(".a-shadow");
    const hd = $("#sh-handle");
    const place = () => Object.assign(hd.style, { left: `${sh.offsetLeft - 4}px`, top: `${sh.offsetTop - 4}px`, width: `${sh.offsetWidth + 8}px`, height: `${Math.max(16, sh.offsetHeight + 8)}px` });
    place();
    const [x, y, w] = shadowOf(look);
    $("#sh-info").textContent = `${CREATURES[look].name}: animal ${li + 1} of ${looks.length} · middle ${x}, feet ${y}, width ${w}${shadows[look] ? " (set)" : ""} · ${Object.keys(shadows).length} set in all`;
    $("#sh-out").value = text(look);
    hd.addEventListener("pointerdown", (e) => {
      e.preventDefault();
      hd.setPointerCapture?.(e.pointerId);
      const x0 = e.clientX;
      const y0 = e.clientY;
      const start = shadowOf(look).slice();
      let v = start;
      const move = (ev) => {
        v = [start[0] + Math.round((ev.clientX - x0) / px), start[1] - Math.round((ev.clientY - y0) / px), start[2]];
        setShadowTry(look, v);
        sh.outerHTML = shadowHtml(sp, look);
        const nsh = actor.querySelector(".a-shadow");
        Object.assign(hd.style, { left: `${nsh.offsetLeft - 4}px`, top: `${nsh.offsetTop - 4}px` });
      };
      const up = () => {
        hd.removeEventListener("pointermove", move);
        hd.removeEventListener("pointerup", up);
        if (v.join() !== start.join()) set(look, v);
        else draw();
      };
      hd.addEventListener("pointermove", move);
      hd.addEventListener("pointerup", up);
    });
  }
  function set(look, v) {
    shadows[look] = v;
    setShadowTry(look, v);
    save(shadows);
    draw();
  }

  const step = (d) => {
    li = (li + d + looks.length) % looks.length;
    draw();
  };
  $("#sh-prev").addEventListener("click", () => step(-1));
  $("#sh-next").addEventListener("click", () => step(1));
  $("#sh-look").addEventListener("change", (e) => {
    li = looks.indexOf(e.target.value);
    draw();
  });
  const widen = (d) => {
    const [x, y, w] = shadowOf(looks[li]);
    set(looks[li], [x, y, Math.max(3, w + d)]);
  };
  $("#sh-narrow").addEventListener("click", () => widen(-1));
  $("#sh-wider").addEventListener("click", () => widen(1));
  $("#sh-reset").addEventListener("click", () => {
    delete shadows[looks[li]];
    setShadowTry(looks[li], null);
    save(shadows);
    draw();
  });
  $("#sh-clear").addEventListener("click", () => {
    if (!confirm("Clear every shadow you've set?")) return;
    for (const l of Object.keys(shadows)) setShadowTry(l, null);
    shadows = {};
    save(shadows);
    draw();
  });
  const copy = async (btn, only) => {
    const t = $("#sh-out");
    t.value = text(only);
    t.select();
    const label = btn.textContent;
    try {
      await navigator.clipboard.writeText(t.value);
      btn.textContent = "Copied!";
    } catch {
      document.execCommand?.("copy");
      btn.textContent = "Select the box";
    }
    setTimeout(() => (btn.textContent = label), 1600);
  };
  $("#sh-copy-look").addEventListener("click", (e) => copy(e.currentTarget, looks[li]));
  $("#sh-copy").addEventListener("click", (e) => copy(e.currentTarget, null));
  const key = (e) => {
    if (e.target.closest("select, textarea")) return;
    if (e.key === "ArrowRight") step(1);
    if (e.key === "ArrowLeft") step(-1);
  };
  window.addEventListener("keydown", key);
  const onResize = () => draw();
  window.addEventListener("resize", onResize);
  setCleanup(() => {
    window.removeEventListener("keydown", key);
    window.removeEventListener("resize", onResize);
  });
  draw();
}
