// Today's dungeon, the same for everyone: which questions wait behind which doors, who guards them,
// and which relics lie in the nook. Questions and relics come from the schedule; monsters, door
// order and the Toadstool's letter come from a seed, so they never change for a day.
import { SCHEDULE } from "./data/schedule.js";
import { RULES } from "./config.js";
import { BESTIARY, ROLE_LOOKS, beatsArmor, shownTier } from "./rules.js";
import { room } from "./content.js";
import { hashString, seededRandom } from "./util.js";

/**
 * Which creature plays a monster at this door: one of the creatures that can play its role, at the
 * first glade and at every fork alike. A hash of its own, so it never moves the day's seed. (Looks
 * are only for show: the rules go by the monster.)
 */
export function lookFor(day, floor, door, monster) {
  const looks = ROLE_LOOKS[monster];
  return looks?.length ? looks[hashString(`look:${day}:${floor}:${door}`) % looks.length] : monster;
}

export const scheduleLength = () => SCHEDULE.length;

/** The schedule line for a day. Days past the end of the schedule wrap around. */
export function dayEntry(day) {
  const line = SCHEDULE[(((day - 1) % SCHEDULE.length) + SCHEDULE.length) % SCHEDULE.length];
  const [first, f2, f3, f4, boss, relics] = line.split(";");
  return { first, pairs: [f2.split(","), f3.split(","), f4.split(",")], boss, relics: relics.split(",") };
}

const pool = (name) => Object.keys(BESTIARY).filter((k) => BESTIARY[k].pool === name);

function shuffle(arr, rand) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

/** The first letter of an answer, the way the Letter lock reads it ("The Tempest" → T). */
export const initialOf = (name) =>
  name
    .replace(/^the\s+/i, "")
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .charAt(0)
    .toUpperCase();

/** A fair letter for the Toadstool: at least four answers, and some of them not the obvious ones.
 *  Rules 7 and before: when no letter was fair it fell back to the three most common initials,
 *  which could leave a door with only a Copper answer behind Silver armour (see fairLetters). */
function oldLetter(pid, rand) {
  const counts = new Map();
  for (const a of room(pid).answers) {
    const l = initialOf(a.name);
    if (!/[A-Z]/.test(l)) continue;
    const c = counts.get(l) || { n: 0, rare: 0 };
    c.n++;
    if (a.tier !== "c") c.rare++;
    counts.set(l, c);
  }
  const good = [...counts].filter(([, c]) => c.n >= 4 && c.rare >= 3).map(([l]) => l).sort();
  const ok = good.length ? good : [...counts].sort((a, b) => b[1].n - a[1].n).slice(0, 3).map(([l]) => l);
  return ok[Math.floor(rand() * ok.length)];
}

/**
 * Rules 8: the letters a letter lock at this door may ask for, counting every answer the lock takes
 * (by its name or an alias, as passesLetter reads them) and the ones rare enough for the armour.
 * Fair: at least four answers, three of them through the armour. A small list without a fair
 * letter gets the letters with the most answers through (never fewer than two). Empty: no letter
 * lock can be fair here.
 */
export function fairLetters(pid, armor) {
  const counts = new Map();
  for (const a of room(pid).answers) {
    const through = beatsArmor(shownTier(a.tier), armor);
    for (const l of new Set([a.name, ...a.aliases].map(initialOf))) {
      if (!/[A-Z]/.test(l)) continue;
      const c = counts.get(l) || { n: 0, through: 0 };
      c.n++;
      if (through) c.through++;
      counts.set(l, c);
    }
  }
  const fair = [...counts].filter(([, c]) => c.n >= 4 && c.through >= 3).map(([l]) => l);
  if (fair.length) return fair.sort();
  const most = Math.max(0, ...[...counts.values()].map((c) => c.through));
  return most < 2 ? [] : [...counts].filter(([, c]) => c.through === most).map(([l]) => l).sort();
}

const cache = new Map();

/** The twists that never make a glade harder: the Warm-up, and the Wisp's hint (yours to take or not). */
export const GENTLE_QUIRKS = new Set(["warmup", "bargain"]);

/** Makes a door gentle (see dungeonForDay): no armour, no twist that makes it harder, and from
 *  rules 8 (fair) no ×2 either. The #/dev shortcuts use it too, so they show what a walk does. */
export function gentleDoor(door, fair = true) {
  door.armor = "none";
  if (!GENTLE_QUIRKS.has(door.quirk)) {
    door.quirk = "warmup";
    delete door.letter;
  }
  if (fair) Object.assign(door, { mult: 1, elite: false });
  return door;
}

/**
 * The day's dungeon with this many glades (floors), for a walk played under these rules (leave
 * them out for today's). The first glades are the schedule's line for the day; any extra forks
 * borrow pairs from other days' lines (deterministically, never repeating a room that day), so a
 * 5-glade day stays exactly as it always was.
 *
 * gentle (rules 7): the first RULES.GENTLE_GLADES glades have no armour, and any twist that makes a
 * glade harder (bouncing Copper, a letter lock, two answers, Copper that pays nothing or costs gold,
 * a lantern that costs two hearts, a thick skull's Gold armour) becomes a plain Warm-up. The same
 * creatures still stand there, and the day's seed is used exactly as before, so the paths, the
 * questions and everything after glade 2 stay the same. Old walks (rules 6 and before) skip it.
 *
 * fair (rules 8): a letter lock asks for a letter from fairLetters, or, where no letter can be fair,
 * becomes a Warm-up with no armour. And no gentle glade pays ×2: with nothing harder about it, the
 * ×2 path was always the better pick, so now glade 2's fork is a choice of question.
 */
export function dungeonForDay(day, floors = RULES.FLOORS, { rules = Infinity } = {}) {
  const gentle = rules >= 7;
  const fair = rules >= 8;
  const key = `${day}:${floors}:${gentle}:${fair}`;
  if (cache.has(key)) return cache.get(key);
  const e = dayEntry(day);
  const rand = seededRandom(hashString(`pocket-quest:${day}`));
  const firsts = shuffle(pool("first"), rand);
  const plains = shuffle(pool("plain"), rand);
  const elites = shuffle(pool("elite"), rand);

  const make = (pid, monster, armor, mult, elite, floor) => {
    const door = { pid, monster, quirk: BESTIARY[monster].quirk, armor, mult, elite };
    if (door.quirk === "thick") door.armor = "g";
    // The letter is picked even for a gentle glade, and always with one draw, so the seed moves on
    // exactly as it always did.
    if (door.quirk === "letter") {
      if (!fair) door.letter = oldLetter(pid, rand);
      else {
        const ok = fairLetters(pid, door.armor);
        const x = rand();
        if (ok.length) door.letter = ok[Math.floor(x * ok.length)];
        else Object.assign(door, { quirk: "warmup", armor: "none" });
      }
    }
    if (gentle && floor < RULES.GENTLE_GLADES && monster !== "dragon") gentleDoor(door, fair);
    return door;
  };

  const levels = [{ doors: [make(e.first, firsts[0], "none", 1, false, 0)] }];
  const forks = Math.max(0, floors - 2);
  const addPair = ([plainPid, elitePid], i, r) => {
    const floor = i + 1;
    const plain = make(plainPid, plains[i % plains.length], floor === 1 ? "none" : "s", 1, false, floor);
    const elite = make(elitePid, elites[i % elites.length], floor === 1 ? "s" : "g", RULES.ELITE_MULT, true, floor);
    levels.push({ doors: r() < 0.5 ? [plain, elite] : [elite, plain] });
  };
  e.pairs.slice(0, forks).forEach((p, i) => addPair(p, i, rand));
  if (forks > e.pairs.length) {
    // Extra forks: pairs from other days' lines, with their own seed so the rest of the day never shifts.
    const used = new Set([e.first, e.boss, ...e.pairs.flat()]);
    const extra = seededRandom(hashString(`pocket-quest:${day}:extra`));
    for (let i = e.pairs.length; i < forks; i++) {
      let pair = null;
      for (let k = 1; k < SCHEDULE.length && !pair; k++) {
        const other = dayEntry(day + k * 37 + i);
        const p = other.pairs[(i + k) % other.pairs.length];
        if (!used.has(p[0]) && !used.has(p[1])) pair = p;
      }
      pair ||= e.pairs[i % e.pairs.length];
      pair.forEach((pid) => used.add(pid));
      addPair(pair, i, extra);
    }
  }
  levels.push({ doors: [{ ...make(e.boss, "dragon", "g", 1, false, levels.length), boss: true }] });

  levels.forEach((l, f) => l.doors.forEach((door, i) => (door.look = lookFor(day, f, i, door.monster))));

  const d = { day, floors: levels, relics: e.relics };
  cache.set(key, d);
  return d;
}
