// The path medals turn. Their frames come from the badge sprite sheet (BADGE_TURNS, cut by
// tools/scenes/build_badge.py): the empty medal from 15° to 90°, and where its face sits in each.
// A portrait, if given, is drawn into the face of every frame (at the forks the medals are empty: the
// guardian stands right under its medal). The frames are mirrored for the other way round.
// While you choose, the medals sway gently; the one you tap spins once.
import { BADGE_TURNS as T } from "./badge-art.js";
import { reducedMotion } from "../util.js";

const FILL = 0.8; // how much of the face the portrait fills
// Every pose in the strip, as a yaw: the mirrored ones (the other way), then the painted ones.
const POSES = [...T.frames.map((f) => -f.yaw).reverse(), ...T.frames.map((f) => f.yaw)];
const at = (yaw) => POSES.indexOf(yaw);
// Waiting: a slow sway, resting nearly face-on.
const SWAY = [15, 15, 15, 15, 30, 45, 30, 15, -15, -15, -15, -15, -30, -45, -30, -15].map(at);
const SWAY_MS = 230;
// Tapped: once all the way round (edge-on at 90°, then the far side, then round to the front).
const HALF = [15, 30, 45, 60, 75, 90, -75, -60, -45, -30, -15];
const SPIN = [...HALF, ...HALF, 15].map(at);

const load = (src) =>
  new Promise((ok, no) => {
    const i = new Image();
    i.onload = () => ok(i);
    i.onerror = no;
    i.src = src;
  });
let frames = null;
const strips = new Map();

/** Every pose of the medal with this portrait in it, side by side on one canvas. */
function strip(portrait) {
  if (!strips.has(portrait)) {
    frames ||= load(T.img);
    strips.set(
      portrait,
      Promise.all([frames, portrait ? load(portrait) : null]).then(([fr, pt]) => {
        const c = document.createElement("canvas");
        c.width = T.w * POSES.length;
        c.height = T.h;
        const g = c.getContext("2d");
        g.imageSmoothingEnabled = false;
        POSES.forEach((yaw, k) => {
          const f = T.frames.findIndex((x) => x.yaw === Math.abs(yaw));
          const flip = yaw < 0;
          g.save();
          g.translate(k * T.w + (flip ? T.w : 0), 0);
          g.scale(flip ? -1 : 1, 1);
          g.drawImage(fr, f * T.w, 0, T.w, T.h, 0, 0, T.w, T.h);
          g.restore();
          const face = T.frames[f].face;
          if (!face || !pt) return; // edge-on, or an empty medal
          let [cx, cy, a, b, ang] = face;
          if (Math.sin(ang) < 0) ang += Math.PI; // the long axis, pointing down
          if (flip) (cx = T.w - cx), (ang = Math.PI - ang);
          g.save();
          g.translate(k * T.w + cx, cy);
          g.rotate(ang - Math.PI / 2); // x: across the face, y: down it
          g.scale(b * FILL, a * FILL);
          g.drawImage(pt, -1, -1, 2, 2);
          g.restore();
        });
        return c;
      }),
    );
  }
  return strips.get(portrait);
}

const live = new Set();
let ticking = false;
function tick(now) {
  for (const p of live) {
    if (!p.el.isConnected) {
      live.delete(p);
      continue;
    }
    let k;
    if (p.spin != null) {
      // Fast at first, easing out.
      const t = (now - p.spin) / 1100;
      if (t >= 1) {
        p.spin = null;
        p.t0 = now;
        k = SWAY[0];
      } else k = SPIN[Math.min(SPIN.length - 1, Math.floor((1 - (1 - t) ** 2) * SPIN.length))];
    } else k = SWAY[Math.floor((now - p.t0) / SWAY_MS) % SWAY.length];
    if (k !== p.k) {
      p.k = k;
      p.g.clearRect(0, 0, T.w, T.h);
      p.g.drawImage(p.strip, k * T.w, 0, T.w, T.h, 0, 0, T.w, T.h);
    }
  }
  ticking = live.size > 0;
  if (ticking) requestAnimationFrame(tick);
}

/** Turn a medal (a .path-pin, with or without a .face portrait): swapped in once its frames are drawn. */
export async function turnBadge(pin, delay = 0) {
  const src = pin.querySelector(".face")?.getAttribute("src") || "";
  let s;
  try {
    s = await strip(src);
  } catch {
    return; // keep the still medal
  }
  if (!pin.isConnected) return;
  const cv = document.createElement("canvas");
  cv.className = "turn";
  cv.width = T.w;
  cv.height = T.h;
  cv.style.setProperty("--grow", String(T.w / T.front));
  cv.style.aspectRatio = `${T.w} / ${T.h}`;
  const g = cv.getContext("2d");
  g.drawImage(s, at(15) * T.w, 0, T.w, T.h, 0, 0, T.w, T.h);
  pin.append(cv);
  pin.classList.add("turning");
  if (reducedMotion()) return;
  const p = { el: pin, g, strip: s, k: at(15), t0: performance.now() - delay * 1000, spin: null };
  pin._turn = p;
  live.add(p);
  if (!ticking) {
    ticking = true;
    requestAnimationFrame(tick);
  }
}

/** The tapped medal spins once, then goes back to swaying. */
export function spinBadge(pin) {
  if (pin?._turn) pin._turn.spin = performance.now();
}
