// Bottom sheets: how to play, and settings. (No confirm() anywhere: embedded browsers block it.)
// Each sheet is a real modal: the page behind it goes inert (no taps, no Tab, hidden from screen
// readers) and stops scrolling, Tab stays inside, Escape closes it, and focus goes back where it was.
import { html, raw, $ } from "../util.js";
import { TIERS, TIER_ORDER, RANKS, BESTIARY, QUIRKS, ROLE_LOOKS, CREATURES } from "../rules.js";
import { RULES } from "../config.js";
import { store } from "../store.js";
import { sfx } from "../sfx.js";
import { coin, lantern, divider, dia, ico, heart } from "../forest/ui.js";
import { LIGHTS } from "../forest/light.js";

let lastFocus = null;
let walled = []; // what the open sheet made inert

/** Is a sheet open over the page? */
export const sheetOpen = () => Boolean($("#modal-root")?.firstChild);

export function openModal(inner, { label = "Dialog", onClose, cls = "" } = {}) {
  closeModal();
  lastFocus = document.activeElement;
  const root = $("#modal-root");
  root.innerHTML = `<div class="sheet-back" data-close><div class="sheet box ${cls}" tabindex="-1" role="dialog" aria-modal="true" aria-label="${label}"><div class="sheet-x"><button class="close" type="button" data-close aria-label="Close">${ico("close", 20)}</button></div>${inner}</div></div>`;
  const back = root.firstElementChild;
  back.addEventListener("click", (e) => {
    if (e.target === back || e.target.closest("button[data-close]")) {
      closeModal();
      onClose?.();
    }
  });
  root._onClose = onClose;
  // Everything else on the page (the toast still speaks) sits behind the sheet until it closes.
  walled = [...document.body.children].filter((el) => el !== root && el.id !== "toast" && !el.inert);
  for (const el of walled) el.inert = true;
  const doc = document.documentElement;
  doc.classList.toggle("sheet-gutter", window.innerWidth > doc.clientWidth);
  doc.classList.add("sheet-open");
  back.querySelector(".sheet").focus({ preventScroll: true });
}

export function closeModal() {
  const root = $("#modal-root");
  if (!root || !root.firstChild) return;
  root.innerHTML = "";
  root._onClose = null;
  for (const el of walled) el.inert = false;
  walled = [];
  document.documentElement.classList.remove("sheet-open", "sheet-gutter");
  // A screen redrawn under the sheet (the map in a new light) replaced the button that opened it:
  // go back to its twin, the one with the same id.
  const back = lastFocus?.isConnected ? lastFocus : lastFocus?.id ? document.getElementById(lastFocus.id) : null;
  lastFocus = null;
  back?.focus?.({ preventScroll: true });
}

/** What Tab can reach inside the open sheet (not what's folded away in a closed <details>). */
function tabStops(sheet) {
  return [...sheet.querySelectorAll('button:not([disabled]), [href], input:not([disabled]), summary, [tabindex]:not([tabindex="-1"])')].filter((el) => el.getClientRects().length);
}

document.addEventListener("keydown", (e) => {
  if (!sheetOpen()) return;
  if (e.key === "Escape") {
    const fn = $("#modal-root")._onClose;
    closeModal();
    fn?.();
  } else if (e.key === "Tab") {
    // Round and round inside the sheet.
    const sheet = $("#modal-root .sheet");
    const stops = tabStops(sheet);
    if (!stops.length) return e.preventDefault();
    const at = stops.indexOf(document.activeElement);
    const next = e.shiftKey ? (at <= 0 ? stops.at(-1) : null) : at === -1 || at === stops.length - 1 ? stops[0] : null;
    if (next) {
      e.preventDefault();
      next.focus();
    }
  }
});

// One row per twist: the glade-1 creatures all play the same Warm-up, so they share one.
const CAST = [["bunny", "slime"], "goblin", "toad", "bat", "bones", "troll", "wisp", "mimic", "dragon"];

/** "a, b or c" */
const anyOf = (xs) => (xs.length > 1 ? `${xs.slice(0, -1).join(", ")} or ${xs.at(-1)}` : xs[0]);

export function showHelp({ onClose } = {}) {
  store.seenHelp = true;
  const tiers = TIER_ORDER.map((t) => html`<div>${raw(coin(t, 18))}<span><b>${TIERS[t].name}</b> · ${TIERS[t].gold} gold. ${TIERS[t].blurb}</span></div>`).join("");
  // A row is a role, or roles that play the same twist: every creature that can play them.
  const looks = (row) => [row].flat().flatMap((k) => (ROLE_LOOKS[k]?.length ? ROLE_LOOKS[k] : [k]));
  const names = (row) => anyOf(looks(row).map((c) => CREATURES[c]?.name || BESTIARY[c].name));
  const faces = (row) => looks(row).map((c) => dia(c)).join("");
  // The glade-1 creatures only ever stand in a gentle glade (rules 7): there they play a Warm-up.
  const twist = (k) => QUIRKS[BESTIARY[k].pool === "first" ? "warmup" : BESTIARY[k].quirk].short;
  const cast = CAST.map((row) => {
    const k = [row].flat()[0];
    return html`<div><span class="faces">${raw(faces(row))}</span><span><b>${names(row)}</b>${BESTIARY[k].pool === "elite" ? " (×2 gold)" : ""}: ${twist(k)}</span></div>`;
  }).join("");
  const gentle = RULES.GENTLE_GLADES;
  // The Wisp's hint is the one twist a gentle glade keeps (dungeon.js GENTLE_QUIRKS), in whichever creature plays it.
  const hinters = names("wisp");
  openModal(
    html`<div class="sheet-head"><div class="cap">Before you go</div><h2>How the walk works</h2>${raw(divider(40))}</div>
      <ol class="rules">
        <li><span class="ic">${raw(dia("mossbunny"))}</span><div><h3>Pick a path</h3><p>${RULES.FLOORS} glades a day, the same for everyone. At each fork, tap the path you like the look of.</p></div></li>
        <li><span class="ic"><span class="row" style="gap:2px">${raw(coin("c", 12) + coin("s", 12) + coin("g", 12))}</span></span><div><h3>Name something rare</h3><p>The fewer people who thought of it, the more gold it pays. In the first ${gentle} glades any right answer wins. From glade ${gentle + 1} every creature wears armour, and a common answer just bounces off.</p></div></li>
        <li><span class="ic">${raw(lantern(24))}</span><div><h3>Mind the lantern</h3><p>Wrong guesses are free. Only a burnt-out lantern costs you a heart.</p></div></li>
      </ol>
      <details class="fine">
        <summary>The finer print</summary>
        <h4 class="cap">Loot</h4>
        <div class="tier-list">${raw(tiers)}</div>
        <p>The first ${gentle} glades are gentle: no armour, and nothing that makes them harder (a ${hinters} may still offer you a hint, for half the gold). From glade ${gentle + 1} every creature wears armour: Silver or better gets past the plain path, Gold or better past the <b>×2</b> path and Old Ember. A right answer that's too common just bounces off: no gold, but no heart lost either (though the ${names("mimic")} still takes 20 gold for a Copper). From glade ${gentle + 1}, the path marked <b>×2</b> pays double.</p>
        <h4 class="cap">Who you'll meet</h4>
        <p>In the first ${gentle} glades everyone plays a gentle Warm-up (a ${hinters} may still offer a hint). From glade ${gentle + 1}, each creature plays its own twist:</p>
        <div class="cast-list">${raw(cast)}</div>
        <p>After glade 2 you take one charm from the <b>Wishing Stones</b>.</p>
        <p><b>Old Ember</b> guards the hoard in glade ${RULES.FLOORS}. She has eaten the five most common answers. Land ${RULES.BOSS_STRIKES} strikes of Gold or better before the lantern dies and the hoard is yours: +${RULES.VAULT_BONUS} gold, and +${RULES.HEART_BONUS} for each ${raw(heart(true, 12))} left. If it dies first, you slip home with what you found.</p>
        <p><b>Your purse:</b> the gold from each day's first walk is saved. Spend it at the <b>Camp</b> on someone new to walk as: a Fox Scout who can listen in at a fork to hear the question first, a Lamplighter with a bigger lantern, and more.</p>
        <p>You have ${RULES.HEARTS} hearts. Lose them all and the walk ends, but you keep every coin. The lantern burns ${RULES.CANDLE} seconds a glade and ${RULES.BOSS_CANDLE} at Old Ember's (${RULES.CANDLE_HARD} and ${RULES.BOSS_CANDLE_HARD} in hard mode, which also skips typo help). A walk takes about three minutes.</p>
        <p>Your title for the day: ${RANKS.map((r) => r.name).join(" → ")}.</p>
      </details>
      <button class="btn" type="button" data-close>Got it</button>`,
    { label: "How to play", onClose },
  );
}

export function showSettings({ onClose } = {}) {
  openModal(
    html`<div class="sheet-head"><div class="cap">Your lantern, your way</div><h2>Settings</h2>${raw(divider(40))}</div>
      <label class="setting"><span><b>Sound</b><small>Coins, rustles and a little fanfare.</small></span><span class="switch"><input type="checkbox" id="set-sound" ${sfx.muted ? "" : "checked"} /><i></i></span></label>
      <div class="setting light-setting"><span><b>Light</b><small id="light-note">${LIGHTS[store.lighting].note}</small></span>
        <div class="light-pick" role="radiogroup" aria-label="Light">${raw(
          Object.entries(LIGHTS)
            .map(([k, l]) => `<button type="button" role="radio" aria-checked="${store.lighting === k}" data-light="${k}"><span class="thumb ${k}" aria-hidden="true"><img src="art/glade/meadow-dusk.webp" alt="" /><img src="art/glade/meadow.webp" alt="" /></span><span>${l.name}</span></button>`)
            .join(""),
        )}</div>
      </div>
      <label class="setting"><span><b>Hard mode</b><small>A ${RULES.CANDLE_HARD}-second lantern (${RULES.BOSS_CANDLE_HARD} at Old Ember's) and no typo help. Starts with your next walk.</small></span><span class="switch"><input type="checkbox" id="set-hard" ${store.hardMode ? "checked" : ""} /><i></i></span></label>
      <div class="setting"><span><b>How to play</b><small>The rules, the loot and who lives in the wood.</small></span><button class="btn ghost small" type="button" id="set-help">Open</button></div>
      <div class="setting"><span><b>Past walks</b><small>Every walk so far, and your hoard.</small></span><a class="btn ghost small" href="#/archive">Open</a></div>
      <div class="setting"><span><b>Placing mode</b><small>Drag the creatures at the forks to where they should stand, then copy the spots.</small></span><a class="btn ghost small" href="#/place">Open</a></div>
      <div class="setting"><span><b>Shadows</b><small>Set each animal's shadow on the animal alone, then copy it.</small></span><a class="btn ghost small" href="#/shadows">Open</a></div>
      <p class="small-note center" style="margin-top:18px">Your walks and settings are kept only in this browser.</p>
      <button class="btn" type="button" data-close>Done</button>`,
    { label: "Settings", onClose },
  );
  const root = $("#modal-root");
  root.querySelector("#set-sound").addEventListener("change", (e) => {
    if (e.target.checked === sfx.muted) sfx.toggle();
    sfx.tap();
    window.dispatchEvent(new Event("pq:paint-sfx"));
  });
  root.querySelector("#set-hard").addEventListener("change", (e) => {
    store.hardMode = e.target.checked;
    sfx.tap();
  });
  // The light: redraw whatever is on screen in it straight away.
  for (const b of root.querySelectorAll("[data-light]"))
    b.addEventListener("click", () => {
      if (store.lighting === b.dataset.light) return;
      store.lighting = b.dataset.light;
      sfx.tap();
      for (const o of root.querySelectorAll("[data-light]")) o.setAttribute("aria-checked", String(o === b));
      root.querySelector("#light-note").textContent = LIGHTS[store.lighting].note;
      window.dispatchEvent(new Event("pq:relight"));
    });
  root.querySelector("#set-help").addEventListener("click", () => showHelp({ onClose }));
  root.querySelector('a[href="#/archive"]').addEventListener("click", () => closeModal());
  root.querySelector('a[href="#/place"]').addEventListener("click", () => closeModal());
  root.querySelector('a[href="#/shadows"]').addEventListener("click", () => closeModal());
}
