// The test shortcuts: open any screen of the walk straight away, in any order, in either light, with any
// creature at any glade or fork. Each one is a walk made to order (never saved, never sent anywhere),
// played up to that screen through the real game. On this computer, or with the admin unlocked.
// How to use them (and tools/shots.mjs, which screenshots them): .claude/skills/pocket-quest-visual-qa.
//
//   #/dev                                              every shortcut, as links
//   #/dev/title?light=dusk                             the start screen
//   #/dev/map?at=start|end&light=night                 the map, before glade 1 or before Old Ember
//   #/dev/glade?place=bridge&look=goblin&light=dusk    a glade and its creature (place: meadow, pond,
//              [&quirk=letter&armor=s&hero=fox&then=answer:g|answer:c|miss]    bridge, stones, ring, hollow)
//   #/dev/fork?place=willow&looks=goblin,wisp&light=night[&pick=0|1&floor=3]   a fork, its two guardians
//   #/dev/nook?light=dusk                              the Wishing Stones
//   #/dev/ember?light=night[&then=answer:e]            Old Ember on her hoard
//   #/dev/home?bot=keen|casual|expert&seed=3            the ledger after a walk a bot played
//   #/dev/archive · #/dev/camp · #/dev/help · #/dev/settings   the other pages, and the two sheets
//
// Everywhere: day (whose questions, default 5), light (dusk | night, default the Settings one), hero,
// still=0 (let the lantern burn; by default it stays full so screenshots are steady).
import { html, raw, esc } from "../util.js";
import { renderDelve } from "./delve.js";
import { renderGate } from "./gate.js";
import { dungeonForDay, gentleDoor, fairLetters } from "../dungeon.js";
import { room } from "../content.js";
import { spellingFor, RULES_VERSION } from "../engine.js";
import { BESTIARY, CREATURES, HEROES, QUIRKS, ARMOR } from "../rules.js";
import { RULES } from "../config.js";
import { setLightOverride } from "../forest/light.js";
import { FORK_IDS } from "../forest/fork-scene.js";
import { botRun } from "../bots.js";
import { seededRandom } from "../util.js";
import { rebuildActions } from "./admin.js";
import { rememberPractice, renderLedgerFor } from "./ledger.js";
import { renderArchive } from "./archive.js";
import { renderCamp } from "./camp.js";
import { showHelp, showSettings } from "./modals.js";

/** The glades' places, and the glade each one is on a normal walk. */
const PLACES = ["meadow", "pond", "bridge", "stones", "ring", "hollow"];
const LOOKS = Object.keys(CREATURES);
const last = () => RULES.FLOORS - 1;
const floorOf = (place) => (place === "meadow" ? 0 : place === "hollow" ? last() : Math.min(last() - 1, Math.max(1, PLACES.indexOf(place))));

/** The day's walk, with every glade before `floor` turned into a Warm-up that any right answer passes. */
function walkFor(day, floor) {
  const d = structuredClone(dungeonForDay(day));
  d.floors.forEach((f, fi) => {
    if (fi < floor)
      for (const x of f.doors) {
        x.quirk = "warmup";
        x.armor = "none";
        delete x.letter;
      }
  });
  return d;
}

/**
 * Put a creature at a door: its role, and the twist (quirk) and armour asked for, or the natural ones.
 * The door takes the role's own path, the way dungeonForDay builds it: an elite (×2) role walks the
 * elite path with Gold armour, the rest the plain path (Silver), a Thick skull always wears Gold.
 * In a gentle glade the natural ones are made gentle the way a walk does (gentleDoor), so a Wisp
 * there keeps its hint; a twist asked for there keeps no armour (but a Thick skull's) and no ×2.
 */
function cast(door, look, { quirk, armor, floor }) {
  const role = CREATURES[look]?.role;
  if (!role) return door;
  const elite = BESTIARY[role].pool === "elite";
  const out = { ...door, look, monster: role, quirk: QUIRKS[quirk] ? quirk : BESTIARY[role].quirk, elite, mult: elite ? RULES.ELITE_MULT : 1 };
  out.armor = out.quirk === "thick" || elite ? "g" : "s";
  if (floor < RULES.GENTLE_GLADES) {
    if (QUIRKS[quirk]) Object.assign(out, { armor: out.quirk === "thick" ? "g" : "none", elite: false, mult: 1 });
    else gentleDoor(out);
  }
  if (ARMOR[armor]) out.armor = armor;
  if (out.quirk === "letter") out.letter = fairLetters(door.pid, out.armor)[0] || room(door.pid).answers[0].name.replace(/^the\s+/i, "").charAt(0).toUpperCase();
  else delete out.letter;
  return out;
}

/** The actions that walk a run up to the door of glade `floor` (a right answer each, a quiet charm). */
/** How a door's room takes answer a: its name, or an alias that fits a letter the room wants (rules 8), or null. */
const sayAt = (door, a) => spellingFor({ rules: RULES_VERSION }, { pid: door.pid, quirk: door.quirk, letter: door.letter, answers: [] }, a.rank);

function actionsTo(d, floor) {
  const acts = [];
  const charm = Math.max(0, d.relics.findIndex((r) => !["map", "rod", "tooth"].includes(r)));
  for (let f = 0; f < floor; f++) {
    acts.push({ t: "door", i: 0 });
    const door = d.floors[f].doors[0];
    acts.push({ t: "answer", text: room(door.pid).answers.map((a) => sayAt(door, a)).find(Boolean) });
    // The Wishing Stones come right after glade 2.
    if (f === 1) acts.push({ t: "relic", i: charm });
  }
  return acts;
}

/** After the screen is up: answer with a given rarity (answer:c|s|g|e|j), a wrong answer (miss), or tap a path. */
function thenDo(view, q) {
  const then = q.get("then") || "";
  const pick = q.get("pick");
  setTimeout(() => {
    if (pick === "0" || pick === "1") view.querySelector(`.path-pin[data-pick="${pick}"], .art-hit[data-pick="${pick}"]`)?.click();
    const input = view.querySelector("#answer");
    if (!input || !then) return;
    let text = "Not a real answer at all";
    const m = then.match(/^answer:([cfsgej])$/);
    if (m) {
      const door = window.__pqDevDoor;
      const answers = door ? room(door.pid).answers.filter((a) => sayAt(door, a)) : [];
      const a = answers.find((x) => x.tier === m[1]) || answers[0];
      text = a ? sayAt(door, a) : text;
    }
    input.value = text;
    input.form?.requestSubmit();
  }, 700);
}

function index(view) {
  const q = (o) => new URLSearchParams(o).toString();
  const link = (path, o, label) => html`<a href="#/dev/${path}?${q(o)}">${label}</a>`;
  const lights = ["dusk", "night"];
  view.innerHTML = html`<div class="page"><div class="page-head"><h1>Test shortcuts</h1>
    <p class="muted">Any screen, in any order. A made-to-order walk each time, never saved. See .claude/skills/pocket-quest-visual-qa.</p></div>
    <div class="box" style="padding:14px;display:grid;gap:10px;font-size:14px">
      <div><b>Start and map</b>: ${raw(lights.map((l) => link("title", { light: l }, `title (${l})`) + " · " + link("map", { at: "start", light: l }, `map (${l})`) + " · " + link("map", { at: "end", light: l }, `map before Old Ember (${l})`)).join(" · "))}</div>
      <div><b>Wishing Stones and Old Ember</b>: ${raw(lights.map((l) => link("nook", { light: l }, `stones (${l})`) + " · " + link("ember", { light: l }, `Old Ember (${l})`)).join(" · "))}</div>
      ${raw(
        PLACES.filter((p) => p !== "hollow")
          .map((p) => html`<div><b>${p}</b>: ${raw(lights.map((l) => LOOKS.map((k) => link("glade", { place: p, look: k, light: l }, k)).join(" ") + ` <span class="muted">(${l})</span>`).join("<br />"))}</div>`)
          .join(""),
      )}
      ${raw(FORK_IDS.map((f) => html`<div><b>fork: ${f}</b>: ${raw(lights.map((l) => link("fork", { place: f, looks: "goblin,wisp", light: l }, `goblin + wisp (${l})`) + " · " + link("fork", { place: f, looks: "tortoise,otter", light: l, pick: 1 }, `tortoise + otter, picked (${l})`)).join(" · "))}</div>`).join(""))}
    </div></div>`;
}

export function renderDev(ctx, screen, q) {
  const { view } = ctx;
  const day = Math.max(1, Number(q.get("day")) || 5);
  setLightOverride(q.get("light"));
  const hero = HEROES[q.get("hero")] ? q.get("hero") : undefined;
  const still = q.get("still") !== "0";
  document.body.dataset.view = "walk";

  if (!screen) {
    document.body.dataset.view = "page";
    return index(view);
  }
  // The pages round the walk.
  if (screen === "home") {
    document.body.dataset.view = "home";
    const kind = ["casual", "keen", "expert"].includes(q.get("bot")) ? q.get("bot") : "keen";
    const s = botRun(day, kind, seededRandom(Number(q.get("seed")) || 3));
    rememberPractice(day, { day, done: true, hard: false, rules: s.rules, floors: s.floors, hero: s.hero, actions: rebuildActions(day, s), gold: s.gold, ending: s.ending });
    return renderLedgerFor(ctx, day, "test", { sample: true });
  }
  if (screen === "archive" || screen === "camp") {
    document.body.dataset.view = "page";
    if (q.get("light")) document.body.dataset.light = q.get("light") === "night" ? "night" : "dusk";
    return screen === "archive" ? renderArchive(ctx) : renderCamp(ctx);
  }
  if (screen === "help" || screen === "settings") {
    // Over the map, where they open from.
    renderDev(ctx, "map", q);
    return setTimeout(() => (screen === "help" ? showHelp() : showSettings()), 400);
  }
  if (screen === "title") {
    document.body.dataset.view = "title";
    return ctx.setCleanup(renderGate({ view, day, mode: "dev", onStart: () => {} }));
  }

  let floor = 0;
  let enter = false;
  let d;
  let glade = null;
  let fork = null;
  if (screen === "glade") {
    glade = PLACES.includes(q.get("place")) ? q.get("place") : "meadow";
    floor = Number.isInteger(Number(q.get("floor"))) && q.get("floor") ? Math.min(last(), Math.max(0, Number(q.get("floor")))) : floorOf(glade);
    if (glade === "hollow") floor = last();
    d = walkFor(day, floor);
    const look = q.get("look");
    if (floor !== last() && CREATURES[look]) d.floors[floor].doors[0] = cast(d.floors[floor].doors[0], look, { quirk: q.get("quirk"), armor: q.get("armor"), floor });
    enter = true;
  } else if (screen === "ember") {
    floor = last();
    glade = "hollow";
    d = walkFor(day, floor);
    enter = true;
  } else if (screen === "fork") {
    fork = FORK_IDS.includes(q.get("place")) ? q.get("place") : FORK_IDS[0];
    floor = Math.min(last() - 1, Math.max(1, Number(q.get("floor")) || 1));
    d = walkFor(day, floor);
    const looks = (q.get("looks") || "").split(",");
    d.floors[floor].doors = d.floors[floor].doors.map((door, i) => (CREATURES[looks[i]] ? cast(door, looks[i], { quirk: q.get("quirk"), armor: q.get("armor"), floor }) : door));
  } else if (screen === "nook") {
    floor = 2;
    d = walkFor(day, floor);
  } else if (screen === "map") {
    floor = q.get("at") === "end" ? last() : 0;
    d = walkFor(day, floor);
  } else {
    view.innerHTML = html`<div class="page"><p>No such shortcut: ${esc(screen)}. <a href="#/dev">All shortcuts</a></p></div>`;
    return;
  }

  let actions = actionsTo(d, floor);
  // The Wishing Stones come right after glade 2: stop before the charm.
  if (screen === "nook") actions = actions.filter((a) => a.t !== "relic");
  if (enter) actions.push({ t: "door", i: 0 });
  // For then=answer:…, the room's question.
  window.__pqDevPid = enter ? d.floors[floor].doors[0].pid : null;
  window.__pqDevDoor = enter ? d.floors[floor].doors[0] : null;
  ctx.setCleanup(renderDelve({ view, day, mode: "dev", dev: { dungeon: d, actions, hero, floor, glade, fork, still }, onDone: () => {} }));
  thenDo(view, q);
}
