// The walk: the map → a fork → a glade → the Wishing Stones → … → Old Ember → home.
// The engine decides what happens; this file only shows it. Every creature asks its question out
// loud, watches you type, reacts to what you say, and plays by its own quirk.
import { html, raw, esc, toast, reducedMotion, pct, todayDay } from "../util.js";
import { apply, replay, currentRoom, candleSeconds, floorReached, needed, counts, canPeek, wouldTake, spellingFor } from "../engine.js";
import { room, find, suggest, recognise, warmLexicon } from "../content.js";
import { TIERS, HEROES, shownTier, ARMOR, RELICS, CATEGORIES, QUIRKS, beast, relicText, relicIdle, emberStrikes, dowsing } from "../rules.js";
import { RULES } from "../config.js";
import { store, newRunRecord, personalStats, takePick, stillCounts } from "../store.js";
import { submitRun, fetchStats, clockLooksOff } from "../stats.js";
import { quipFor } from "../quips.js";
import { sfx } from "../sfx.js";
import { burst, rain, drift, centerOf, flyTo } from "../fx.js";
import { rememberPractice } from "./ledger.js";
import { showCamp, purseChip, heroPortrait } from "./camp.js";
import { showHelp, showSettings, sheetOpen } from "./modals.js";
import { tickNextWalk } from "./gate.js";
import { EMBER_BOX, EMBER_ART, sceneArt } from "../forest/scene.js";
import { moodFor } from "../forest/light.js";
import { cheerFor, voiceFor, asSentence } from "../voice.js";
import { REACT, needsLine, lanternSecs, resultLines } from "../walk-words.js";
import { sceneHtml, actorHtml, emberHtml, relicHtml, youHtml, happyActor, place, SCENES, SPRITES, HERO_ART, RELIC_ART } from "../forest/scene.js";
import { coin, heart, lantern, leaf, dia, hand, lanternMeter, ico } from "../forest/ui.js";
import { startArtParticles } from "../forest/particles.js";
import { FORKS, atLight, forkFor, forkPainting, forkSceneHtml, forkView, forkSources, badgeHtml, BADGE, badgeAt, tagAt, cardAt, guardBox } from "../forest/fork-scene.js";
import { turnBadge, spinBadge } from "../forest/badge-turn.js";
import { MAP, paintedMapFits, stopOf, mapSceneHtml, mapView, mapSources, mapArea, travellerAt, markerSize, besideMarker, underMarkers, tagOffMarkers } from "../forest/map-scene.js";

// Which place each glade is in, and the fork before it: the day goes from morning to night.
// The places a walk passes through, morning to night. The first glade is the meadow and the last is
// Old Ember's hollow; the glades between are spread over the rest, however many glades a walk has.
const MIDDLE_GLADES = ["pond", "bridge", "stones", "ring"];
function gladeScene(floor, floors) {
  if (floor === 0) return "meadow";
  if (floor === floors - 1) return "hollow";
  const m = floors - 2;
  const i = m <= MIDDLE_GLADES.length ? Math.round(((floor - 1) * (MIDDLE_GLADES.length - 1)) / Math.max(1, m - 1)) : (floor - 1) % MIDDLE_GLADES.length;
  return MIDDLE_GLADES[m === 1 ? 1 : i];
}
/**
 * Where a glade's creature stands: its stage, or (a bridge) up on the handrail for a small creature that
 * would vanish behind the rail. Heavy creatures (a tortoise, a badger) never climb up there.
 */
export function stageFor(sc, look) {
  const sp = SPRITES[look];
  const small = sp && sp.h * sp.room * (sc.actorScale || 1) < 24 && !["tortoise", "badger", "stomp"].includes(look);
  return sc.spots.perch && small ? sc.spots.perch : sc.spots.monster;
}
/** A letter lock's question: "…, starting with “C”." — unless the question already asks for that letter. */
const withLetter = (q, letter) => (new RegExp(`start(s|ing)? with (the letter )?["“']?${letter}\\b`, "i").test(q) ? q : `${q.replace(/\.$/, "")}, starting with “${letter}”.`);
export const RELIC_COLOR = { draught: "#ff9a8a", helm: "#c8d4e8", candle: "#ffe7a0", map: "#e9dcc0", rod: "#c89a6a", coin: "#ffd76a", tooth: "#fff3c4", clover: "#8fffa0" };

const WORDS = ["One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine"];
const pickOne = (arr) => arr[Math.floor(Math.random() * arr.length)];
const HIT_MOOD = { c: "hop", f: "hop", s: "hop", g: "hop", e: "hop", j: "hop" };
const RARE = (t) => t === "g" || t === "e" || t === "j";
// Short words for a tier, for when there's no crowd to count.
const TIER_SHORT = { c: "what most people say", f: "the trap everyone reaches for", s: "a good find", g: "genuinely uncommon", e: "true obscurity", j: "the glade's hidden treasure" };
const cap1 = (t) => t.charAt(0).toUpperCase() + t.slice(1);

/** A smooth, organic wobble for the lantern: layered sines with random phases. */
function makeNoise() {
  const ph = Array.from({ length: 4 }, () => Math.random() * 1000);
  return (t) => (Math.sin(t * 7.3 + ph[0]) * 0.5 + Math.sin(t * 13.1 + ph[1]) * 0.3 + Math.sin(t * 23.7 + ph[2]) * 0.15 + Math.sin(t * 2.1 + ph[3]) * 0.4) / 1.35;
}

/**
 * A day's walk. dev (the test shortcuts, views/dev.js): a walk made to order, never saved: { dungeon,
 * actions, hero, floor (the glade it's about), glade (that glade's place), fork (that fork's place),
 * still (the lantern never burns down) }.
 */
export function renderDelve({ view, day, mode, onDone, dev = null }) {
  const persistent = !dev && (mode === "today" || mode === "archive");
  let rec = persistent ? store.run(day) : null;
  if (!rec) {
    // Only today's walk can count (a title left open since yesterday never gets this far: app.js).
    rec = newRunRecord(day, mode === "today" && !dev && day === todayDay());
    if (dev) Object.assign(rec, { hard: false, hero: dev.hero || rec.hero, actions: [...(dev.actions || [])] });
    if (persistent) store.saveRun(rec);
  }
  // Before the first step the walk takes whoever is picked at the Camp (a dev walk keeps its own).
  const unsettled = () => !dev && !rec.actions.length;
  if (!dev && takePick(rec) && persistent) store.saveRun(rec);
  const rebuild = () => replay(day, rec.actions, { hard: rec.hard, rules: rec.rules || 1, floors: rec.floors, hero: rec.hero, dungeon: dev?.dungeon });
  let s = rebuild();
  let alive = true;
  let busy = false;
  let tick = null;
  let nextTick = null; // the map's "a new walk opens in…"
  let lastSecond = null;
  let crowd = null;
  let focus = null; // the part of the scene that must stay visible: [top, bottom] as fractions
  let clearX = null; // a world x that must stay left of a wide screen's panel (the creature's far side)
  const timers = new Set();

  const later = (fn, ms) => {
    const t = setTimeout(() => {
      timers.delete(t);
      if (alive) fn();
    }, ms);
    timers.add(t);
    return t;
  };
  const save = () => persistent && store.saveRun(rec);
  // Build the wrong-answer lexicon while nothing is happening, not on the first miss.
  (window.requestIdleCallback || ((fn) => setTimeout(fn, 1500)))(() => warmLexicon(), { timeout: 4000 });
  // How many people said what (only with the stats server, and only once enough have walked).
  fetchStats(day).then((st) => {
    if (st && st.total >= 10) crowd = st;
  });
  function dispatch(action) {
    const ev = apply(s, action);
    if (!ev) return null;
    // When the walk was begun: it counts only if that was on its own day (stillCounts in store.js).
    if (!rec.actions.length) rec.begunAt = Date.now();
    rec.actions.push(action);
    save();
    return ev;
  }

  view.innerHTML = `<div class="walk" id="walk">
    <div class="walk-scene" id="wscene"></div>
    <div class="walk-ui">
      <div class="glade-row" id="glades" aria-label="Today's glades"></div>
      <div class="stack" id="stack"></div>
      <div class="status bar" id="status"></div>
    </div>
  </div>`;
  const walk = view.querySelector("#walk");
  const wscene = view.querySelector("#wscene");
  const stack = view.querySelector("#stack");
  const status = view.querySelector("#status");

  // ---------- Scene, and keeping the important part of it in view ----------

  let lights = [];
  const last = s.floors - 1; // Old Ember's glade
  /** keep: the part to keep in view (see fit). clear: a world x that must stay left of a wide screen's panel. */
  function setScene(id, { inner = "", over = "", label = "", enter = false, keep = [0.15, 0.6], clear = null, you = true, mood = "night" } = {}) {
    wscene.innerHTML = sceneHtml(id, { inner: inner + (you ? youHtml(id, s.hero, mood) : ""), over, label, mood }) + `<div class="fade"></div>`;
    onMap(false);
    walk.style.setProperty("--bg", `url("${new URL(sceneArt(id, mood).img, location.href).href}")`);
    lights = [...wscene.querySelectorAll(".sc-glow, .sc-dark")];
    focus = keep;
    clearX = clear;
    wscene.classList.remove("enter");
    if (enter && !reducedMotion()) {
      void wscene.offsetWidth;
      wscene.classList.add("enter");
      // Off again once it's played, or a later screen-shake would restart it.
      later(() => {
        wscene.classList.remove("enter");
        requestAnimationFrame(fit);
      }, 950);
    }
    requestAnimationFrame(fit);
  }
  // The light lives on its two layers only, so a flicker doesn't restyle the whole scene.
  function setLight(prop, value) {
    for (const el of lights) el.style.setProperty(prop, value);
  }
  /**
   * Keep the part of the scene that matters (focus: top and bottom, as fractions) in view above the
   * panel: slide the scene up, and if that isn't enough, zoom out a little (a soft blurred copy of
   * the scene fills the sides).
   */
  const wide = () => document.documentElement.classList.contains("wide");
  // The painted map is on screen: a phone held sideways lays it out beside the panel (style.css).
  const onMap = (on) => document.body.classList.toggle("on-map", on);
  /** A glade's name plate sits over the focus: its height in pixels (it doesn't scale with the scene). */
  const plateLift = () => wscene.querySelector(".plate:not(.gone)")?.offsetHeight || 0;
  /** Wide screens: the world covers the window; slide it so the scene sits left of the panel. */
  function fitWide(sc) {
    sc.style.height = "";
    sc.style.aspectRatio = "";
    walk.classList.remove("zoomed");
    wscene.style.setProperty("--scene-y", "0px");
    const info = SCENES[sc.dataset.scene];
    const vw = sc.offsetWidth;
    const vh = sc.offsetHeight;
    // Centre the middle of the scene in the free space left of the panel.
    const free = Math.max(vw * 0.4, stack.getBoundingClientRect().left - sc.getBoundingClientRect().left);
    let WH, WW, u, wx;
    // The art can only slide so far. If the creature would still reach under the panel (Old Ember's
    // tail), zoom in a little: the wider world slides further.
    for (let zoom = 1; zoom <= 1.3; zoom += 0.02) {
      WH = Math.max(vh, (vw * info.h) / info.w) * zoom;
      WW = (WH * info.w) / info.h;
      u = WH / info.h;
      const maxShift = (WW - vw) / 2;
      wx = Math.max(-maxShift, Math.min(maxShift, free / 2 - vw / 2));
      if (clearX == null || vw / 2 - WW / 2 + wx + clearX * u <= free - 12) break;
    }
    // Keep the important part of the scene (and the name plate over it) in view vertically.
    const top = focus[0] * WH - plateLift();
    const bottom = focus[1] * WH;
    let wy = Math.min(0, vh * 0.96 - bottom);
    wy = Math.max(wy, Math.min(0, 24 - top), vh - WH);
    sc.style.setProperty("--wh", `${Math.round(WH)}px`);
    sc.style.setProperty("--wx", `${Math.round(wx)}px`);
    sc.style.setProperty("--wy", `${Math.round(wy)}px`);
    // The free space left of the panel, for what's centred in it (the lantern going out, BLOOM).
    sc.style.setProperty("--free", `${Math.round(free)}px`);
  }
  function fit() {
    const sc = wscene.querySelector(".scene");
    if (!sc || !focus) return;
    if (sc.dataset.scene === "map-art") return fitMap(sc);
    if (sc.classList.contains("art")) return fitArt(sc);
    if (wide()) {
      fitWide(sc);
      wscene.querySelectorAll(".path-card").forEach(keepInView);
      keepAsk();
      return;
    }
    for (const v of ["--wh", "--wx", "--wy", "--free"]) sc.style.removeProperty(v);
    const W = sc.offsetWidth;
    const info = SCENES[sc.dataset.scene];
    const H = (W * info.h) / (info.core || info.w); // the scene's height at its normal size
    const room = stack.getBoundingClientRect().top - walk.getBoundingClientRect().top - 8;
    // Above the focus: the glade row (when it shows), and a glade's name plate over the creature.
    const row = view.querySelector("#glades");
    const rowBottom = row?.offsetParent && row.offsetHeight ? row.getBoundingClientRect().bottom - walk.getBoundingClientRect().top : 0;
    const lift = plateLift();
    const topRoom = Math.max(40, rowBottom + 6 + lift);
    const top = focus[0] * H;
    const bottom = focus[1] * H;
    // Zooming out makes the scene shorter and shows more of the forest at the sides (the art is
    // drawn wider than a phone shows), so nothing is ever empty.
    // Some screens (the fork, with little in the panel) may zoom in past normal to fill the room.
    let scale = Math.max(0.62, Math.min(focus[2] || 1, (room - topRoom) / Math.max(1, bottom - top)));
    // Room to spare (a short card): zoom in a little so the painting reaches the card, no dark gap.
    if (H * scale < room) scale = Math.min(1.45, room / H);
    let y = Math.min(0, room - bottom * scale);
    y = Math.max(y, topRoom - top * scale);
    // The scene can't slide down (there's nothing painted above it): zoom in instead, so what's over
    // the focus (Old Ember's strikes) comes out from under the glade row. The bottom gives way.
    if (y > 0 && top > 0) {
      scale = Math.min(1.45, topRoom / top);
      y = 0;
    }
    sc.style.height = `${Math.round(H * scale)}px`;
    sc.style.aspectRatio = "auto";
    wscene.style.setProperty("--scene-y", `${Math.round(Math.min(0, y))}px`);
    walk.classList.toggle("zoomed", scale < 0.995);
    wscene.querySelectorAll(".path-card").forEach(keepInView);
    keepAsk();
  }
  /**
   * The question the creature asks stays readable when the room changes (a phone's keyboard opens):
   * nudged back into view once the scene has slid to its new place.
   */
  let askTimer = 0;
  function keepAsk() {
    clearTimeout(askTimer);
    askTimer = later(() => {
      const ask = wscene.querySelector(".say.ask");
      if (ask && ask.dataset.ask != null) keepInView(ask);
    }, 380);
  }
  const onResize = () => requestAnimationFrame(fit);
  // The walk never scrolls (older browsers without overflow: clip can still scroll it by focus).
  walk.addEventListener("scroll", () => walk.scrollTop && (walk.scrollTop = 0));
  window.addEventListener("resize", onResize);
  window.visualViewport?.addEventListener("resize", onResize);
  // The light changed in Settings (it opens on the map): draw the map or the fork again in it,
  // under the open Settings. A glade already underway keeps its light; the next one takes the new.
  const onRelight = () => (s.phase === "door" || s.phase === "nook") && renderPhase();
  window.addEventListener("pq:relight", onRelight);

  /** New panel content rises in. */
  function setStack(markup) {
    stack.innerHTML = markup;
    stack.classList.remove("panel-in");
    void stack.offsetWidth;
    stack.classList.add("panel-in");
    requestAnimationFrame(fit);
  }

  // ---------- The glade row and the status bar ----------

  /** opts.at: the glade to count (a result card shows its own glade; the engine has already moved on). */
  function paintGlades(opts = {}) {
    const row = view.querySelector("#glades");
    if (opts.hide) {
      row.innerHTML = "";
      return;
    }
    const cur = Math.min(last, opts.at ?? s.floor);
    const cells = [...Array(s.floors).keys()].map((f) => {
      const rm = s.rooms.find((r) => r.floor === f);
      const inRoom = s.phase === "room" && f === s.floor;
      const fell = s.ending === "fell" && rm && rm === s.rooms.at(-1);
      if (f === last) return dia("dragon", `boss${f === cur && s.phase !== "done" ? " now" : ""}`, "Old Ember");
      if (rm && !inRoom) return dia(rm.look, fell ? "fell" : "done", beast(rm).name);
      if (inRoom) return dia(rm.look, "now", beast(rm).name);
      return dia(null, f === cur && s.phase !== "done" ? "now" : "");
    });
    row.innerHTML = `<span class="cap">Glade <span class="num">${cur + 1}</span>/${s.floors}</span>${cells.join("")}`;
  }

  function paintStatus() {
    const max = Math.max(RULES.HEARTS, s.hearts);
    let hearts = "";
    for (let i = 0; i < max; i++) hearts += heart(i < s.hearts, 15);
    const spent = relicSpent();
    // The lantern only matters while a question is open, so it's only shown then.
    const quizTime = s.phase === "room" && Boolean(rec.deadline);
    const secs = quizTime ? lanternSecs(rec.deadline - Date.now(), candleSeconds(s) * 1000) : "";
    status.innerHTML = `<button class="me-btn" type="button" aria-label="${HEROES[s.hero].name}: open the camp" title="The camp">${dia(`hero-${s.hero}`)}</button>
      <span class="hearts" aria-label="${s.hearts} ${s.hearts === 1 ? "heart" : "hearts"}${s.helm ? ", and a helm" : ""}">${hearts}${s.helm ? `<span class="helm" title="Iron Helm: blocks the next hit">+helm</span>` : ""}</span>
      ${s.relic ? `<button class="relic${spent ? " used" : ""}" type="button" aria-label="Your charm: ${esc(RELICS[s.relic].name)}"><span class="dia" style="background:${RELIC_COLOR[s.relic]}33"><span style="transform:rotate(-45deg)"><img class="pixel" src="art/r-${s.relic}.png" alt="" style="width:14px;height:auto" /></span></span></button>` : ""}
      <span class="gold" aria-label="${s.gold} gold">${coin("g", 15)}<span class="num">${shownGold}</span></span>
      ${quizTime ? `<span class="meter" aria-hidden="true">${lantern(16)}<span class="meter-bar"><span class="meter-fill"></span></span><span class="secs">${secs}</span></span>` : ""}`;
    // The camp opens between glades: a sheet over a question would hide the lantern while it burns.
    status.querySelector(".me-btn").addEventListener("click", () => {
      sfx.tap();
      if (s.phase !== "room") return openCamp();
      toast("The camp can wait: your lantern is lit!");
      const input = stack.querySelector("#answer");
      if (input && !input.disabled) input.focus({ preventScroll: true });
    });
    status.querySelector(".relic")?.addEventListener("click", () => toast(`${RELICS[s.relic].name}: ${relicText(s, s.relic)}${spent ? " (used)" : ""}`));
    paintMeter();
  }
  /** The Camp, over the walk. Before the first step a pick walks today: the walk and the map take it
   *  when the Camp closes, and the map shows what's left in the purse. */
  function openCamp() {
    const was = `${store.hero} ${store.purse}`;
    showCamp({ walking: unsettled() ? null : s.hero, fresh: unsettled(), onClose: () => {
      if (!alive || was === `${store.hero} ${store.purse}`) return;
      if (!dev && takePick(rec)) {
        save();
        s = rebuild();
      }
      if (s.phase === "door" && s.floor === 0) renderMap();
    } });
  }
  const relicSpent = () => (s.relic === "helm" && !s.helm) || (s.relic === "coin" && !s.coin) || (s.relic === "rod" && !s.rod && s.rooms.some((r) => r.rod));
  function paintMeter(frac) {
    const fill = status.querySelector(".meter-fill");
    if (!fill) return;
    if (frac == null) frac = s.phase === "room" && rec.deadline ? Math.max(0, Math.min(1, (rec.deadline - Date.now()) / (candleSeconds(s) * 1000))) : s.phase === "done" ? 0 : 1;
    fill.style.transform = `scaleX(${frac.toFixed(3)})`;
  }

  // The gold counter rolls towards the real total instead of jumping.
  let shownGold = s.gold;
  let rollRaf = 0;
  function setGold(bump = true) {
    const goldEl = status.querySelector(".gold");
    const span = goldEl?.querySelector(".num");
    if (!span) return;
    const from = shownGold;
    const to = s.gold;
    cancelAnimationFrame(rollRaf);
    if (bump) {
      goldEl.classList.remove("bump");
      void goldEl.offsetWidth;
      goldEl.classList.add("bump");
    }
    if (from === to || reducedMotion()) {
      shownGold = to;
      span.textContent = to;
      return;
    }
    const t0 = performance.now();
    const dur = Math.min(900, 260 + Math.abs(to - from) * 4);
    const step = (t) => {
      const k = Math.min(1, (t - t0) / dur);
      shownGold = Math.round(from + (to - from) * (1 - Math.pow(1 - k, 3)));
      span.textContent = shownGold;
      if (k < 1) rollRaf = requestAnimationFrame(step);
    };
    rollRaf = requestAnimationFrame(step);
  }

  function veil(fn, ms = 420) {
    if (reducedMotion()) return fn();
    const v = document.createElement("div");
    v.className = "veil";
    document.body.append(v);
    setTimeout(() => v.remove(), 950);
    later(fn, ms);
  }

  // ---------- The map: before glade 1, and before Old Ember ----------

  function renderMap() {
    stopLantern();
    const boss = s.floor === last;
    const id = `${boss ? "map-night" : "map-day"}-${s.floors}`;
    const sc = SCENES[id];
    const stops = sc.spots.stops;
    const here = stops[Math.min(stops.length - 1, s.floor + 1)];
    const pos = ([x, y]) => `left:${((x / sc.w) * 100).toFixed(2)}%;top:${((y / sc.h) * 100).toFixed(2)}%`;
    const markers = [...Array(s.floors).keys()]
      .map((f) => {
        const rm = s.rooms.find((r) => r.floor === f);
        const cls = f === last ? `boss${boss ? " now" : ""}` : rm ? "done" : f === s.floor ? "now" : "";
        const who = f === last ? "dragon" : rm ? rm.look : null;
        return `<div class="marker" style="${pos(stops[f + 1])}">${dia(who, cls)}${rm ? `<span class="badge">${badgeFor(rm)}</span>` : ""}</div>`;
      })
      .join("");
    const lamps = boss ? sc.spots.lamps.map((p) => `<span class="map-lamp" style="${pos(p)}"></span>`).join("") : "";
    const tag = boss
      ? `<div class="map-tag box" style="left:${(((stops[stops.length - 1][0] + 9) / sc.w) * 100).toFixed(1)}%;top:${(((stops[stops.length - 1][1] - 5) / sc.h) * 100).toFixed(1)}%"><span class="cap">Old Ember</span></div>`
      : `<div class="map-tag box" style="left:${(((here[0] + 10) / sc.w) * 100).toFixed(1)}%;top:${(((here[1] - 4) / sc.h) * 100).toFixed(1)}%"><span class="cap">You are here</span></div>`;
    // You, standing by the glade you're about to walk into.
    const hero = HERO_ART[s.hero] || HERO_ART.wanderer;
    const me = `<img class="map-me pixel" src="${hero.img}" alt="" style="left:${(((here[0] - 16) / sc.w) * 100).toFixed(2)}%;top:${(((here[1] - 12) / sc.h) * 100).toFixed(2)}%;width:${((hero.w / sc.w) * 100 * 0.7).toFixed(2)}%" />`;
    if (paintedMapFits(s.floors)) paintMap(boss);
    else setScene(id, { over: lamps + markers + tag + (boss ? "" : me), label: boss ? "The wood at night, seen from above: lanterns glow at the glades you've cleared. The great tree waits at the top." : `The wood as a miniature from above: a path from the round door through ${s.floors} clearings to a great tree.`, keep: mapFocus(stops), you: false });
    paintGlades({ hide: true });
    const first = s.dungeon.floors[0].doors[0];
    const streak = personalStats().current;
    if (boss) {
      setStack(html`<div class="box map-panel">
        <div class="cap">Glade ${s.floors} · the end of the path</div>
        <div class="ttl">Old Ember, keeper of the hoard</div>
        <div class="it">She ate the five most common answers. ${emberStrikes(s)}</div>
        <button class="btn" type="button" id="go">Wake her gently</button>
      </div>`);
    } else {
      setStack(html`<div class="box map-panel">
        <div class="row"><span class="cap">The Whispering Wood</span><span class="num" style="margin-left:auto;font-size:15px;color:#fff">No. ${day}</span></div>
        <div class="ttl">${WORDS[s.floors - 2] || s.floors - 1} glades, then Old Ember</div>
        <div class="it">First, a ${beast(first).name} waits in the meadow.</div>
        <div class="chips"><span class="chip">${raw(leaf(12, "#8fffd0"))} ${moodFor("glade", { floor: 0, floors: s.floors }) === "night" ? "Moonlit mist" : "Misty dusk"}</span>${streak > 0 && mode === "today" ? raw(`<span class="chip gold">${streak}-day streak</span>`) : ""}${s.hard ? raw(`<span class="chip bad">Hard mode</span>`) : ""}${mode === "replay" ? raw(`<span class="chip">Practice</span>`) : mode === "test" ? raw(`<span class="chip bad">Test walk</span>`) : ""}</div>
        <button class="btn" type="button" id="go">Set off</button>
      </div>
      <div class="map-menu">
        <div class="tt-icons">
          <a class="ico" href="#/archive" title="Ledger"><span class="c">${raw(ico("book"))}</span><span class="cap">Ledger</span></a>
          <button class="ico" type="button" id="m-camp" title="Camp"><span class="c"><img class="pixel hero-ico" src="${heroPortrait(store.hero)}" alt="" /></span><span class="cap">Camp</span></button>
          <button class="ico" type="button" id="m-help" title="How to play"><span class="c">${raw(ico("how"))}</span><span class="cap">How to play</span></button>
          <button class="ico" type="button" id="m-settings" title="Settings"><span class="c">${raw(ico("gear"))}</span><span class="cap">Settings</span></button>
        </div>
        <p class="map-foot">${raw(purseChip())}${mode === "today" ? raw(` · <span id="map-next"></span>`) : ""}</p>
      </div>`);
      const next = stack.querySelector("#map-next");
      clearInterval(nextTick);
      if (next) nextTick = tickNextWalk(next, day);
      stack.querySelector("#m-camp").addEventListener("click", openCamp);
      stack.querySelector("#m-help").addEventListener("click", () => showHelp());
      stack.querySelector("#m-settings").addEventListener("click", () => showSettings());
      // First visit: explain the walk once, here on the map (not over the start screen), unless you've
      // already set off (the glade and its lantern are on their way) or another sheet is open.
      if (!store.seenHelp) later(() => !store.seenHelp && !busy && s.phase === "door" && s.floor === 0 && !sheetOpen() && showHelp(), 700);
    }
    paintStatus();
    const go = stack.querySelector("#go");
    go.addEventListener("click", () => {
      // The map left open over midnight, not a step taken yet: today's walk is the new one (app.js).
      if (mode === "today" && !rec.actions.length && day !== todayDay()) return window.dispatchEvent(new HashChangeEvent("hashchange"));
      enterPath(0);
    });
    // Not under an open sheet: the map redraws under Settings when the light changes.
    later(() => !sheetOpen() && go.focus({ preventScroll: true }), 300);
  }

  /** On the map: where you are now, and the next two glades ahead (they're further up the map). */
  function mapFocus(stops) {
    const here = stops[Math.min(stops.length - 1, s.floor + 1)];
    const ahead = stops[Math.min(stops.length - 1, s.floor + 3)];
    const h = SCENES[`map-day-${s.floors}`].h;
    return [Math.max(0, ahead[1] - 16) / h, Math.min(h, here[1] + 12) / h];
  }

  /** The little token beside a cleared glade: the best loot there, or a burnt-out lantern. */
  function badgeFor(rm) {
    const got = rm.answers.filter(counts).sort((a, b) => TIERS[shownTier(b.tier)].rank - TIERS[shownTier(a.tier)].rank)[0];
    return got ? coin(shownTier(got.tier), 14) : `<span style="opacity:.8">${lantern(14, { out: true })}</span>`;
  }

  // ---------- The fork: tap the path you like the look of ----------

  let chosen = -1;
  let fx = null; // the fork's particles
  let forkAt = forkFor(day, 1); // which fork this is (every fork of a walk is a different place)
  const pathName = (i) => forkAt.names[i];
  let artView = { s: 1, tx: 0, ty: 0 }; // where the painted fork sits on screen (see fitArt)
  function renderFork() {
    stopLantern();
    chosen = -1;
    const doors = s.dungeon.floors[s.floor].doors;
    // A painted fork, a different one at each fork of the walk (the mushroom fork, the willow, the
    // mossy arch, the lantern stair), each with its own two paths.
    const baseFork = dev?.fork && s.floor === dev.floor ? FORKS[dev.fork] : forkFor(day, s.floor);
    // Dusk or moonlight (Settings; by default the first half of the forks at dusk, the rest by night).
    const night = moodFor("fork", { floor: s.floor, floors: s.floors }) === "night";
    forkAt = atLight(baseFork, night);
    wscene.innerHTML = forkSceneHtml({ place: forkAt, doors, hero: s.hero, labels: doors.map((d, i) => esc(pathLabel(d, i))), night }) + `<div class="fade"></div>`;
    onMap(false);
    walk.style.setProperty("--bg", `url("${new URL(forkPainting(forkAt, night), location.href).href}")`);
    lights = [];
    focus = [0, 1];
    // Over each path: a badge with its guardian's portrait, bobbing, and under it a card with what
    // the path holds. A letter lock shows its letter on a little tag by the guardian.
    const ui = wscene.querySelector(".art-ui");
    ui.insertAdjacentHTML(
      "beforeend",
      doors
        .map(
          (d, i) =>
            badgeHtml(i, (-i * 1.3).toFixed(1)) +
            `<button class="path-card box art" type="button" data-pick="${i}" aria-label="${esc(pathLabel(d, i))}" style="--d:${(-i * 2.1).toFixed(1)}s"></button>` +
            (d.quirk === "letter" ? `<span class="art-tag" data-tag="${i}">${esc(d.letter)}</span>` : ""),
        )
        .join(""),
    );
    // The medals turn: frames from the badge sheet, with each guardian drawn in.
    ui.querySelectorAll(".path-pin").forEach((pin, i) => turnBadge(pin, i * 1.3));
    wscene.classList.remove("enter");
    if (!reducedMotion()) {
      void wscene.offsetWidth;
      wscene.classList.add("enter");
      later(() => {
        wscene.classList.remove("enter");
        requestAnimationFrame(fit);
      }, 950);
    }
    fx?.stop();
    // No sparkles on the guardians themselves.
    const avoid = doors.map((d, i) => {
      const g = guardBox(forkAt, i, d.look);
      return { x0: g.x - g.w / 2 - 8, x1: g.x + g.w / 2 + 8, y0: g.top - 8, y1: g.bottom + 4 };
    });
    fx = startArtParticles(wscene.querySelector(".art-particles"), { view: () => artView, sparks: forkAt.art.fx?.sparks || null, stream: forkAt.stream, sources: forkSources(forkAt, night), avoid });
    paintGlades();
    paintStatus();
    paintForkStack();
    requestAnimationFrame(fit);
  }
  /** The painted map: the walk from the first clearing to the cave, with markers pinned to the clearings. */
  function paintMap(boss) {
    const done = s.rooms.map((r) => r.floor);
    const night = moodFor("map", { last: boss }) === "night";
    wscene.innerHTML = mapSceneHtml({ done, night, floors: s.floors }) + `<div class="fade"></div>`;
    onMap(true);
    walk.style.setProperty("--bg", `url("${new URL(night && MAP.night ? MAP.night : MAP.img, location.href).href}")`);
    lights = [];
    focus = [0, 1];
    const pin = (x, y, extra = "") => `data-wx="${x}" data-wy="${y}" ${extra}`;
    const markers = [...Array(s.floors).keys()]
      .map((f) => {
        const rm = s.rooms.find((r) => r.floor === f);
        const cls = f === last ? `boss${boss ? " now" : ""}` : rm ? "done" : f === s.floor ? "now" : "";
        const who = f === last ? "dragon" : rm ? rm.look : null;
        const [x, y] = stopOf(f, s.floors);
        return `<div class="marker art" ${pin(x, y)}>${dia(who, cls)}${rm ? `<span class="badge">${badgeFor(rm)}</span>` : ""}</div>`;
      })
      .join("");
    // You stand on the path at the edge of the clearing you're about to walk into (the path runs up the
    // middle of the map). The tag floats over you, and Old Ember's sits beside her medal, never over it.
    // Before Old Ember you stand where the last clearing meets the path up to her cave.
    // data-by: the marker to keep clear of (fitMap), since markers keep their size as the map scales.
    const by = Math.min(last - (boss ? 1 : 0), s.floor);
    const hero = HERO_ART[s.hero] || HERO_ART.wanderer;
    const [cx, cy] = stopOf(last, s.floors);
    const [mx, my] = travellerAt(by, s.floors);
    const me = `<img class="map-me art pixel" src="${hero.img}" alt="" ${pin(mx, my, `data-wh="112" data-by="${by}" data-aspect="${(hero.w / hero.h).toFixed(3)}"`)} />`;
    const tag = boss
      ? `<div class="map-tag box art" ${pin(cx + 62, cy - 14, `data-by="${last}"`)}><span class="cap">Old Ember</span></div>`
      : `<div class="map-tag box art above" ${pin(mx, my - 146)}><span class="cap">You are here</span></div>`;
    wscene.querySelector(".art-ui").insertAdjacentHTML("beforeend", markers + me + tag);
    wscene.classList.remove("enter");
    if (!reducedMotion()) {
      void wscene.offsetWidth;
      wscene.classList.add("enter");
      later(() => {
        wscene.classList.remove("enter");
        requestAnimationFrame(fit);
      }, 950);
    }
    fx?.stop();
    fx = startArtParticles(wscene.querySelector(".art-particles"), { view: () => artView, stream: MAP.water, sources: mapSources(), area: mapArea, flies: 22, petals: 6 });
    requestAnimationFrame(fit);
  }
  function fitMap(sc) {
    wscene.style.setProperty("--scene-y", "0px");
    walk.classList.remove("zoomed");
    // A wide screen, or a phone held sideways: the panel sits beside the map (style.css, .landscape).
    const beside = wide() || document.documentElement.classList.contains("landscape");
    const vw = walk.clientWidth;
    const vh = walk.clientHeight;
    sc.style.height = `${vh}px`;
    const roomH = beside ? vh : Math.round(stack.getBoundingClientRect().top - walk.getBoundingClientRect().top);
    const free = beside ? Math.max(vw * 0.45, stack.getBoundingClientRect().left - sc.getBoundingClientRect().left) : vw;
    // Sideways on a phone the painting can't both fill the window and fit the walk left of the panel:
    // it fills the part left of the panel, and the panel's dark column (style.css) covers the rest.
    const cover = beside && !wide() ? Math.min(vw, free + 12) : vw;
    artView = mapView(vw, vh, { roomH, top: 20, free, cover });
    const { s: k, tx, ty } = artView;
    sc.querySelector(".art-world").style.transform = `translate(${tx}px, ${ty}px) scale(${k})`;
    for (const el of sc.querySelectorAll("[data-wx]")) {
      el.style.left = `${Math.round(el.dataset.wx * k + tx)}px`;
      el.style.top = `${Math.round(el.dataset.wy * k + ty)}px`;
      if (el.dataset.wh) el.style.height = `${Math.round(el.dataset.wh * k)}px`;
    }
    // The markers shrink a little with a small map, so the clearings don't pile up on a small phone.
    const mk = markerSize(k);
    sc.style.setProperty("--mk", `${mk}px`);
    clearMarkers(sc, k, mk, free);
    fx?.redraw?.();
  }
  /**
   * Keep the traveller and the tags off the markers: you stand beside your clearing's marker, the
   * tag floats centred over you (nudged sideways off a marker it would cover), Old Ember's sits
   * beside her medal.
   */
  function clearMarkers(sc, k, mk, free) {
    const marks = [...sc.querySelectorAll(".marker.art")].map((m) => [parseFloat(m.style.left), parseFloat(m.style.top)]);
    const me = sc.querySelector(".map-me");
    const tag = sc.querySelector(".map-tag");
    if (me && marks[me.dataset.by]) {
      const half = (me.dataset.wh * k * me.dataset.aspect) / 2;
      const x = besideMarker(parseFloat(me.style.left), marks[me.dataset.by][0], half, mk, 8);
      const y0 = parseFloat(me.style.top);
      const y = Math.round(underMarkers(x, y0, half, me.dataset.wh * k, marks, mk));
      me.style.left = `${Math.round(x)}px`;
      me.style.top = `${y}px`;
      // The tag over you comes along.
      if (tag?.classList.contains("above")) tag.style.top = `${Math.round(parseFloat(tag.style.top) + y - y0)}px`;
    }
    if (!tag) return;
    if (tag.dataset.by && marks[tag.dataset.by]) {
      // Beside a medal (translate 0 -50%): its left edge just past the medal's right edge.
      tag.style.left = `${Math.round(Math.max(parseFloat(tag.style.left), marks[tag.dataset.by][0] + mk / 2 + 6))}px`;
    } else if (me && tag.classList.contains("above")) {
      // Over you (translate -50% -100%): centred on the traveller, then off any marker it would cover.
      const x = tagOffMarkers(parseFloat(me.style.left), { tw: tag.offsetWidth, th: tag.offsetHeight, bottom: parseFloat(tag.style.top), marks, mk, free });
      tag.style.left = `${Math.round(x)}px`;
    }
  }

  /** Lay the painted fork into its window, and pin the badges, cards and tags to their spots. */
  function fitArt(sc) {
    wscene.style.setProperty("--scene-y", "0px");
    walk.classList.remove("zoomed");
    const isWide = wide();
    const vw = walk.clientWidth;
    const room = isWide ? walk.clientHeight : Math.round(stack.getBoundingClientRect().top - walk.getBoundingClientRect().top + 30);
    sc.style.height = `${room}px`;
    const free = isWide ? Math.max(vw * 0.45, stack.getBoundingClientRect().left - sc.getBoundingClientRect().left) : vw;
    const row = view.querySelector("#glades")?.getBoundingClientRect();
    artView = forkView(vw, room, { free, top: row ? row.bottom - sc.getBoundingClientRect().top : 50, room: isWide ? 0.9 : 1, place: forkAt });
    const { s: k, tx, ty } = artView;
    sc.querySelector(".art-world").style.transform = `translate(${tx}px, ${ty}px) scale(${k})`;
    const put = (el, [x, y]) => el && (el.style.left = `${Math.round(x * k + tx)}px`) && (el.style.top = `${Math.round(y * k + ty)}px`);
    // The medals keep the painting's size (a little larger on small screens, so they stay tappable).
    const mk = Math.max(k, 0.62);
    // Each medal floats over its own guardian's head; its card hangs beside the guardian, toward the middle.
    s.dungeon.floors[s.floor].doors.forEach((door, i) => {
      const pin = sc.querySelector(`.path-pin[data-pick="${i}"]`);
      if (pin) Object.assign(pin.style, { width: `${Math.round(BADGE.w * mk)}px`, height: `${Math.round(BADGE.h * mk)}px` });
      put(pin, badgeAt(forkAt, i, door.look));
      const card = sc.querySelector(`.path-card[data-pick="${i}"]`);
      const other = s.dungeon.floors[s.floor].doors[1 - i]?.look;
      if (card) put(card, cardAt(forkAt, i, door.look, card.offsetWidth / 2 / k, 14 / k, { height: card.offsetHeight / k, other }));
      put(sc.querySelector(`.art-tag[data-tag="${i}"]`), tagAt(forkAt, i, door.look));
    });
    sc.querySelectorAll(".path-card").forEach(keepInView);
    fx?.redraw?.();
  }

  // The question heard at a fork, as asked: a letter lock's letter is already on its card.
  const heardQuestion = (d) => asSentence(room(d.pid).q);
  const quirkLine = (d) => (d.quirk === "letter" ? `Must start with “${d.letter}”` : QUIRKS[d.quirk].short.replace(/\.$/, ""));
  function pathLabel(d, i) {
    const r = room(d.pid);
    return `${cap1(pathName(i))}: ${CATEGORIES[r.cat].name}, guarded by the ${beast(d).name}. ${quirkLine(d)}.${d.elite ? " Double gold." : ""}`;
  }
  function paintForkStack() {
    const doors = s.dungeon.floors[s.floor].doors;
    const heard = (i) => s.relic === "map" || (s.peeked && s.peeked.floor === s.floor && s.peeked.i === i);
    doors.forEach((d, i) => {
      const r = room(d.pid);
      const card = wscene.querySelector(`.path-card[data-pick="${i}"]`);
      const pin = wscene.querySelector(`.path-pin[data-pick="${i}"]`);
      if (!card) return;
      card.classList.toggle("on", chosen === i);
      card.classList.toggle("off", chosen >= 0 && chosen !== i);
      card.setAttribute("aria-pressed", String(chosen === i));
      // A question heard at the fork is read out with its path too.
      card.setAttribute("aria-label", pathLabel(d, i) + (heard(i) ? ` It asks: “${heardQuestion(d)}”` : ""));
      pin?.classList.toggle("on", chosen === i);
      const needs = needsLine(d);
      card.innerHTML = html`<span class="cap">${CATEGORIES[r.cat].name} <span class="nb">· ${beast(d).name}</span></span>
        <span class="ttl">${QUIRKS[d.quirk].path}</span>
        <span class="does">${quirkLine(d)}.</span>
        ${needs ? raw(html`<span class="req">(${needs})</span>`) : ""}
        ${heard(i) ? raw(html`<span class="heard">“${heardQuestion(d)}”</span>`) : ""}`;
    });
    const canListen = canPeek(s) && s.relic !== "map";
    const action =
      chosen < 0
        ? html`<div class="hint-row">${raw(leaf(13, "#8fffd0"))} Tap a badge to see what waits on that path${s.relic ? raw(html` · <span>Charm: ${RELICS[s.relic].name}</span>`) : ""}</div>`
        : html`<div class="hint-row">${canListen ? raw(html`<button class="chip" type="button" id="listen">Listen in (Fox Scout · once a walk)</button>`) : ""}</div><button class="btn" type="button" id="take">${cap1(pathName(chosen).replace(/^the /, "through the "))}</button>`;
    setStack(action);
    for (const b of wscene.querySelectorAll(".path-card, .path-pin, .art-hit")) b.onclick = () => pick(Number(b.dataset.pick));
    stack.querySelector("#take")?.addEventListener("click", () => enterPath(chosen));
    stack.querySelector("#listen")?.addEventListener("click", () => listen(chosen));
    requestAnimationFrame(() => wscene.querySelectorAll(".path-card").forEach(keepInView));
  }
  function pick(i) {
    if (busy || s.phase !== "door") return;
    if (chosen === i) return enterPath(i);
    chosen = i;
    sfx.tap();
    for (const b of wscene.querySelectorAll(".art-hit")) b.classList.toggle("on", Number(b.dataset.pick) === i);
    mood(wscene.querySelector(`[data-path="${i}"]`), "hop", 520);
    spinBadge(wscene.querySelector(`.path-pin[data-pick="${i}"]`));
    // A little burst of sparkles over the chosen guardian.
    const g = guardBox(forkAt, i, s.dungeon.floors[s.floor].doors[i].look);
    const [x, y] = [g.x, g.top + 60];
    fx?.burst(x, y - 60, i ? "#9ff4ff" : "#ffd890");
    paintForkStack();
    stack.querySelector("#take")?.focus({ preventScroll: true });
  }
  function listen(i) {
    if (busy) return;
    const ev = dispatch({ t: "peek", i });
    if (!ev) return;
    sfx.rustle();
    paintForkStack();
    // The chip is gone now: keep keyboard focus on the way on.
    stack.querySelector("#take")?.focus({ preventScroll: true });
  }

  /** Step onto a path (or set off from the map): into the glade. */
  function enterPath(i) {
    if (busy || s.phase !== "door") return;
    busy = true;
    sfx.rustle();
    for (const b of stack.querySelectorAll("button")) b.disabled = true;
    wscene.querySelector(`.art-hit[data-pick="${i}"]`)?.classList.add("on");
    veil(() => {
      const ev = dispatch({ t: "door", i });
      busy = false;
      if (!ev) return renderPhase();
      rec.deadline = Date.now() + candleSeconds(s) * 1000 + RULES.DOOR_GRACE_MS;
      save();
      renderRoom(true);
    });
  }

  // ---------- A glade: the creature, its question, and your answer ----------

  const questionFor = (rm, r) => (rm.quirk === "letter" ? withLetter(r.q, rm.letter) : r.q);
  let actorBox = null; // the creature's box in scene grid pixels: { x, top, bottom }

  function renderRoom(entering = false) {
    const rm = currentRoom(s);
    const r = room(rm.pid);
    const m = beast(rm);
    if (!rec.deadline) {
      rec.deadline = Date.now() + candleSeconds(s) * 1000;
      save();
    }
    const id = dev?.glade && rm.floor === dev.floor ? dev.glade : gladeScene(rm.floor, s.floors);
    const sc = SCENES[id];
    const gladeLight = moodFor("glade", { floor: rm.floor, floors: s.floors });
    let inner;
    if (rm.boss) {
      inner = emberHtml(false, id, gladeLight);
      if (sc.painted) {
        const k = sc.actorScale || 1;
        const [sx, sy] = sc.spots.monster;
        actorBox = { x: sx, top: sy - EMBER_BOX.h * k, bottom: sy };
      } else {
        const off = (sc.w - (sc.core || sc.w)) / 2;
        actorBox = { x: 62 + off, top: 70, bottom: 108 };
      }
    } else {
      const spot = stageFor(sc, rm.look);
      const sp = SPRITES[rm.look];
      inner = actorHtml(id, rm.look, spot, { mood: gladeLight });
      const k = sp.room * (sc.actorScale || 1);
      const top = spot[1] - sp.float - sp.h * k;
      actorBox = { x: spot[0], top, bottom: spot[1] - sp.float, right: spot[0] + (sp.w * k) / 2 };
    }
    const plateTop = ((actorBox.top - 3) / sc.h) * 100;
    const x = ((actorBox.x / sc.w) * 100).toFixed(2);
    // Over its name: Old Ember's strikes, or the creature's twist. (A letter lock's letter is said in its
    // speech bubble, on a tag.)
    const badge = rm.boss
      ? `<div class="strike-pips"><span class="cap" style="font-size:9.5px">Strikes</span>${strikePips(rm)}</div>`
      : `<span class="chip">${QUIRKS[rm.quirk].name}</span>`;
    const plate = `<div class="plate" style="left:${x}%;top:${plateTop.toFixed(2)}%">${badge}<div class="ttl">${esc(m.name)}</div></div>`;
    // Keep in view: from the foot of its name plate (fit adds the plate's own height) down to you.
    const reach = rm.boss ? actorBox.x + (EMBER_BOX.w * (sc.actorScale || 1)) / 2 : actorBox.right;
    setScene(id, { inner, over: plate + saysHtml(), label: `${m.name} in the glade.`, enter: entering, mood: gladeLight, keep: [Math.max(0, actorBox.top - 3) / sc.h, (Math.max(actorBox.bottom + 4, sc.spots.you[1] + 2)) / sc.h], clear: reach });
    if (entering && rm.boss) later(() => sfx.roar(), 500);

    const armor = ARMOR[rm.armor];
    const chipRight = rm.boss
      ? `<span class="chip gold">Gold or better</span>`
      : rm.quirk === "letter"
        ? `<span class="chip">Starts with ${esc(rm.letter)}</span>`
        : rm.armor !== "none"
          ? `<span class="chip">${armor.short}</span>`
          : rm.elite
            ? `<span class="chip gold">Double gold</span>`
            : "";
    const catLine = `${CATEGORIES[r.cat].name}${rm.boss ? " · the hoard" : rm.elite && rm.armor !== "none" ? " · double gold" : ""}${s.hard ? " · hard" : ""}`;
    // The creature asks the question in its own speech bubble, in its own words (askBubble); the card
    // keeps the category and the rules, and the question itself for screen readers.
    const voice = voiceFor(rm, questionFor(rm, r), day);
    const spoken = [voice.before, voice.question, voice.after].filter(Boolean).join(" ");
    const sealed = rm.boss ? raw(html`<div class="sealed" aria-label="Already eaten">${raw(r.sealed.map((n) => html`<s>${sayAs(rm, r.answers.find((a) => a.name === n))}</s>`).join(""))}</div>`) : "";
    setStack(html`<div class="box qbox asked" id="qbox">
        <div class="row"><span class="cap">${catLine}</span>${raw(chipRight)}</div>
        <div class="q sr-only" id="q" role="heading" aria-level="2" aria-label="${spoken}">${questionFor(rm, r)}</div>
        ${sealed}
      </div>
      <div class="toast-line" id="hint" aria-live="polite"></div>
      <div class="suggest" id="suggest"></div>
      <form class="bar answer" id="answer-form" autocomplete="off">
        ${raw(hand())}
        <input id="answer" type="text" inputmode="text" enterkeyhint="go" autocomplete="off" autocorrect="off" autocapitalize="words" spellcheck="false" maxlength="60" placeholder="${rm.boss ? "Strike with a rare one…" : rm.quirk === "letter" ? `A “${rm.letter}” word…` : "Your answer…"}" aria-labelledby="q" />
        <span class="ans-lamp" aria-hidden="true">${raw(lantern(14))}<b class="ans-secs"></b></span>
        <span class="ans-line" aria-hidden="true"><i></i></span>
        <button class="enter cap" type="submit" aria-label="Say it">Enter</button>
      </form>
      <div class="tiers-key" id="meta">${raw(metaLine(rm, r))}</div>`);

    const form = stack.querySelector("form");
    const input = stack.querySelector("#answer");
    const actor = wscene.querySelector(".actor");
    // Tapping Enter (or a suggestion) mustn't take focus from the answer box: on a phone that closes
    // the keyboard, the layout jumps, and the tap misses the button. Keep the focus, keep one tap.
    const keepFocus = (e) => {
      if (document.activeElement === input && e.target.closest(".answer .enter, #suggest button")) e.preventDefault();
    };
    stack.addEventListener("pointerdown", keepFocus);
    stack.addEventListener("mousedown", keepFocus); // iOS moves focus on the mouse events it makes up after a tap
    form.addEventListener("submit", (e) => {
      e.preventDefault();
      submit(input.value);
    });
    let leanTimer = null;
    input.addEventListener("input", () => {
      sfx.type();
      stack.querySelector("#suggest").innerHTML = "";
      // The creature leans in and watches you type.
      actor?.classList.add("lean");
      clearTimeout(leanTimer);
      leanTimer = setTimeout(() => actor?.classList.remove("lean"), 260);
    });
    bindMeta(rm);
    // The creature speaks: its bubble pops up and the question writes itself out while it talks.
    const bubble = askBubble(voice);
    if (entering && bubble && !reducedMotion()) {
      const total = bubbleChars(voice);
      bubble.innerHTML = bubbleHtml(voice, 0);
      bubble.classList.add("typing");
      actor?.classList.add("talking");
      let n = 0;
      const typeOn = () => {
        if (!bubble.isConnected || bubble.dataset.ask == null) return;
        n = Math.min(total, n + (total > 60 ? 3 : 2));
        bubble.innerHTML = bubbleHtml(voice, n);
        if (n < total) later(typeOn, 24);
        else {
          bubble.classList.remove("typing");
          actor?.classList.remove("talking");
        }
      };
      later(typeOn, 520);
    }
    // Typing is the game, so the answer box takes focus as soon as the glade appears.
    later(() => input.focus({ preventScroll: true }), entering ? 500 : 50);
    paintGlades();
    paintStatus();
    startLantern();
  }

  const strikePips = (rm) => Array.from({ length: s.strikesNeeded }, (_, i) => `<span class="pip${i < rm.strikes ? " on" : ""}"></span>`).join("");

  /** The line under the answer bar: what this glade needs (or the tier key), and the dowsing
   *  (the Dowsing Rod's or the Dowser's) under it wherever there is some, Old Ember's glade too. */
  function metaLine(rm, r) {
    const d = dowsing(s, rm, r);
    const dowse = d ? html`<span class="dowse">${raw(leaf(12, "#8fffd0"))} ${d.who}: ${d.count} answers · the Crown Jewel starts with “${sayAs(rm, r.jewel).replace(/^the\s+/i, "")[0]}”</span>` : "";
    return gladeLine(rm, r, !d) + dowse;
  }
  function gladeLine(rm, r, key) {
    if (rm.boss) {
      const strikes = rm.answers.filter((a) => a.idx >= 0 && a.through && counts(a));
      if (!strikes.length) return html`<span>${raw(leaf(12, "#8fffd0"))} Gold, Gem or Crown Jewel answers strike</span>`;
      return `<span class="strikes">${strikes.map((a, i) => html`Strike ${["one", "two", "three"][i] || i + 1}: “${r.answers[a.idx].name}”${raw(coin(shownTier(a.tier), 13))}`).join(" · ")}</span>`;
    }
    if (rm.quirk === "collector") return html`<span>The ${beast(rm).name} wants two different answers: <b class="collect num" style="color:#fff">${rm.answers.filter(counts).length} / ${needed(rm)}</b></span>`;
    if (rm.quirk === "bargain") return html`<button class="chip" type="button" id="wisp" ${rm.hinted ? "disabled" : ""}>${raw(lantern(12))} ${rm.hinted ? `The ${beast(rm).name} whispered “${rm.hintLetter}”` : `Ask the ${beast(rm).name} for a hint · half gold`}</button>`;
    // The tier key, unless the dowsing takes its place.
    return key ? `<span>${coin("c")} common</span><span>${coin("s")} rarer</span><span>${coin("g")} rarest</span>` : "";
  }
  function bindMeta(rm) {
    stack.querySelector("#wisp")?.addEventListener("click", askWisp);
    if (rm.quirk === "collector") stack.querySelector(".collect")?.setAttribute("aria-live", "polite");
  }
  function repaintMeta(rm) {
    const el = stack.querySelector("#meta");
    if (!el) return;
    el.innerHTML = metaLine(rm, room(rm.pid));
    bindMeta(rm);
  }

  function hint(text, cls = "") {
    const el = stack.querySelector("#hint");
    if (!el) return;
    el.className = `toast-line ${cls}`;
    el.innerHTML = text;
    requestAnimationFrame(fit);
  }

  // ---------- Speech and moods ----------

  function saysHtml() {
    return `<div class="say" data-say="m"></div><div class="say" data-say="left"></div><div class="say" data-say="right"></div>`;
  }
  /** How many letters the creature says (the typing counts them). */
  const bubbleChars = (v) => v.before.length + v.question.length + v.after.length;
  /**
   * The bubble's words, the first n letters of them (all of them without n): the line before the
   * question and the one after it small and in italics, the question itself big, a letter lock's letter
   * on a little tag.
   */
  function bubbleHtml(v, n = Infinity) {
    let left = n;
    const take = (t) => {
      const out = t.slice(0, Math.max(0, left));
      left -= t.length;
      return out;
    };
    const before = take(v.before);
    const q = take(v.question);
    const after = take(v.after);
    // The letter a Letter lock wants, “S”, as a little tag (only once it has been typed out whole).
    const qHtml = esc(q)
      .replace(/“([A-Z])”/, (_, l) => `<b class="ltr">${l}</b>`)
      .replace(/(start(?:s|ing)? with (?:the letter )?)([A-Z])(?=[.,!?\s]|$)/, (_, w, l) => `${w}<b class="ltr">${l}</b>`);
    return `${v.before ? `<span class="lead">${esc(before)}</span>` : ""}<span class="ask-q">${qHtml}</span>${v.after ? `<span class="tail-line">${esc(after)}</span>` : ""}`;
  }
  /**
   * The creature asks its question in its own speech bubble, which stays up while you answer, under
   * its feet with its tail pointing up at it. Sized for the whole question first, so it doesn't grow
   * while it's typed out. Returns the bubble.
   */
  function askBubble(voice) {
    const el = wscene.querySelector(`.say[data-say="m"]`);
    if (!el) return null;
    el.classList.add("ask");
    el.style.width = "";
    el.style.minHeight = "";
    say("m", "…", Infinity);
    el.innerHTML = bubbleHtml(voice);
    // It speaks down the path to you: the bubble hangs under its feet, its tail pointing up at it.
    const sc = SCENES[wscene.querySelector(".scene")?.dataset.scene];
    if (actorBox && sc) {
      el.classList.add("below");
      el.style.top = `calc(${((actorBox.bottom / sc.h) * 100).toFixed(2)}% + 10px)`;
      el.style.setProperty("--dy", "0px");
    }
    keepInView(el);
    // Its size without the pop-in's scale (getBoundingClientRect would measure it mid-pop, too small).
    el.style.width = `${el.offsetWidth + 1}px`;
    el.style.minHeight = `${el.offsetHeight}px`;
    el.dataset.ask = el.innerHTML;
    return el;
  }
  /**
   * Its last word on the glade, said in the same bubble it asked from (a thank-you, "Lights out!"),
   * which then goes.
   */
  function farewell(text, ms = 1800) {
    const el = wscene.querySelector(`.say[data-say="m"]`);
    if (!el || el.dataset.ask == null) return say("m", text, ms);
    delete el.dataset.ask;
    delete el.dataset.askSize;
    clearTimeout(el._t);
    el.classList.remove("typing");
    wscene.querySelector(".actor")?.classList.remove("talking");
    el.style.minHeight = "";
    el.style.width = "";
    el.innerHTML = `<span class="react">${esc(text)}</span>`;
    el._t = setTimeout(() => {
      el.classList.remove("show");
      setTimeout(() => el.dataset.ask == null && !el.classList.contains("show") && (el.classList.remove("ask", "below"), (el.style.width = "")), 400);
    }, ms);
  }

  /** The glade's creature says something for a moment. */
  function say(who, text, ms = 1600) {
    const el = wscene.querySelector(`.say[data-say="${who}"]`);
    if (!el || !text) return;
    // It's asking its question in this bubble: say this, then go back to the question.
    if (el.dataset.ask != null) {
      el.classList.remove("typing");
      // A short word gets a small bubble: the question's size comes back with the question.
      if (!el.dataset.askSize) el.dataset.askSize = `${el.style.width}|${el.style.minHeight}`;
      el.style.width = "";
      el.style.minHeight = "";
      el.innerHTML = `<span class="react">${esc(text)}</span>`;
      clearTimeout(el._t);
      el._t = setTimeout(() => {
        if (el.dataset.ask == null) return;
        const [w, h] = (el.dataset.askSize || "|").split("|");
        el.style.width = w;
        el.style.minHeight = h;
        delete el.dataset.askSize;
        el.innerHTML = el.dataset.ask;
      }, ms);
      return;
    }
    const id = wscene.querySelector(".scene")?.dataset.scene;
    const sc = SCENES[id];
    el.classList.remove("below");
    if (who === "m" && actorBox) {
      el.style.left = `${((actorBox.x / sc.w) * 100).toFixed(2)}%`;
      el.style.top = `calc(${(((actorBox.top - 3) / sc.h) * 100).toFixed(2)}% - 46px)`;
    }
    el.textContent = text;
    el.classList.remove("show");
    keepInView(el);
    // No room above the creature (it stands high, under the glade row): say it from below its feet
    // instead of pushing the bubble down over its name plate.
    if (who === "m" && actorBox && parseFloat(el.style.getPropertyValue("--dy")) > 0) {
      el.classList.add("below");
      el.style.top = `calc(${((actorBox.bottom / sc.h) * 100).toFixed(2)}% + 8px)`;
      el.style.setProperty("--dy", "0px");
    }
    void el.offsetWidth;
    el.classList.add("show");
    clearTimeout(el._t);
    if (ms !== Infinity) el._t = setTimeout(() => el.classList.remove("show"), ms);
  }
  /**
   * Nudge a speech bubble or a path's card so it stays on screen, below the glade row and clear of the
   * dark: the fade into the panel at the bottom of a phone's scene, the shaded band behind the panel on
   * wide screens.
   */
  function keepInView(el) {
    // Measured and placed in one go, with no slide: re-kept mid-slide it would measure where it's passing.
    const was = el.style.transition;
    el.style.transition = "none";
    placeInView(el);
    void el.offsetWidth;
    el.style.transition = was;
  }
  function placeInView(el) {
    el.style.setProperty("--dx", "0px");
    el.style.setProperty("--dy", "0px");
    const r = el.getBoundingClientRect();
    const win = wscene.querySelector(".scene")?.getBoundingClientRect();
    if (!win) return;
    const pad = 10;
    const isWide = document.documentElement.classList.contains("wide");
    // On wide screens the panel (and the dark band behind it) sits over the right of the forest.
    const panel = isWide ? stack.getBoundingClientRect().left : innerWidth;
    let right = Math.min(win.right, innerWidth, panel) - pad;
    let leftB = Math.max(win.left, 0) + pad;
    // The fork's two cards each keep to their own half, so they never overlap.
    const midX = (leftB + right) / 2;
    if (el.classList.contains("left")) right = Math.min(right, midX - 4);
    if (el.classList.contains("right")) leftB = Math.max(leftB, midX + 4);
    const row = view.querySelector("#glades");
    const top = Math.max(win.top, 0, row && row.offsetParent ? row.getBoundingClientRect().bottom : 0) + pad;
    // The bottom: above the phone's fade (a little into its clear top is fine), and on screen.
    const fade = !isWide && wscene.querySelector(":scope > .fade")?.getBoundingClientRect();
    const bottom = Math.min(win.bottom, innerHeight, fade && fade.height ? fade.top + fade.height * 0.3 : Infinity, isWide ? Infinity : stack.getBoundingClientRect().top) - pad;
    const dx = r.left < leftB ? leftB - r.left : r.right > right ? right - r.right : 0;
    const dy = r.top - 6 < top ? top - (r.top - 6) : r.bottom > bottom ? Math.max(bottom - r.bottom, top - (r.top - 6)) : 0;
    el.style.setProperty("--dx", `${Math.round(dx)}px`);
    el.style.setProperty("--dy", `${Math.round(dy)}px`);
  }
  function mood(el, name, ms = 600) {
    if (!el || el.classList.contains("ko")) return;
    el.classList.remove("hit", "flinch", "hop", "lunge");
    void el.offsetWidth;
    el.classList.add(name);
    later(() => el.classList.remove(name), ms);
  }
  function shake(big = false) {
    walk.classList.remove("shake", "shake-big");
    void walk.offsetWidth;
    walk.classList.add(big ? "shake-big" : "shake");
    later(() => walk.classList.remove("shake", "shake-big"), 500);
  }
  function flash(kind) {
    const sc = wscene.querySelector(".scene");
    if (!sc || reducedMotion()) return;
    const f = document.createElement("div");
    f.className = `flash ${kind}`;
    sc.append(f);
    later(() => f.remove(), 700);
  }

  // ---------- Answering ----------

  function askWisp() {
    if (busy || s.phase !== "room") return;
    const ev = dispatch({ t: "hint" });
    if (!ev) return;
    const e = ev.find((x) => x.type === "hint");
    sfx.relic();
    say("m", `Psst… “${e.letter}”…`, 2400);
    hint(html`The ${beast(currentRoom(s)).name} whispers: try something rare starting with <b>“${e.letter}”</b>. This glade now pays half.`, "good");
    repaintMeta(currentRoom(s));
    const [x, y] = centerOf(wscene.querySelector(".actor") || wscene);
    drift(x, y, { tier: "night", count: 14, spread: 50 });
    stack.querySelector("#answer")?.focus({ preventScroll: true });
  }

  /**
   * Typo help (normal mode). Text that isn't an answer here but is close to one isn't said: the
   * answer it's close to goes into the box, and Enter says it (as its name or the alias you were
   * spelling, so a letter still fits); edit it and it's gone. Only answers the room would take are
   * offered: not one said already, eaten by Old Ember, or with the wrong letter (then it says so).
   * Something real that just isn't an answer here ("Australia" for Europe) is said as typed: a miss.
   */
  function submit(value) {
    if (busy || s.phase !== "room") return;
    const rm = currentRoom(s);
    const r = room(rm.pid);
    const text = String(value || "").trim();
    if (!text) return;
    const input = stack.querySelector("#answer");
    const box = stack.querySelector("#suggest");
    if (!s.hard && !find(r, text, s.rules) && !recognise(text)) {
      const [best, ...more] = suggest(r, text, { rules: s.rules, fits: (i, sp) => wouldTake(s, rm, i, sp) });
      if (best && input) {
        input.value = best.text;
        input.setSelectionRange(best.text.length, best.text.length);
        input.focus({ preventScroll: true });
        box.innerHTML =
          html`<span class="it">Did you mean <b>${best.text}</b>? Press Enter to answer it.</span>` +
          (more.length ? `<span class="it">Or</span>` + more.map((x) => html`<button class="chip gold" type="button" data-s="${x.text}">${x.text}</button>`).join("") : "");
        for (const b of box.querySelectorAll("button")) b.addEventListener("click", () => submit(b.dataset.s));
        hint("");
        sfx.blip();
        requestAnimationFrame(fit);
        return;
      }
      // Close only to answers the room won't take: say why, and it isn't a guess either.
      const near = suggest(r, text, { rules: s.rules, limit: 1 })[0];
      if (near) {
        if (input) input.value = "";
        box.innerHTML = "";
        return refuse(rm, r, near);
      }
    }
    box.innerHTML = "";
    const ev = dispatch({ t: "answer", text });
    if (!ev) return;
    if (input) input.value = "";
    play(ev, rm, { typed: text });
  }

  /** Why typo help had nothing to propose: the close answer was said already, eaten, or the wrong letter. */
  function refuse(rm, r, near) {
    sfx.blip();
    if (rm.answers.some((x) => x.idx === near.index)) {
      say("m", pickOne(REACT.dupe));
      hint(html`You already said <b>${near.name}</b>.`);
    } else if (rm.boss && r.sealed.includes(near.name)) {
      say("m", pickOne(REACT.sealed));
      hint(html`Old Ember already ate <b>${near.name}</b>. Find a rarer one!`, "bad");
    } else hint(html`<b>${near.text}</b> doesn't start with <b>“${rm.quirk === "letter" ? rm.letter : r.letter}”</b>. Guesses are free.`, "bad");
  }

  /** How this room takes an answer: its name, or the alias that fits the room's letter ("Persia" for P). */
  function sayAs(rm, a) {
    return spellingFor(s, rm, a.rank) || a.name;
  }

  function missLine(typed, r, m, rm, reason, letter = rm.letter) {
    if (reason === "letter") return html`That doesn't start with <b>“${letter}”</b>. Guesses are free.`;
    const known = recognise(typed, r.listKey);
    if (known && known.listKey === r.listKey) return html`<b>${known.name}</b> is a ${r.noun}, but ${r.miss || "not one that belongs here"}. Guesses are free.`;
    if (known) return html`<b>${known.name}</b> is a real ${known.noun}, but not what ${m.the} asked for.`;
    const q = quipFor(typed);
    if (q) return esc(q);
    return html`“${typed}” isn’t on the list. Guesses are free.`;
  }

  /** Shows what just happened: reactions, loot, hits, strikes, then a result or an ending. */
  function play(ev, rm, { typed }) {
    const r = room(rm.pid);
    const m = beast(rm);
    const actor = wscene.querySelector(".actor");
    const form = stack.querySelector("#answer-form");
    let resolved = false;
    let ending = null;
    let reaction = null; // what it just said to a right answer
    for (const e of ev) {
      if (e.type === "miss") {
        form?.classList.remove("shake");
        void form?.offsetWidth;
        form?.classList.add("shake");
        sfx.miss();
        say("m", pickOne(e.reason === "letter" && rm.quirk === "letter" ? REACT.letter : REACT.miss));
        mood(actor, "hop", 520);
        hint(missLine(typed, r, m, rm, e.reason, e.letter), "bad");
      }
      if (e.type === "bounced") {
        hint(`${missLine(typed, r, m, rm, rm.answers.at(-1)?.reason)} It bounced off the ${m.name}. No harm done, once.`, "bad");
        say("m", "Boing! That one bounced.");
        sfx.blocked();
      }
      if (e.type === "forgiven") {
        hint(`${missLine(typed, r, m, rm, rm.answers.at(-1)?.reason)} Your Four-leaf Clover forgives it.`, "bad");
        sfx.blocked();
      }
      if (e.type === "hit") later(() => takeHitFx(e.times), e.cause === "armor" ? 650 : 120);
      if (e.type === "blocked")
        later(() => {
          sfx.blocked();
          toast("Your Iron Helm takes the hit!");
          paintStatus();
        }, 650);
      if (e.type === "dupe") {
        sfx.blip();
        say("m", pickOne(REACT.dupe));
        hint(html`You already said <b>${e.name}</b>.`);
      }
      if (e.type === "sealed") {
        sfx.blip();
        say("m", pickOne(REACT.sealed));
        hint(html`Old Ember already ate <b>${e.name}</b>. Find a rarer one!`, "bad");
      }
      if (e.type === "loot" && e.armored) {
        // A right answer, but too common for the armour: it bounces off. Nothing lost; try again.
        scorePop(`${coin(shownTier(e.tier), 26)}`, "zero");
        sfx.blocked();
        mood(actor, "hop", 520);
        say("m", pickOne(REACT.armored));
        const what = `only ${TIERS[shownTier(e.tier)].name}`;
        hint(html`<b>${e.name}</b> is right, but ${what}. It bounced off: no heart lost. Try a rarer one!`, "bad");
        continue;
      }
      if (e.type === "loot") {
        lootFx(e, actor);
        const t = e.lucky ? "g" : e.trueTier === "f" ? "f" : e.tier;
        reaction = pickOne(REACT[t]);
        say("m", reaction);
        mood(actor, HIT_MOOD[e.lucky ? "g" : e.tier], 650);
        // A right answer: the last miss's red line ("bounced off", "already said") goes.
        hint("");
        if (rm.quirk === "haggler" && e.tier === "c") hint(html`<b>${e.name}</b> is Copper, and the ${m.name} doesn't buy copper. No gold.`, "bad");
        if (rm.boss && e.through) hint(html`<b>${e.name}</b>: a ${TIERS[shownTier(e.tier)].name} strike!`, "good");
        if (rm.boss && !e.through) hint(html`<b>${e.name}</b> is only ${TIERS[shownTier(e.tier)].name}. Old Ember shrugs it off.`, "bad");
      }
      if (e.type === "eaten")
        later(() => {
          // An empty purse: nothing to bite.
          if (!e.gold) return say("m", "Copper? And your purse is empty! Hmph.");
          say("m", "Crunch! Copper makes me peckish.");
          toast(`The ${m.name} ate ${e.gold} of your gold!`);
          setGold(true);
          sfx.hit();
        }, 900);
      if (e.type === "healed")
        later(() => {
          sfx.relic();
          toast(`The ${m.name} is delighted and gives you a big hug: +1 heart!`);
          paintStatus();
          status.querySelectorAll(".hearts .hrt")[s.hearts - 1]?.classList.add("pop");
        }, 800);
      if (e.type === "collect") {
        repaintMeta(rm);
        hint(html`<b>${e.have} of ${e.need}.</b> The ${m.name} wants one more, a different one.`, "good");
        // Said with the reaction, not after it, or it would talk over the reaction to your next answer.
        say("m", `${reaction || "Lovely!"} One more, please!`, 2400);
      }
      if (e.type === "strike") {
        later(() => sfx.strike(), 200);
        const pips = wscene.querySelector(".strike-pips");
        if (pips) {
          pips.innerHTML = `<span class="cap" style="font-size:9.5px">Strikes</span>${strikePips(rm)}`;
          pips.querySelectorAll(".pip.on")[rm.strikes - 1]?.classList.add("fresh");
        }
        repaintMeta(rm);
      }
      if (e.type === "advance") resolved = true;
      if (e.type === "vault" || e.type === "fell" || e.type === "escaped") ending = e;
    }
    paintStatus();
    if (ending) return finish(ending);
    if (resolved) {
      stopLantern();
      busy = true;
      const input = stack.querySelector("#answer");
      if (input) {
        input.disabled = true;
        input.blur();
      }
      const got = rm.answers.filter(counts);
      // Won over: the creature is delighted and lets you through.
      later(() => {
        happyActor(actor, { aside: false });
        sfx.happy();
        farewell(pickOne(["Off you go, then!", "You may pass!", "Thank you! This way!", "Lovely. Through you go!"]), 1800);
      }, 800);
      later(() => showResult(rm), 1500);
    }
  }

  function takeHitFx(times = 1) {
    sfx.hit();
    if (times > 1) later(() => sfx.hit(), 220);
    // The hearts about to go crack in two and fall away.
    const before = [...status.querySelectorAll(".hearts .hrt.on")];
    for (let k = 0; k < times; k++) {
      const h = before[s.hearts + k];
      if (!h || reducedMotion()) continue;
      const r = h.getBoundingClientRect();
      for (const side of ["l", "r"]) {
        const shard = document.createElement("div");
        shard.className = `heart-shard ${side}`;
        shard.innerHTML = heart(true, r.width);
        Object.assign(shard.style, { left: `${r.left}px`, top: `${r.top}px`, width: `${r.width}px`, height: `${r.height}px`, animationDelay: `${k * 0.12}s` });
        document.body.append(shard);
        setTimeout(() => shard.remove(), 1200);
      }
    }
    shake(times > 1);
    flash("red");
    mood(wscene.querySelector(".actor"), "hop", 500);
    paintStatus();
    if (navigator.vibrate) navigator.vibrate(times > 1 ? [60, 60, 60] : 60);
  }

  /** "+30" floating up beside the creature. */
  function scorePop(text, cls = "", stay = false) {
    const sc = wscene.querySelector(".scene");
    const box = SCENES[sc?.dataset.scene];
    if (!sc || !box || !actorBox) return null;
    const el = document.createElement("div");
    el.className = `score-pop ${cls}${stay ? " stay" : ""}`;
    const off = (box.w - (box.core || box.w)) / 2;
    const right = Math.min(off + (box.core || box.w) - 24, (actorBox.right ?? actorBox.x + 10) + 2);
    el.style.left = `${((right / box.w) * 100).toFixed(1)}%`;
    el.style.top = `${(((actorBox.top + 2) / box.h) * 100).toFixed(1)}%`;
    el.innerHTML = text;
    sc.querySelector(".sc-world").append(el);
    if (!stay) later(() => el.remove(), 1700);
    return el;
  }

  /**
   * BLOOM: a Gold-or-better answer makes the glade burst into flower, and the creature cries out (its own
   * cheer, voice.js). The words burst and go, even on
   * the win, so it never stays over a face (Old Ember laughing); stay: the glow stays, low over the hoard.
   */
  let cheers = 0;
  function bloom(stay = false) {
    const sc = wscene.querySelector(".scene");
    if (!sc) return;
    sfx.bloom();
    const glow = document.createElement("div");
    glow.className = `bloom-glow${stay ? " stay" : ""}`;
    const word = document.createElement("div");
    word.className = "bloom-word";
    word.setAttribute("aria-hidden", "true");
    // The creature cries out in its own voice (voice.js CHEERS), not a word of ours.
    const look = sc.querySelector(".actor[data-m]")?.dataset.m;
    word.textContent = cheerFor(look, cheers++);
    sc.append(glow, word);
    const info = SCENES[sc.dataset.scene];
    if (info && actorBox) {
      word.style.top = `max(4%, calc(${(((actorBox.top + actorBox.bottom) / 2 / info.h) * 100).toFixed(2)}% - 40px))`;
      if (stay) glow.style.setProperty("--gy", `${((actorBox.bottom / info.h) * 100).toFixed(1)}%`);
    }
    later(() => {
      word.remove();
      if (!stay) glow.remove();
    }, 2300);
    const [x, y] = centerOf(sc.querySelector(".actor") || sc);
    burst(x, y - 20, { tier: "bloom", kind: "petal", count: stay ? 44 : 26, speed: 300, gravity: 140, life: 1.7 });
  }

  function lootFx(e, actor) {
    const tier = e.lucky ? "g" : e.tier;
    if (tier === "j") flash("gold");
    if (RARE(tier)) {
      shake(tier !== "g");
      bloom();
    }
    scorePop(e.gold ? `+${e.gold}` : "0", e.gold ? "" : "zero");
    sfx.loot(e.trueTier === "f" && !e.lucky ? "f" : tier);
    const [x, y] = actor ? centerOf(actor) : centerOf(wscene);
    if (!e.gold) return;
    // Sparkle at the hit, then the coins fly home to the purse and it rolls up.
    burst(x, y - 20, { tier, kind: "star", count: { c: 4, f: 3, s: 8, g: 12, e: 18, j: 30 }[tier], speed: tier === "j" ? 360 : 240, gravity: 200, life: 0.9 });
    const coins = { c: 3, f: 3, s: 5, g: 8, e: 11, j: 16 }[tier] || 5;
    let landed = 0;
    const goldEl = status.querySelector(".gold");
    flyTo(x, y - 10, goldEl, {
      tier,
      count: coins,
      onArrive: () => {
        if (landed++ % 2 === 0) sfx.tap();
      },
      onDone: () => setGold(true),
    });
    if (reducedMotion()) setGold(true);
  }

  // ---------- The lantern ----------

  let flickerRaf = 0;
  function startLantern() {
    stopLantern();
    lastSecond = null;
    const total = candleSeconds(s) * 1000;
    const update = () => {
      if (!alive || s.phase !== "room") return stopLantern();
      if (dev?.still) rec.deadline = Date.now() + total;
      const left = rec.deadline - Date.now();
      const frac = Math.max(0, Math.min(1, left / total));
      setLight("--light", (0.2 + frac * 0.8).toFixed(3));
      paintMeter(frac);
      const secs = lanternSecs(left, total);
      const meter = status.querySelector(".meter");
      // A copy of the lantern rides in the answer bar, so it shows above a phone keyboard too.
      const bar = stack.querySelector(".answer");
      const line = bar?.querySelector(".ans-line i");
      if (line) line.style.transform = `scaleX(${frac.toFixed(3)})`;
      if (secs !== lastSecond) {
        const el = status.querySelector(".secs");
        if (el) el.textContent = secs;
        const a = bar?.querySelector(".ans-secs");
        if (a) a.textContent = secs;
      }
      meter?.classList.toggle("low", left <= 5000);
      bar?.classList.toggle("low", left <= 5000);
      // The creature gets fidgety as the light goes.
      if (left <= 5000 && left > 0 && secs !== lastSecond) {
        sfx.tick();
        mood(wscene.querySelector(".actor:not(.ember)"), "hop", 400);
      }
      lastSecond = secs;
      if (left <= 0) {
        stopLantern();
        timeout();
      }
    };
    update();
    tick = setInterval(update, 100);
    // The flame flickers on its own clock, and the glade's light breathes with it.
    const noise = makeNoise();
    const flicker = (t) => {
      if (!tick) return;
      const left = rec.deadline - Date.now();
      const nervous = left < 5000 ? 2.4 : 1;
      setLight("--flick", (1 + noise(t / 1000) * 0.05 * nervous).toFixed(3));
      flickerRaf = requestAnimationFrame(flicker);
    };
    if (!reducedMotion()) flickerRaf = requestAnimationFrame(flicker);
  }
  function stopLantern() {
    cancelAnimationFrame(flickerRaf);
    if (tick) clearInterval(tick);
    tick = null;
  }

  function timeout() {
    if (busy || s.phase !== "room") return;
    const rm = currentRoom(s);
    sfx.snuff();
    const ev = dispatch({ t: "timeout" });
    if (!ev) return;
    const input = stack.querySelector("#answer");
    if (input) {
      input.disabled = true;
      input.blur();
    }
    setLight("--light", 0.05);
    paintMeter(0);
    farewell("Lights out!", 1300);
    // The hearts crack first, the last one too when it ends the walk.
    const hits = ev.find((e) => e.type === "hit");
    if (hits) later(() => takeHitFx(hits.times), 350);
    const ending = ev.find((e) => e.type === "escaped" || e.type === "fell");
    if (ending) return finish(ending, { hit: Boolean(hits) });
    busy = true;
    if (ev.some((e) => e.type === "blocked")) later(() => (sfx.blocked(), toast("Your Iron Helm takes the hit!"), paintStatus()), 350);
    later(() => (rm.answers.some(counts) ? showResult(rm) : showGutter(rm)), 1200);
  }

  // ---------- After a glade ----------

  const nextLabel = () => (s.phase === "nook" ? "To the Wishing Stones" : s.floor === last ? "Onward, to the great tree" : "Onward");
  function onward(btn) {
    btn.addEventListener("click", () => {
      sfx.tap();
      rec.deadline = null;
      save();
      veil(renderPhase, 380);
    });
    // A short pause so a second Enter press can't skip the result unread.
    btn.disabled = true;
    later(() => {
      btn.disabled = false;
      btn.focus({ preventScroll: true });
    }, 700);
  }

  /** How often people said an answer, when the crowd is known. */
  function said(r, name) {
    const rr = crowd?.rooms?.[r.id];
    if (!rr?.entered) return null;
    return pct(rr.answers?.[name] || 0, rr.entered);
  }

  /** The ladder: where your answer sits among the real ones, from Copper up to the hidden jewel. */
  function ladder(r, rm, mine) {
    const pool = r.answers.filter((a) => spellingFor(s, rm, a.rank) && !(rm.boss && r.sealed.includes(a.name)));
    const rows = [];
    const add = (a, me = false) => a && !rows.some((x) => x.a === a) && rows.push({ a, me });
    const firstOf = (t, skip = 0) => pool.filter((a) => shownTier(a.tier) === t)[skip];
    add(firstOf("c"));
    add(firstOf("c", 1));
    for (const idx of mine) add(r.answers[idx], true);
    for (const t of ["s", "g", "e"]) if (!rows.some((x) => shownTier(x.a.tier) === t)) add(firstOf(t));
    const order = { c: 0, f: 1, s: 2, g: 3, e: 4, j: 5 };
    rows.sort((x, y) => order[shownTier(x.a.tier)] - order[shownTier(y.a.tier)]);
    const cells = rows
      .slice(0, 6)
      .map(({ a, me }) => {
        const p = said(r, a.name);
        return html`<div class="r${me ? " me" : ""}">${raw(coin(shownTier(a.tier)))}<span>${sayAs(rm, a)}</span><span class="pct">${p == null ? TIERS[shownTier(a.tier)].name : `${p}%`}</span></div>`;
      })
      .join("");
    const jewelFound = mine.some((i) => r.answers[i].tier === "j");
    const jewel = r.jewel && !jewelFound ? html`<div class="r hidden">${raw(coin("?"))}<span>The Crown Jewel</span><span class="pct">at home</span></div>` : "";
    return `<div class="ladder">${cells}${jewel}</div>`;
  }

  function showResult(rm) {
    busy = false;
    const r = room(rm.pid);
    const m = beast(rm);
    const got = rm.answers.filter(counts);
    const best = [...got].sort((a, b) => TIERS[shownTier(b.tier)].rank - TIERS[shownTier(a.tier)].rank)[0];
    const earned = got.reduce((t, a) => t + a.gold, 0) - rm.eaten;
    const t = TIERS[shownTier(best.tier)];
    const name = r.answers[best.idx].name;
    const shown = sayAs(rm, r.answers[best.idx]);
    const p = said(r, name);
    const sub = p == null ? `${t.name} · ${TIER_SHORT[best.tier]}` : best.tier === "c" ? `${t.name} · ${p}% said it too` : `${t.name} · ${p}% found it`;
    scorePop(`${earned >= 0 ? "+" : ""}${earned}`, earned ? "" : "zero", true);
    const lines = resultLines({ rm, m, r, got, best, earned });
    const said2 = got.length > 1 ? html` and “${sayAs(rm, r.answers[got.find((a) => a !== best).idx])}”` : "";
    setStack(html`<div class="box result">
        <div class="row" style="gap:10px">${raw(coin(shownTier(best.tier), 26))}<div><div class="ttl${shown.length + (said2 ? 12 : 0) > 22 ? " long" : ""}">“${shown}”${raw(said2)}</div><div class="cap" style="margin-top:2px">${sub}</div></div></div>
        ${lines.length ? raw(`<div class="lines">${lines.map((l) => `<div>${l}</div>`).join("")}</div>`) : ""}
        <div class="rule"></div>
        ${raw(ladder(r, rm, got.map((a) => a.idx)))}
      </div>
      <button class="btn" type="button" id="next">${nextLabel()}</button>`);
    paintGlades({ at: rm.floor });
    paintStatus();
    onward(stack.querySelector("#next"));
  }

  /** The lantern burnt out with nothing said: what would have worked. */
  function showGutter(rm) {
    busy = false;
    const r = room(rm.pid);
    const m = beast(rm);
    const lost = rm.blocked ? 0 : rm.hits;
    const sc = wscene.querySelector(".scene");
    sc?.insertAdjacentHTML(
      "beforeend",
      html`<div class="gutter-dark"></div><div class="gutter-out">
        ${raw(lantern(40, { cls: "dim" }))}
        <div class="ttl">The lantern gutters out</div>
        <div class="lost">${raw(lost ? Array.from({ length: lost }, () => heart(false, 22)).join("") + `<span class="num">−${lost}</span>` : `<span class="it">Your Iron Helm took the hit.</span>`)}</div>
        <div class="it">${m.hit}</div>
      </div>`,
    );
    const pool = r.answers.filter((a) => spellingFor(s, rm, a.rank));
    const picks = ["c", "s", "g", "e"].map((t) => pool.find((a) => shownTier(a.tier) === t)).filter(Boolean);
    setStack(html`<div class="box result">
        <div class="cap">These would have worked</div>
        <div class="would">${raw(picks.map((a) => html`<span>${raw(coin(shownTier(a.tier)))}${sayAs(rm, a)}</span>`).join(""))}</div>
      </div>
      <button class="btn ghost" type="button" id="next">Walk on</button>`);
    paintGlades({ at: rm.floor });
    paintStatus();
    onward(stack.querySelector("#next"));
  }

  // ---------- The Wishing Stones ----------

  let charm = -1;
  function renderNook() {
    stopLantern();
    charm = -1;
    const id = "nook";
    const sc = SCENES[id];
    const relics = s.dungeon.relics;
    const art = relics.map((rid, i) => relicHtml(id, rid, sc.spots[`relic${i}`], i, RELIC_COLOR[rid])).join("");
    const hits = relics.map((rid, i) => `<button class="relic-hit" type="button" data-charm="${i}" aria-label="${esc(RELICS[rid].name)}" style="${place(id, [sc.spots[`relic${i}`][0], sc.spots[`relic${i}`][1] + 1], 22, 22)}"></button>`).join("");
    const title = `<div class="scene-title"><div class="cap">${moodFor("nook") === "night" ? "Moonlight" : "Dusk"} · between glades 2 and 3</div><div class="ttl glowtxt">The Wishing Stones</div></div>`;
    setScene(id, { inner: art, over: hits + title, label: "An old tree with a rope and paper tags; three mossy stones before it, each with a glowing charm.", enter: true, mood: moodFor("nook"), keep: [0.1, (SCENES[id].spots.you[1] + 2) / SCENES[id].h] });
    paintGlades({ hide: true });
    paintStatus();
    paintNookStack();
  }
  function paintNookStack() {
    const relics = s.dungeon.relics;
    const cards = relics
      .map((rid, i) => {
        // Each card shows its charm's own picture, and says so when the charm would do nothing for you.
        const idle = relicIdle(s, rid);
        const art = RELIC_ART[rid];
        return html`<button class="box relic-card${charm === i ? " on" : ""}${idle ? " idle" : ""}" type="button" data-charm="${i}" aria-pressed="${charm === i}"><div class="gem" style="--c:${RELIC_COLOR[rid]}"><img class="pixel" src="${art.img}" alt="" style="width:${art.w * 3}px;height:${art.h * 3}px" /></div><div class="ttl">${RELICS[rid].name}</div><div class="it">${relicText(s, rid)}</div>${idle ? raw(html`<div class="it idle-note">${idle}</div>`) : ""}</button>`;
      })
      .join("");
    setStack(html`<div class="choices">${raw(cards)}</div>
      <button class="btn" type="button" id="take" ${charm < 0 ? "disabled" : ""}>${charm < 0 ? "Choose one charm" : `Take the ${RELICS[relics[charm]].name}`}</button>`);
    for (const b of view.querySelectorAll("[data-charm]")) b.addEventListener("click", () => chooseCharm(Number(b.dataset.charm)));
    stack.querySelector("#take").addEventListener("click", () => takeRelic(charm));
  }
  function chooseCharm(i) {
    if (busy || s.phase !== "nook") return;
    if (charm === i) return takeRelic(i);
    charm = i;
    sfx.tap();
    for (const b of wscene.querySelectorAll(".relic-hit")) b.classList.toggle("on", Number(b.dataset.charm) === i);
    paintNookStack();
    stack.querySelector("#take").focus({ preventScroll: true });
  }
  function takeRelic(i) {
    if (busy || s.phase !== "nook" || i < 0) return;
    busy = true;
    const id = s.dungeon.relics[i];
    sfx.relic();
    const art = wscene.querySelector(`.relic-art[data-i="${i}"]`);
    if (art) {
      const [x, y] = centerOf(art);
      drift(x, y - 10, { tier: "night", count: 18, spread: 50 });
      burst(x, y, { tier: "g", kind: "star", count: 10, speed: 160, gravity: 60, life: 0.8 });
    }
    later(() => {
      dispatch({ t: "relic", i });
      busy = false;
      toast(`You take the ${RELICS[id].name}.`);
      veil(renderPhase, 380);
    }, 650);
  }

  // ---------- Endings ----------

  /** The walk is over. hit: a heart is about to crack (takeHitFx repaints the bar then). */
  function finish(e, { hit = false } = {}) {
    stopLantern();
    busy = true;
    // The bar as it ends: no lantern, since no question is open any more, and the hearts left.
    if (!hit) paintStatus();
    const input = stack.querySelector("#answer");
    if (input) {
      input.disabled = true;
      input.blur();
    }
    rec.done = true;
    rec.finishedAt = Date.now();
    // It counts only if it's finished on its own day, or in the grace just after (stillCounts), and the
    // device's date is right. Otherwise it's a past walk: no purse, no streak, not sent.
    if (rec.live && (!stillCounts(rec, rec.finishedAt) || clockLooksOff())) rec.live = false;
    rec.gold = s.gold;
    rec.ending = s.ending;
    rec.floor = floorReached(s);
    rec.deadline = null;
    save();
    if (persistent && rec.live) submitRun(rec);
    if (!persistent) rememberPractice(day, rec);

    const rm = s.rooms.at(-1);
    const r = room(rm.pid);
    const m = beast(rm);
    const actor = wscene.querySelector(".actor");
    if (e.type === "vault") {
      const flawless = s.hearts >= RULES.HEARTS;
      const last = rm.answers.filter(counts).at(-1);
      farewell("Oh, well done! The hoard is yours!", 2400);
      later(() => {
        happyActor(actor, { aside: false });
        // She lifts her head to laugh: her name plate rises with it, clear of her horns.
        const plate = wscene.querySelector(".plate");
        const sc = SCENES[wscene.querySelector(".scene")?.dataset.scene];
        if (plate && sc?.painted) plate.style.top = `${(((actorBox.top - (EMBER_ART.happy[1] - EMBER_BOX.h) * (sc.actorScale || 1) - 3) / sc.h) * 100).toFixed(2)}%`;
        // Keep her raised head in view too (on a phone the scene slides down for her horns).
        if (sc) focus = [Math.max(0, actorBox.top - (EMBER_ART.happy[1] - EMBER_BOX.h) * (sc.actorScale || 1) - 3) / sc.h, focus[1]];
        requestAnimationFrame(fit);
        // No room above her (a phone, the result card up): the plate bows out; the card says it all.
        // Only when it really runs under the glade row: on a wide screen the row is off to the right.
        later(() => {
          const row = view.querySelector("#glades")?.getBoundingClientRect();
          const r = plate?.getBoundingClientRect();
          const under = row && row.height && r && r.top < row.bottom && r.right > row.left && r.left < row.right;
          if (r && (r.top < 0 || under)) plate.classList.add("gone");
        }, 560);
        sfx.happy();
      }, 600);
      later(() => {
        sfx.vault(flawless ? 1 : 0.6);
        bloom(true);
        rain({ tier: "g", count: flawless ? 150 : 90 });
        if (flawless) later(() => rain({ tier: "bloom", kind: "petal", count: 70 }), 700);
        setGold(true);
        petals();
      }, 900);
      later(() => {
        setStack(html`<div class="box result">
            <div class="row" style="gap:10px">${raw(coin(shownTier(last.tier), 26))}<div><div class="ttl${r.answers[last.idx].name.length > 22 ? " long" : ""}">“${r.answers[last.idx].name}”</div><div class="cap" style="margin-top:2px">${TIERS[shownTier(last.tier)].name} · the final strike</div></div></div>
            <div class="it" style="margin-top:10px;font-size:14.5px">“${m.win}”</div>
            <div class="rule"></div>
            <div class="breakdown">
              <div class="r"><span>${TIERS[shownTier(last.tier)].name}</span><span class="num">+${last.gold}</span></div>
              <div class="r"><span>The hoard</span><span class="num" style="color:#ffe08a">+${RULES.VAULT_BONUS}</span></div>
              ${s.hearts ? raw(html`<div class="r"><span class="row" style="gap:6px">Hearts left ${raw(heart(true, 13))} × ${s.hearts}</span><span class="num">+${s.hearts * RULES.HEART_BONUS}</span></div>`) : ""}
            </div>
          </div>
          <button class="btn" type="button" id="home">Walk home</button>`);
        stack.querySelector("#home").addEventListener("click", done);
        later(() => stack.querySelector("#home")?.focus({ preventScroll: true }), 500);
        paintGlades();
      }, 1700);
    } else if (e.type === "escaped") {
      later(() => sfx.phew(), 500);
      say("m", "Mmm… come back tomorrow…", 2400);
      later(() => {
        wscene.querySelector(".scene")?.insertAdjacentHTML(
          "beforeend",
          html`<div class="gutter-dark"></div><div class="gutter-out">${raw(lantern(40, { cls: "dim" }))}<div class="ttl">The lantern gutters out</div><div class="it">Old Ember yawns, and you tiptoe home with your gold. The hoard stays hers, for today.</div></div>`,
        );
        setStack(html`<div class="box result">
            <div class="cap">You slipped home at nightfall</div>
            <div class="breakdown" style="margin-top:8px"><div class="r"><span>Gold in your pocket</span><span class="num">${s.gold}</span></div></div>
            <div class="it" style="margin-top:6px;font-size:14px">${rm.strikes ? `${rm.strikes} of ${s.strikesNeeded} strikes landed.` : "Not a single strike landed. Next time, dig deeper."}</div>
          </div>
          <button class="btn" type="button" id="home">Walk home</button>`);
        stack.querySelector("#home").addEventListener("click", done);
        later(() => stack.querySelector("#home")?.focus({ preventScroll: true }), 500);
        const [x, y] = centerOf(wscene);
        burst(x, y, { tier: "g", count: 14, speed: 200 });
        paintGlades();
      }, 1300);
    } else {
      setLight("--light", 0.06);
      paintMeter(0);
      say("m", "Night night!", 1600);
      later(() => sfx.fell(), 700);
      later(() => {
        wscene.querySelector(".scene")?.insertAdjacentHTML(
          "beforeend",
          html`<div class="gutter-dark"></div><div class="gutter-out">${raw(heart(false, 40))}<div class="ttl">Out of hearts</div><div class="it">Lost in glade ${rm.floor + 1}. ${cap1(m.the)} tucks you in with a leaf. You keep every coin you found.</div></div>`,
        );
        setStack(html`<div class="box result">
            <div class="cap">The walk ends here</div>
            <div class="breakdown" style="margin-top:8px"><div class="r"><span>Gold in your pocket</span><span class="num">${s.gold}</span></div></div>
            <div class="it" style="margin-top:6px;font-size:14px">${rm.floor >= 3 ? "So close to the hoard." : "The wood will be here tomorrow."}</div>
          </div>
          <button class="btn" type="button" id="home">Walk home</button>`);
        stack.querySelector("#home").addEventListener("click", done);
        later(() => stack.querySelector("#home")?.focus({ preventScroll: true }), 500);
        paintGlades();
      }, 1500);
    }
  }

  /** Petals drifting down through the whole glade. */
  function petals() {
    const sc = wscene.querySelector(".scene");
    if (!sc || reducedMotion()) return;
    const bits = Array.from({ length: 26 }, (_, k) => `<i class="petal" style="--x:${(k * 37) % 100}%;--d:${(4 + (k % 5)).toFixed(1)}s;--delay:${(-(k % 7) * 0.7).toFixed(1)}s;--dx:${(k % 2 ? 1 : -1) * (20 + (k % 4) * 15)}px"></i>`).join("");
    sc.insertAdjacentHTML("beforeend", `<div class="petals">${bits}</div>`);
  }

  let finished = false;
  function done() {
    if (finished || !alive) return;
    finished = true;
    onDone?.();
  }

  // ---------- Which screen now ----------

  function renderPhase() {
    if (s.phase === "done") return done();
    if (s.phase === "door") return s.floor === 0 || s.floor === last ? renderMap() : renderFork();
    if (s.phase === "nook") return renderNook();
    if (s.phase === "room") return renderRoom(false);
  }

  renderPhase();

  return () => {
    alive = false;
    stopLantern();
    clearInterval(nextTick);
    cancelAnimationFrame(rollRaf);
    window.removeEventListener("resize", onResize);
    window.visualViewport?.removeEventListener("resize", onResize);
    window.removeEventListener("pq:relight", onRelight);
    onMap(false);
    for (const t of timers) clearTimeout(t);
    timers.clear();
  };
}
