// What the creatures say when they ask their question (the speech bubble in views/delve.js). Pure data
// and one small helper, so the tests can check every line.

/**
 * Every creature asks its question in its own speech bubble, in its own words: a line before it and/or
 * after it that says its twist, so the twist is heard, not read under the question. A few lines per
 * twist, one picked per glade (the same one for everyone that day). [before, after]
 */
export const VOICE = {
  warmup: [["Hello, traveller!", ""], ["Oh! A visitor!", ""], ["", "Just a little one to start!"]],
  warmupLater: [["No tricks from me.", ""], ["An easy one for you.", ""], ["", "Any right answer will do!"]],
  bouncy: [["Boing!", "Nothing boring, mind!"], ["", "Common ones bounce right off!"]],
  haggler: [["", "Silver or better, dearie!"], ["", "I don't buy copper, dearie!"]],
  letter: [["Only words with my letter!", ""], ["My letter, mind!", ""]],
  sleeper: [["Mmh…", "Take your time…"], ["*yawn*", "Don't let the lantern go out…"]],
  collector: [["", "Two of them, please!"], ["I collect them!", "Two, please!"]],
  thick: [["", "Only something really rare gets through!"], ["", "Rare, or it bounces off my skull!"]],
  bargain: [["", "Stuck? I know a hint…"], ["", "I could whisper you a hint…"]],
  hungry: [["", "Feed me something rare!"], ["", "Copper makes me peckish…"]],
  hoard: [["I've eaten the easy ones.", ""], ["The common ones? Eaten.", ""]],
};
/** A question said out loud ends like a sentence ("Name a vegetable.", "…starting with “S”."). */
export const asSentence = (q) => (/[.?!…”"]$/.test(q.trim()) ? q.trim() : `${q.trim()}.`);
/** The creature's words for this glade: { before, question, after }. */
export function voiceFor(rm, question, day = 0) {
  const lines = VOICE[rm.quirk === "warmup" && rm.floor > 0 ? "warmupLater" : rm.quirk] || [["", ""]];
  const [before, after] = lines[(day * 7 + rm.floor * 3 + (rm.door || 0)) % lines.length];
  return { before, question: asSentence(question), after };
}

/**
 * What a creature cries out when you give it something rare (Gold or better), over the burst of petals:
 * a few words in its own voice. One of them, by the moment (see cheerFor).
 */
export const CHEERS = {
  goblin: ["Shiny!", "Ooh, treasure!", "Me likey!"],
  wisp: ["How bright!", "Glimmer!", "Oh, lovely!"],
  slime: ["Blorp!", "Squishy good!", "Wobble wow!"],
  pecker: ["Tweet tweet!", "Chirp-tastic!", "Peck-perfect!"],
  berryhog: ["Berry nice!", "Snuffle-yes!", "Yum-yum!"],
  badger: ["Ooh, crunchy!", "Leaf-tastic!", "Snort! Yes!"],
  tortoise: ["Sloooow wow!", "Worth the wait!", "Splendid!"],
  myctoad: ["Ribbit-ribbit!", "Croak-tastic!", "Spore-some!"],
  mossbunny: ["Hop hop!", "Bun-believable!", "Twitch-twitch!"],
  otter: ["Splash!", "Otterly good!", "Wheee!"],
  soot: ["Fizz-fizz!", "Puff puff!", "Sooty-sweet!"],
  mosssprite: ["Mossy marvel!", "Sprout-tastic!", "Green and glad!"],
  mushguard: ["Well met!", "Spore-tastic!", "Capital!"],
  cloud: ["Sky-high!", "Fluffy-fine!", "Cloud nine!"],
  weasel: ["Sneaky good!", "Zip-zip!", "Weasel-wow!"],
  dandelion: ["Wish granted!", "Puff-puff!", "Floaty-fine!"],
  pinecone: ["Prickly-nice!", "Spiky-yes!", "Snuff-snuff!"],
  stomp: ["Stomp-stomp!", "Rooted joy!", "Timber-tastic!"],
  mouse: ["Squeak!", "Cheese-worthy!", "Eek, lovely!"],
  owlet: ["Hoo-hoo!", "Owl-standing!", "Hoot hoot!"],
  foxsprite: ["Fox-tastic!", "Yip yip!", "Clever you!"],
  waterdrop: ["Drip-drop!", "Splish!", "Sparkly!"],
  dragon: ["Magnificent!", "A worthy gem!", "Hoard-worthy!"],
};
/** A cheer for this creature (look, or "dragon" for Old Ember); n picks which (the moment it's said). */
export const cheerFor = (look, n = 0) => {
  const list = CHEERS[look] || ["Wonderful!"];
  return list[((n % list.length) + list.length) % list.length];
};
