// Placing mode (#/place, from Settings): drag each creature to where it should stand on each path of
// each fork, then copy the exact spots (world pixels of its feet, the numbers in build_forks.py) to send
// on, one animal at a time or all at once. Nothing here changes the game; your moves are kept in this
// browser until you clear them.
import { FORKS, FORK_IDS, forkSceneHtml, forkView, guardBox } from "../forest/fork-scene.js";
import { setShadowTry } from "../forest/scene.js";
import { loadShadows } from "./shadows.js";
import { CREATURES } from "../rules.js";
import { esc } from "../util.js";

const KEY = "pocketquest:placing";
const load = () => {
  try {
    return JSON.parse(localStorage.getItem(KEY)) || {};
  } catch {
    return {};
  }
};
const save = (moves) => {
  try {
    localStorage.setItem(KEY, JSON.stringify(moves));
  } catch {}
};

export function renderPlace({ view, setCleanup }) {
  const looks = Object.keys(CREATURES);
  let moves = load(); // { fork: { path: { look: [x, y] } } }
  // Shadows set in the Shadows view (#/shadows) show here too.
  for (const [l, v] of Object.entries(loadShadows())) setShadowTry(l, v);
  let fork = FORK_IDS.includes(sessionStorage.getItem("pq:place-fork")) ? sessionStorage.getItem("pq:place-fork") : FORK_IDS[0];
  let li = Math.max(0, looks.indexOf(sessionStorage.getItem("pq:place-look")));
  let night = false;
  let k = { s: 1, tx: 0, ty: 0 };
  document.body.dataset.view = "place";

  view.innerHTML = `<div class="placing">
    <div class="place-bar">
      <a class="btn ghost small" href="#/" aria-label="Leave placing mode">✕</a>
      <select id="pl-look" aria-label="Animal">${looks.map((l) => `<option value="${l}">${esc(CREATURES[l].name)}</option>`).join("")}</select>
      <select id="pl-fork" aria-label="Fork">${FORK_IDS.map((f) => `<option value="${f}">${f}</option>`).join("")}</select>
      <button class="btn ghost small" id="pl-prev" type="button" aria-label="Back: previous fork, or the previous animal">◀</button>
      <button class="btn ghost small" id="pl-next" type="button" aria-label="Next: the next fork, then the next animal">▶</button>
      <button class="btn ghost small" id="pl-light" type="button">Night</button>
    </div>
    <div class="place-stage"><div class="place-scene"></div><div class="place-ui"></div></div>
    <div class="place-foot">
      <span id="pl-info" class="small-note"></span>
      <button class="btn small" id="pl-copy-look" type="button">Copy this animal</button>
      <button class="btn small" id="pl-copy" type="button">Copy all</button>
      <button class="btn ghost small" id="pl-reset" type="button">Reset here</button>
      <button class="btn ghost small" id="pl-clear" type="button">Clear all</button>
    </div>
    <textarea id="pl-out" readonly rows="4" aria-label="Your moves"></textarea>
  </div>`;
  const $ = (s) => view.querySelector(s);
  const stage = $(".place-stage");
  const holder = $(".place-scene");
  const ui = $(".place-ui");

  /** This fork with your moves in: each path's spot for this creature. */
  const placeFor = (look) => {
    const p = FORKS[fork];
    const at = [0, 1].map((i) => ({ ...(p.at?.[i] || {}), ...(moves[fork]?.[i]?.[look] ? { [look]: moves[fork][i][look] } : {}) }));
    return { ...p, at };
  };
  const spotOf = (place, i, look) => place.at?.[i]?.[look] || place.spots[i];
  /** Every move: [fork, path, look, [x, y]]. */
  const all = () => Object.entries(moves).flatMap(([f, paths]) => Object.entries(paths).flatMap(([i, byLook]) => Object.entries(byLook).map(([l, xy]) => [f, Number(i), l, xy])));

  /** Your moves as text to send: all of them, or one animal's. */
  function text(only = null) {
    const list = all().filter(([, , l]) => !only || l === only);
    const what = only ? CREATURES[only].name : "all animals";
    if (!list.length) return `No moves yet for ${what}.`;
    const data = {};
    for (const [f, i, l, xy] of list) ((data[f] ||= {})[i] ||= {})[l] = xy;
    const lines = list.map(([f, i, l, [x, y]]) => `${f} ${i ? "right" : "left"} ${l}: [${x}, ${y}]`);
    return `Placing mode spots, ${what} (world px, feet):\n${lines.join("\n")}\n\n${JSON.stringify(data)}`;
  }

  function out() {
    const look = looks[li];
    const list = all();
    const mine = list.filter(([, , l]) => l === look).length;
    const animals = new Set(list.map(([, , l]) => l)).size;
    $("#pl-info").textContent = `${CREATURES[look].name}: animal ${li + 1} of ${looks.length}, fork ${FORK_IDS.indexOf(fork) + 1} of ${FORK_IDS.length}${mine ? ` · ${mine} moved for it` : ""}${list.length ? ` · ${list.length} moves, ${animals} animals in all` : ""}`;
    $("#pl-out").value = text(look);
  }

  function draw() {
    const look = looks[li];
    sessionStorage.setItem("pq:place-fork", fork);
    sessionStorage.setItem("pq:place-look", look);
    $("#pl-fork").value = fork;
    $("#pl-look").value = look;
    $("#pl-light").textContent = night ? "Dusk" : "Night";
    const place = placeFor(look);
    holder.innerHTML = forkSceneHtml({ place, doors: [{ look }, { look }], hero: "wanderer", labels: ["", ""], night });
    const sc = holder.querySelector(".scene");
    const w = stage.clientWidth;
    const h = stage.clientHeight;
    sc.style.height = `${h}px`;
    k = forkView(w, h, { place });
    sc.querySelector(".art-world").style.transform = `translate(${k.tx}px, ${k.ty}px) scale(${k.s})`;
    // A handle over each guardian (over the painting's front pieces too), to drag it by.
    ui.innerHTML = [0, 1]
      .map((i) => {
        const b = guardBox(place, i, look);
        const moved = moves[fork]?.[i]?.[look];
        return `<div class="place-handle${moved ? " moved" : ""}" data-i="${i}" style="left:${(b.x - b.w / 2) * k.s + k.tx}px;top:${b.top * k.s + k.ty}px;width:${b.w * k.s}px;height:${(b.bottom - b.top) * k.s}px"><span>${i ? "R" : "L"}</span></div>`;
      })
      .join("");
    for (const hd of ui.querySelectorAll(".place-handle")) drag(hd, place, look, sc);
    out();
  }

  function drag(hd, place, look, sc) {
    const i = Number(hd.dataset.i);
    const actor = sc.querySelector(`.guard[data-path="${i}"]`);
    hd.addEventListener("pointerdown", (e) => {
      e.preventDefault();
      hd.setPointerCapture?.(e.pointerId);
      const x0 = e.clientX;
      const y0 = e.clientY;
      const left = parseFloat(hd.style.left);
      const top = parseFloat(hd.style.top);
      const aLeft = parseFloat(actor?.style.left || 0);
      const aTop = parseFloat(actor?.style.top || 0);
      let dx = 0;
      let dy = 0;
      const move = (ev) => {
        dx = ev.clientX - x0;
        dy = ev.clientY - y0;
        hd.style.left = `${left + dx}px`;
        hd.style.top = `${top + dy}px`;
        if (actor) {
          actor.style.left = `${aLeft + dx / k.s}px`;
          actor.style.top = `${aTop + dy / k.s}px`;
        }
      };
      const up = () => {
        hd.removeEventListener("pointermove", move);
        hd.removeEventListener("pointerup", up);
        if (Math.abs(dx) + Math.abs(dy) < 2) return;
        const [sx, sy] = spotOf(place, i, look);
        ((moves[fork] ||= {})[i] ||= {})[look] = [Math.round(sx + dx / k.s), Math.round(sy + dy / k.s)];
        save(moves);
        draw();
      };
      hd.addEventListener("pointermove", move);
      hd.addEventListener("pointerup", up);
    });
  }

  // One animal at a time: every fork for it, then on to the next animal.
  const step = (d) => {
    let fi = FORK_IDS.indexOf(fork) + d;
    if (fi >= FORK_IDS.length) (fi = 0), (li = (li + 1) % looks.length);
    if (fi < 0) (fi = FORK_IDS.length - 1), (li = (li - 1 + looks.length) % looks.length);
    fork = FORK_IDS[fi];
    draw();
  };
  $("#pl-prev").addEventListener("click", () => step(-1));
  $("#pl-next").addEventListener("click", () => step(1));
  $("#pl-look").addEventListener("change", (e) => {
    li = looks.indexOf(e.target.value);
    fork = FORK_IDS[0];
    draw();
  });
  $("#pl-fork").addEventListener("change", (e) => {
    fork = e.target.value;
    draw();
  });
  $("#pl-light").addEventListener("click", () => {
    night = !night;
    draw();
  });
  // Reset here: this animal at this fork.
  $("#pl-reset").addEventListener("click", () => {
    for (const i of [0, 1]) delete moves[fork]?.[i]?.[looks[li]];
    save(moves);
    draw();
  });
  $("#pl-clear").addEventListener("click", () => {
    if (!confirm("Clear every move you've made in placing mode?")) return;
    moves = {};
    save(moves);
    draw();
  });
  const copy = async (btn, only) => {
    const t = $("#pl-out");
    t.value = text(only);
    t.select();
    const label = btn.textContent;
    try {
      await navigator.clipboard.writeText(t.value);
      btn.textContent = "Copied!";
    } catch {
      document.execCommand?.("copy");
      btn.textContent = "Select the box";
    }
    setTimeout(() => (btn.textContent = label), 1600);
  };
  $("#pl-copy-look").addEventListener("click", (e) => copy(e.currentTarget, looks[li]));
  $("#pl-copy").addEventListener("click", (e) => copy(e.currentTarget, null));
  const key = (e) => {
    if (e.target.closest("select, textarea")) return;
    if (e.key === "ArrowRight") step(1);
    if (e.key === "ArrowLeft") step(-1);
  };
  window.addEventListener("keydown", key);
  const onResize = () => draw();
  window.addEventListener("resize", onResize);
  setCleanup(() => {
    window.removeEventListener("keydown", key);
    window.removeEventListener("resize", onResize);
  });
  draw();
}
