// The illustrated forks. The first, the mushroom fork, is the painted scene (FORK_ART, cut by
// tools/scenes/build_fork.py) with its layers brought back to life: the glowing things breathe, the
// canopy sways, the slime bobs in its halo, and the creatures of the two paths wait at the tree hollow
// (left) and the mushroom house (right). The others (MORE_FORKS, tools/scenes/build_forks.py) were
// painted from it on this PC, so they share its world and its view: the willow and the lantern gate,
// the mossy arch and the hedge tunnel, the lantern stair and the crystal grotto. Each fork of a walk is
// a different one. Positions are in the paintings' own pixels (the world).
import { FORK_ART } from "./fork-art.js";
import { MORE_FORKS } from "./forks-art.js";
import { paint, paintBg } from "./pics.js";
import { SPRITES, HERO_ART, FORK_IDLE } from "./art-data.js";
import { lightLayer, figureStyle, idleOf, shadowHtml } from "./scene.js";
import { PLACED } from "./fork-placed.js";

const B = FORK_ART.base;
const at = (x, y) => [B.x + x, B.y + y]; // a point in the clean scene → the world

export const FORK = {
  id: "mushroom",
  art: FORK_ART,
  names: ["the hollow", "the mushroom gate"],
  label: "A fork in an enchanted wood: one path over a stone bridge to a hollow tree, the other to a glowing mushroom house.",
  // Where the two paths' guardians stand (their feet): the goblin's and the wisp's spots.
  spots: [
    [FORK_ART.chars.goblin.x, FORK_ART.chars.goblin.y],
    [FORK_ART.chars.wisp.x, FORK_ART.chars.wisp.y],
  ],
  // Each creature's own spot on each path, placed by hand (fork-placed.js).
  at: [0, 1].map((i) => PLACED.mushroom?.[i] || {}),
  // Tap areas for the two paths: the tree hollow and the bridge; the mushroom house.
  hits: [
    [...at(80, 250), 300, 420],
    [...at(470, 400), 270, 360],
  ],
  // What to keep in view: the whole clean scene across, from the treetops down to the traveller.
  focus: { x0: B.x, x1: B.x + B.w, y0: B.y + 90, y1: FORK_ART.chars.traveller.y + 40 },
  // Warm and magic lights that flicker and breathe: [x, y, radius, colour, speed].
  glows: [
    [...at(250, 470), 60, "#ffcf7a", 2.6],
    [...at(433, 682), 56, "#ffcf7a", 3.1],
    [...at(190, 960), 56, "#ffcf7a", 2.8],
    [...at(492, 960), 56, "#ffcf7a", 3.4],
    [...at(452, 640), 48, "#ff8a4a", 1.9],
    [...at(600, 640), 150, "#ffd890", 4.5],
    [...at(605, 470), 120, "#ff9a6a", 5.2],
    [...at(270, 820), 110, "#6ee8ff", 3.8],
  ],
  // Points along the stream, for its glints.
  stream: [at(640, 355), at(560, 400), at(470, 455), at(390, 510), at(320, 560), at(240, 610), at(160, 645), at(70, 668)],
};

/** A painted place from MORE_FORKS, in the same shape as FORK. */
function otherFork(id) {
  const f = MORE_FORKS[id];
  const [p0, p1] = f.paths;
  const t = f.traveller;
  const xs = [p0.spot[0], p1.spot[0]];
  // Room over the guardians for the tallest creature and its medal.
  const ys = [p0.spot[1] - 250, p1.spot[1] - 250];
  return {
    id,
    names: f.paths.map((p) => p.name),
    label: f.label,
    art: { w: f.w, h: f.h, img: f.dusk.img, night: f.night?.img || null, badge: FORK_ART.badge },
    lights: { dusk: f.dusk, night: f.night || f.dusk },
    figures: { dusk: f.dusk.figures, night: (f.night || f.dusk).figures },
    spots: f.paths.map((p) => p.spot),
    at: f.paths.map((p, i) => ({ ...(p.at || {}), ...(PLACED[id]?.[i] || {}) })),
    hits: f.paths.map((p) => p.hit),
    // Parts of the painting nearer than the guardians (fallen stones, a signpost): drawn over them.
    occluders: f.occluders || [],
    // By night (a painting of its own, not always drawn in quite the same place): see atLight.
    night: { spots: f.paths.map((p) => p.night_spot || p.spot), occluders: f.night_occluders || f.occluders || [] },
    traveller: t,
    // Like the mushroom fork: its clean scene across (base), from the treetops down to the traveller;
    // or, without one, both guardians and their medals across.
    focus: f.base
      ? { x0: f.base[0], x1: f.base[0] + f.base[2], y0: f.base[1] + 90, y1: t[1] + 40 }
      : { x0: Math.min(...xs) - 110, x1: Math.max(...xs) + 110, y0: Math.min(...ys) - 90, y1: t[1] + 40 },
    stream: [],
  };
}

export const FORKS = { mushroom: FORK, ...Object.fromEntries(Object.keys(MORE_FORKS).map((id) => [id, otherFork(id)])) };
export const FORK_IDS = Object.keys(FORKS);

/** Which place a walk's fork is: a different one at each fork of a walk, in another order each day. */
export const forkFor = (day, floor) => FORKS[FORK_IDS[(((day + floor - 1) % FORK_IDS.length) + FORK_IDS.length) % FORK_IDS.length]];

/** A fork as it is in this light: by night its guardians' spots and front pieces can move with the painting. */
export const atLight = (place, night) => (night && place.night ? { ...place, ...place.night } : place);

/** The painting for this light. */
export const forkPainting = (place, night) => (night && place.art.night ? place.art.night : place.art.img);

/** Sparkles rise gently from these (the lanterns, the mushroom house, the slime's halo). */
/** The medal over each path: the painted frame, with the guardian's portrait set in it. */
/** The medal's size in the painting: half the painted one, and empty (its guardian stands right under it). */
export const BADGE = { w: FORK_ART.badge.w / 2, h: FORK_ART.badge.h / 2 };
export const badgeHtml = (i, d) => `<button class="path-pin art" type="button" data-pick="${i}" tabindex="-1" aria-hidden="true" style="--d:${d}s;width:${BADGE.w}px;height:${BADGE.h}px"><img class="frame" src="${FORK_ART.badge.img}" alt="" /></button>`;

export const forkSources = (place = FORK, night = false) =>
  place === FORK ? mushroomSources() : place.lights[night ? "night" : "dusk"].glows.map(([x, y, , c]) => [x, y, c]);
const mushroomSources = () => [
  [...at(605, 520), "#ffd890"],
  [...at(600, 660), "#ffe7a0"],
  [...at(270, 790), "#6ee8ff"],
  [...at(250, 470), "#ffcf7a"],
  [...at(433, 682), "#ffcf7a"],
];

/**
 * World pixels per sprite pixel at a fork. Every creature keeps its own size (a mouse is smaller than a
 * stone troll), all at the same pixel size, a little finer than the painting's own pixels.
 */
export const FORK_PX = 2.5;

/** The box a guardian fills at a fork, in world pixels: { x (middle), top, bottom (feet), w, h, lift }. */
/** The mushroom fork's own painted guardians (its slime is part of the scene, so it isn't one). */
const PAINTED = new Set(["goblin", "wisp"]);
export function guardBox(place, i, look) {
  // Each creature can have its own spot on a path (place.at[i][look]: a small one on a step, a big one
  // on open ground); else the path's.
  const [x, y] = place.at?.[i]?.[look] || place.spots[i];
  const c = place.id === "mushroom" && PAINTED.has(look) && FORK_ART.chars[look];
  if (c) return { x, top: y - c.h, bottom: y, w: c.w, h: c.h, lift: 0, hx: x };
  const sp = SPRITES[look] || SPRITES.goblin;
  const k = FORK_PX * (place.scale || 1);
  const lift = (sp.float || 0) * k;
  const w = sp.w * k;
  // hx: over its head (a creature with a long tail or a branch isn't centred in its box).
  return { x, top: y - lift - sp.h * k, bottom: y - lift, w, h: sp.h * k, lift, hx: x - w / 2 + (sp.hx ?? 0.5) * w };
}
/** Where a path's medal floats: just over its own guardian's head (floaters bob, so a little higher). */
export const badgeAt = (place, i, look) => {
  const b = guardBox(place, i, look);
  return [b.hx, b.top - 22 - (b.lift ? b.h * 0.08 : 0) - BADGE.h / 2];
};
/**
 * Where a path's card hangs (its top centre): beside its own guardian, on the side toward the middle of
 * the scene, a gap away, its top level with the guardian's head. half: half the card's width, gap: the
 * gap, both in world pixels (the card is sized in screen pixels, so the caller converts).
 */
export const cardAt = (place, i, look, half, gap, { height = 0, other = null } = {}) => {
  const b = guardBox(place, i, look);
  const side = i ? -1 : 1;
  const x = b.x + side * (b.w / 2 + gap + half);
  let y = b.top + Math.min(24, b.h * 0.15);
  // Never over the traveller, nor over the other path's medal: then it hangs higher.
  const hits = (r) => x - half < r.x1 && x + half > r.x0 && y < r.y1 && y + height > r.y0;
  const you = travellerBox(place);
  if (height && hits(you)) y = you.y0 - gap - height;
  if (height && other) {
    const [mx, my] = badgeAt(place, 1 - i, other);
    const m = { x0: mx - BADGE.w / 2, x1: mx + BADGE.w / 2, y0: my - BADGE.h / 2, y1: my + BADGE.h / 2 };
    if (hits(m)) y = Math.min(y, m.y0 - gap - height);
    // Nor over the other guardian itself (the forks whose guardians stand close): then over its medal.
    const g = guardBox(place, 1 - i, other);
    if (hits({ x0: g.x - g.w / 2, x1: g.x + g.w / 2, y0: g.top, y1: g.bottom })) y = Math.min(y, m.y0 - gap - height);
  }
  return [x, y];
};
/** The traveller's box at a fork, in world pixels. */
export function travellerBox(place) {
  const t = FORK_ART.chars.traveller;
  const [x, y] = place.traveller || [t.x, t.y];
  return { x0: x - t.w / 2, x1: x + t.w / 2, y0: y - t.h, y1: y };
}
/** A letter lock's tag: beside the guardian's head, on the outer side. */
export const tagAt = (place, i, look) => {
  const b = guardBox(place, i, look);
  return [b.x + (i ? 1 : -1) * (b.w / 2 + 18), b.top + Math.min(40, b.h * 0.35)];
};

const img = (src, x, y, w, h, cls = "", extra = "") => `<img class="${cls}" src="${src}" alt="" draggable="false" style="left:${x}px;top:${y}px;width:${w}px;height:${h}px;${extra}" />`;

/** Whose idle loop a guardian plays: the painted figure's at the mushroom fork, else its sprite's. */
const guardLoop = (place, look) => (place.id === "mushroom" && PAINTED.has(look) && FORK_ART.chars[look] ? { idle: FORK_IDLE[look], id: `fork-${look}` } : { idle: SPRITES[look]?.idle, id: look });

/** Someone standing at a spot, feet at [x, y]: a painted creature (the mushroom fork's own), or a
 * small sprite drawn larger. */
function standing(place, i, look, { cls = "", attrs = "", lit = null, lead = null } = {}) {
  const c = place.id === "mushroom" && PAINTED.has(look) && FORK_ART.chars[look];
  const b = guardBox(place, i, look);
  // A painted creature carries the painting's own light; a sprite takes the light of its spot. Both play
  // their idle loop (if it's drawn); the second path's guardian half a loop after the first (lead: the
  // first one's look), so the two never breathe in step.
  const [litCls, litVars, rim] = figureStyle(c ? null : lit);
  const from = lead ? guardLoop(place, lead) : null;
  if (c) {
    const idle = idleOf(FORK_IDLE[look], `fork-${look}`, i, from);
    return `<div class="art-actor${idle.cls} ${cls}" data-look="${look}"${idle.attrs} ${attrs} style="${idle.style}left:${b.x - c.w / 2}px;top:${b.top}px;width:${c.w}px;height:${c.h}px"><span class="a-shadow"></span><img class="a-img" src="${idle.img || c.img}" alt="" draggable="false" /></div>`;
  }
  const sp = SPRITES[look];
  // A sprite at the fork's pixel size, lit where it stands, floating if it floats.
  const idle = idleOf(sp.idle, look, i, from);
  const src = idle.img || sp.img;
  return `<div class="art-actor pixel-actor${sp.float ? " floats" : ""}${sp.emits ? " emits" : ""}${litCls}${idle.cls} ${cls}" data-look="${look}"${idle.attrs} ${attrs} style="${litVars}${idle.style}left:${b.x - b.w / 2}px;top:${b.top}px;width:${b.w}px;height:${b.h}px;--lift:${Math.round((b.lift * 100) / b.h)}%">${shadowHtml(sp, look)}<img class="a-img" src="${src}" data-happy="${sp.happy}" data-img="${src}" alt="" draggable="false" />${lightLayer(src, sp.w, sp.h, rim)}</div>`;
}

/** The traveller, feet at [x, y]: the painted one for the Wanderer, any other character's sprite
 * drawn larger. */
function traveller(hero, [x, y] = [FORK_ART.chars.traveller.x, FORK_ART.chars.traveller.y], lit = null) {
  const t = FORK_ART.chars.traveller;
  // The painted Wanderer at their own spot in the mushroom fork already has its light.
  const own = x === t.x && y === t.y;
  const [litCls, litVars, rim] = figureStyle(hero === "wanderer" && own ? null : lit);
  if (hero === "wanderer") return `<div class="art-actor you${litCls}" style="${litVars}left:${x - t.w / 2}px;top:${y - t.h}px;width:${t.w}px;height:${t.h}px"><span class="a-shadow"></span><img class="a-img" src="${t.img}" alt="" draggable="false" />${litCls ? lightLayer(t.img, t.w, t.h, rim) : ""}</div>`;
  const h = HERO_ART[hero] || HERO_ART.wanderer;
  const k = t.h / h.h;
  return `<div class="art-actor you pixel-actor${litCls}" style="${litVars}left:${x - (h.w * k) / 2}px;top:${y - h.h * k}px;width:${h.w * k}px;height:${h.h * k}px"><span class="a-shadow"></span><img class="a-img" src="${h.img}" alt="" draggable="false" />${lightLayer(h.img, h.w, h.h, rim)}</div>`;
}

/** The parts of the painting in front of the guardians, cut from the painting itself and laid over them. */
const frontHtml = (place, painting, glows = "") =>
  (place.occluders || []).map((poly) => `<div class="art-front" aria-hidden="true" style="clip-path:polygon(${poly.map(([x, y]) => `${x}px ${y}px`).join(",")})">${paint(painting, `class="art-bg" alt="" draggable="false"`)}${glows}</div>`).join("");

const hitsHtml = (place, labels) => place.hits.map(([x, y, w, h], i) => `<button class="art-hit" type="button" data-pick="${i}" aria-label="${labels[i]}" style="left:${x}px;top:${y}px;width:${w}px;height:${h}px"></button>`).join("");

/** One of the other forks: its painting in this light, its lights breathing, the guardians and you. */
function otherForkHtml(place, { doors, hero, labels, night }) {
  const A = place.art;
  const painting = forkPainting(place, night);
  const figs = place.figures[night ? "night" : "dusk"] || [];
  const glows = place.lights[night ? "night" : "dusk"].glows.map(([x, y, r, c], i) => `<span class="art-glow" style="left:${x - r}px;top:${y - r}px;width:${r * 2}px;height:${r * 2}px;--c:${c};--sp:${(2.4 + ((i * 0.9) % 3)).toFixed(1)}s;--d:${(-i * 0.7).toFixed(1)}s"></span>`).join("");
  return `<div class="scene art${night && A.night ? " night" : ""}" data-scene="fork-art" data-fork="${place.id}" role="img" aria-label="${place.label}">
    <div class="art-world" style="width:${A.w}px;height:${A.h}px">
      ${paint(painting, `class="art-bg" alt="" draggable="false"`)}
      <div class="art-canopy" style="${paintBg(painting)};background-size:${A.w}px ${A.h}px;height:${B.y + 520}px"></div>
      ${glows}
      ${doors.map((d, i) => standing(place, i, d.look, { cls: "guard", attrs: `data-path="${i}"`, lit: figs[i], lead: i ? doors[0].look : null })).join("")}
      ${frontHtml(place, painting, glows)}
      ${traveller(hero, place.traveller, figs[2])}
      ${hitsHtml(place, labels)}
    </div>
    <div class="art-ui"><canvas class="art-particles" aria-hidden="true"></canvas></div>
  </div>`;
}

/** The whole painted scene. place: which fork (FORKS); doors: its two doors (their looks stand at the
 * paths). */
export function forkSceneHtml({ place = FORK, doors, hero, labels, night = false }) {
  if (place.id !== "mushroom") return otherForkHtml(place, { doors, hero, labels, night });
  const A = FORK_ART;
  // Later in the walk the fork is the same place by moonlight (tools/scenes/build_fork.py).
  const painting = night && A.night ? A.night : A.img;
  const fx = A.fx;
  const glows = FORK.glows.map(([x, y, r, c, sp], i) => `<span class="art-glow" style="left:${x - r}px;top:${y - r}px;width:${r * 2}px;height:${r * 2}px;--c:${c};--sp:${sp}s;--d:${(-i * 0.7).toFixed(1)}s"></span>`).join("");
  const halo = fx.halo;
  const slime = A.chars.slime;
  const hits = hitsHtml(FORK, labels);
  const figs = A.figures?.[night && A.night ? "night" : "dusk"] || [];
  return `<div class="scene art${night && A.night ? " night" : ""}" data-scene="fork-art" data-fork="mushroom" role="img" aria-label="${FORK.label}">
    <div class="art-world" style="width:${A.w}px;height:${A.h}px">
      ${paint(painting, `class="art-bg" alt="" draggable="false"`)}
      <div class="art-canopy" style="${paintBg(painting)};background-size:${A.w}px ${A.h}px;height:${B.y + 520}px"></div>
      ${img(fx.beams.img, fx.beams.x, fx.beams.y, fx.beams.w, fx.beams.h, "art-fx beams")}
      ${glows}
      ${img(fx.gold.img, fx.gold.x, fx.gold.y, fx.gold.w, fx.gold.h, "art-fx gold")}
      ${img(fx.purple.img, fx.purple.x, fx.purple.y, fx.purple.w, fx.purple.h, "art-fx purple")}
      ${img(fx.runes.img, fx.runes.x, fx.runes.y, fx.runes.w, fx.runes.h, "art-fx runes")}
      ${doors[0]?.look === "goblin" ? img(A.chars.sack.img, A.chars.sack.x - A.chars.sack.w / 2, A.chars.sack.y - A.chars.sack.h, A.chars.sack.w, A.chars.sack.h, "art-prop") : ""}
      ${doors.map((d, i) => standing(place, i, d.look, { cls: "guard", attrs: `data-path="${i}"`, lit: figs[i], lead: i ? doors[0].look : null })).join("")}
      <div class="art-slime" style="left:${halo.x}px;top:${halo.y}px;width:${halo.w}px;height:${halo.h}px">
        <img class="art-fx halo" src="${halo.img}" alt="" draggable="false" />
        ${img(slime.img, slime.x - slime.w / 2 - halo.x, slime.y - slime.h - halo.y, slime.w, slime.h, "slime-body")}
      </div>
      ${traveller(hero, undefined, figs[2])}
      ${hits}
    </div>
    <div class="art-ui"><canvas class="art-particles" aria-hidden="true"></canvas></div>
  </div>`;
}

/**
 * Where the world goes in a window of this size: the focus fills the width it can, the painting
 * always covers the window, and on wide screens the paths sit in the room left of the panel.
 */
export function forkView(vw, vh, { free = vw, top = 0, room = 1, place = FORK } = {}) {
  const f = place.focus;
  const A = place.art;
  const s = Math.max(vw / A.w, vh / A.h, room * Math.min(free / (f.x1 - f.x0), (vh - top) / (f.y1 - f.y0)));
  const cx = ((f.x0 + f.x1) / 2) * s;
  const cy = ((f.y0 + f.y1) / 2) * s;
  let tx = free / 2 - cx;
  let ty = top + (vh - top) / 2 - cy;
  tx = Math.min(0, Math.max(vw - A.w * s, tx));
  ty = Math.min(0, Math.max(vh - A.h * s, ty));
  return { s, tx, ty };
}
