// Words the walk shows that must match the rules (views/delve.js): the creatures' reactions, a path
// card's needs, the lantern's seconds and a glade's result lines. Pure, so the tests can check them.
import { ARMOR } from "./rules.js";
import { html, esc } from "./util.js";

/**
 * What a creature blurts out when you answer. Each tier gets its own reaction. None of them waves you
 * on: a Collector still wants a second answer, and a won glade says its own farewell.
 */
export const REACT = {
  c: ["Oh, that one! Everyone says that.", "Yes! That's right!", "A classic. Good one!"],
  f: ["Oh, that one! Everyone says that.", "Yes! That's right!"],
  s: ["Ooh, lovely!", "Oh, nice one!", "How nice! I like that one."],
  g: ["Oh, what a find!", "Wonderful! Hardly anyone says that!", "You know your stuff!"],
  e: ["Wow! Where did you learn that?!", "Oh my! Nobody knows that one!", "Goodness, how lovely!"],
  j: ["My Crown Jewel! You found it!", "The jewel! I'm so happy!", "How did you know?! Hooray!"],
  miss: ["Never heard of it!", "Nope!", "Is that even a thing?"],
  letter: ["Wrong letter!", "That's not my letter!", "Read my cap!"],
  sealed: ["Already ate that one.", "Mm, tasted that earlier."],
  dupe: ["You said that already!", "Again? Really?"],
  armored: ["Right, but too common for me!", "Hmm, everyone says that one. Something rarer?", "Close! Try a rarer one."],
};

/**
 * A path card's small print: the armour to beat and the ×2 pay. A letter lock's letter is already in
 * the line above ("Must start with “H”"), so it isn't said again. The pay says "double gold", not
 * "Gold ×2", which read like two Gold answers.
 */
export function needsLine(d) {
  return [d.armor && d.armor !== "none" ? ARMOR[d.armor].short : "", d.elite ? "double gold" : ""].filter(Boolean).join(" · ");
}

/**
 * The seconds shown by the lantern. The lantern waits a moment while the glade opens (the door's
 * grace), full: the count waits with it at the lantern's own length instead of reading 37 of 35.
 */
export const lanternSecs = (left, total) => Math.max(0, Math.min(Math.round(total / 1000), Math.ceil(left / 1000)));

/**
 * The lines on a glade's result card, as HTML: what cost you, what paid, and why. rm: the room, m: its
 * creature (beast), r: its question, got: the answers that counted, best: the best of them, earned:
 * its gold.
 */
export function resultLines({ rm, m, r, got, best, earned }) {
  const lines = [];
  const took = rm.blocked ? `<span class="good">Your Iron Helm took the hit.</span>` : `<span class="hurt">−1 heart</span>`;
  // The Collector's lantern went out after one answer: that costs a heart, unless the Iron Helm took it.
  if (rm.result === "partial") lines.push(`${rm.blocked ? "The lantern went out before the second answer." : `<span class="hurt">The lantern went out before the second answer.</span>`} ${took}`);
  else if (!got.every((a) => a.through)) lines.push(`Too common to get through its armour. ${esc(m.hit)} ${took}`);
  if (best?.lucky) lines.push(`<span class="good">Your Lucky Coin turned it into Gold!</span>`);
  if (got.some((a) => a.clover)) lines.push(`<span class="good">Your Four-leaf Clover turned Copper into Silver!</span>`);
  if (rm.quirk === "haggler" && got.some((a) => a.tier === "c")) lines.push(`The ${esc(m.name)} paid nothing for Copper.`);
  if (rm.quirk === "haggler" && got.some((a) => a.tier === "s" || a.tier === "g")) lines.push(`<span class="good">The ${esc(m.name)} paid ×1.5 for your find.</span>`);
  if (rm.eaten) lines.push(`<span class="hurt">The ${esc(m.name)} ate ${rm.eaten} of your gold.</span>`);
  // A Hungry creature's ×3 for a Gem or a Jewel is instead of the path's ×2, not on top of it (goldFor).
  const tripled = (a) => rm.quirk === "hungry" && (a.tier === "e" || a.tier === "j");
  if (got.some(tripled)) lines.push(`<span class="good">The ${esc(m.name)} paid triple for something rare${rm.elite ? ", instead of double" : ""}!</span>`);
  if (rm.healed) lines.push(`<span class="good">The ${esc(m.name)} was so delighted it healed a heart.</span>`);
  if (rm.bounced) lines.push(`<span class="good">One wrong answer bounced off the ${esc(m.name)}.</span>`);
  if (rm.hinted) lines.push(`You took the ${esc(m.name)}'s hint, so this glade paid half.`);
  if (rm.elite && earned > 0 && got.some((a) => a.gold > 0 && !tripled(a))) lines.push(`<span class="good">The ×2 path doubled it.</span>`);
  if (got.some((a) => a.tier === "j")) lines.push(html`<span class="good">You found the Crown Jewel!${r.jewelNote ? ` ${r.jewelNote}.` : ""}</span>`);
  return lines;
}
