// The answer lists and each room's loot table, decoded on first use. Pure (no DOM), so the server
// uses the same code to check results.
import { LISTS } from "./data/lists.js";
import { PROMPTS } from "./data/prompts.js";
import { decode } from "./codec.js";
import { keyOf, keyVariants, distance, typoBudget } from "./match.js";

const decoded = new Map();

// Rules 8 matching (runs from before keep the old way, see keysFor): ordinals fold ("Henry the
// Eighth", folding 2 in match.js); an all-capitals short form isn't made plural ("Cars" isn't CAR,
// the Central African Republic); and these aliases, which pointed at a rarer answer than people
// mean, point at the one they mean: Ram and Bull are Aries and Taurus as much as the Chinese Goat and Ox.
const ALIAS_FIXES = { zodiac: { Ram: "Aries", Bull: "Taurus" } };

/** An answer's name and aliases, with the rules 8 alias fixes when fixed. */
function spellings(listKey, name, aliases, fixed) {
  const fix = fixed && ALIAS_FIXES[listKey];
  if (!fix) return [name, ...aliases];
  return [name, ...aliases.filter((a) => !Object.hasOwn(fix, a)), ...Object.keys(fix).filter((a) => fix[a] === name)];
}

/** A list's items: { name, aliases } with the list's filler words. */
export function listItems(li) {
  if (!decoded.has(li)) {
    const list = LISTS[li];
    const items = decode(list.items)
      .split("\n")
      .map((line) => {
        const [name, ...aliases] = line.split("|");
        return { name, aliases };
      });
    decoded.set(li, items);
  }
  return decoded.get(li);
}

export const promptIds = () => Object.keys(PROMPTS);
export const hasPrompt = (pid) => Object.hasOwn(PROMPTS, pid);

const rooms = new Map();

/**
 * Everything about one prompt: its question, its answers (most common first) with their tiers, and
 * the letter its answers must start with when the question asks for one ("…that starts with P").
 */
export function room(pid) {
  if (rooms.has(pid)) return rooms.get(pid);
  const p = PROMPTS[pid];
  if (!p) throw new Error(`Unknown prompt ${pid}`);
  const list = LISTS[p.list];
  const items = listItems(p.list);
  const answers = p.a.split(" ").map((tok, rank) => {
    const idx = Number(tok.slice(0, -1));
    return { name: items[idx].name, aliases: items[idx].aliases, tier: tok.slice(-1), rank };
  });
  const r = {
    id: pid,
    q: p.q,
    cat: p.cat,
    diff: p.diff,
    miss: p.miss || "",
    noun: list.noun,
    listKey: list.key,
    drop: list.drop,
    letter: p.l || null,
    jewelNote: p.jd || "",
    answers,
    keys: [],
    jewel: answers.find((a) => a.tier === "j") || null,
    // The dragon's five: the most common answers that aren't a trap or the jewel.
    sealed: answers.filter((a) => a.tier === "c" || a.tier === "s").slice(0, 5).map((a) => a.name),
  };
  rooms.set(pid, r);
  return r;
}

const foldingFor = (rules) => (rules >= 8 ? 2 : 1);

/**
 * A room's key → { i: answer index, s: the name or alias it comes from } for a rules version. When
 * two answers share a key, the more common one has it. Before rules 8: folding 1, every key may be
 * made plural, and the aliases as the lists have them.
 */
function keysFor(r, rules) {
  const f = foldingFor(rules);
  if (r.keys[f]) return r.keys[f];
  const keys = new Map();
  r.answers.forEach((a, i) => {
    for (const s of spellings(r.listKey, a.name, a.aliases, f >= 2)) {
      const k = keyOf(s, r.drop, f);
      if (k && !keys.has(k)) keys.set(k, { i, s, short: f >= 2 && /^[A-Z0-9.]+$/.test(s) });
    }
  });
  return (r.keys[f] = keys);
}

/**
 * Exact match (after folding, aliases and plurals) under a run's rules (the newest by default).
 * Returns { i, s } (the answer, and the name or alias that matched) or null.
 */
export function find(r, text, rules = Infinity) {
  const keys = keysFor(r, rules);
  const k = keyOf(text, r.drop, foldingFor(rules));
  if (!k) return null;
  if (keys.has(k)) return keys.get(k);
  for (const v of keyVariants(k)) if (keys.get(v) && !keys.get(v).short) return keys.get(v);
  return null;
}

/** The answer index an exact match finds, or -1. */
export const lookup = (r, text, rules = Infinity) => find(r, text, rules)?.i ?? -1;

/**
 * Typo help for the answer box: the answers within the typo budget, closest first, each with the
 * name or alias the typo was closest to (text: what to propose). fits(i, s) leaves out answers the
 * room wouldn't take (said already, eaten, the wrong letter). Only offered in normal mode; the
 * engine itself only ever accepts exact matches.
 */
export function suggest(r, text, { rules = Infinity, limit = 3, fits = null } = {}) {
  const k = keyOf(text, r.drop, foldingFor(rules));
  if (k.length < 3) return [];
  const budget = typoBudget(k.length);
  if (!budget) return [];
  const best = new Map();
  for (const [key, e] of keysFor(r, rules)) {
    if (fits && !fits(e.i, e.s)) continue;
    const d = distance(k, key, budget);
    if (d <= budget && (!best.has(e.i) || d < best.get(e.i).d)) best.set(e.i, { d, s: e.s });
  }
  return [...best]
    .sort((a, b) => a[1].d - b[1].d || r.answers[a[0]].rank - r.answers[b[0]].rank)
    .slice(0, limit)
    .map(([i, b]) => ({ index: i, name: r.answers[i].name, text: b.s, d: b.d }));
}

let lexicon = null;
/**
 * Every answer the game knows, from every list, for warm misses: "Brazil is a country, just not
 * in Africa." Returns { name, noun, listKey } or null.
 */
export function recognise(text, preferList = null) {
  warmLexicon();
  const k = keyOf(text);
  const found = lexicon.get(k) || keyVariants(k).map((v) => lexicon.get(v)).find(Boolean);
  if (!found) return null;
  // The room's own list first ("Brazil is a country, but not in Africa"), then the broadest list
  // (a country before a World Cup host).
  return found.find((e) => e.listKey === preferList) || [...found].sort((a, b) => b.size - a.size)[0];
}

/**
 * Builds the every-answer lexicon (it decodes every list: a noticeable pause on a phone). The
 * game calls this in idle time, so the first wrong answer doesn't stutter.
 */
export function warmLexicon() {
  if (!lexicon) {
    lexicon = new Map();
    LISTS.forEach((list, li) => {
      const items = listItems(li);
      for (const it of items) {
        for (const s of spellings(list.key, it.name, it.aliases, true)) {
          const k = keyOf(s, list.drop);
          if (k.length < 2) continue;
          const all = lexicon.get(k) || [];
          if (!all.some((e) => e.listKey === list.key)) all.push({ name: it.name, noun: list.noun, listKey: list.key, size: items.length });
          lexicon.set(k, all);
        }
      }
    });
  }
}

export const allLists = () => LISTS;
