// The big paintings come as AVIF where the browser can show it (about 40% smaller), with the WebP
// as the fallback. Which ones have an AVIF copy: VARIANTS, from tools/scenes/make_web_images.py.
import { VARIANTS } from "./image-variants.js";

const HAS = new Set(VARIANTS.avif);
const avifOf = (src) => src.replace(/\.webp$/, ".avif");

/** An <img> of a painting: inside a <picture> with an AVIF source when there is one. */
export function paint(src, attrs = "") {
  const img = `<img src="${src}" ${attrs} />`;
  return HAS.has(src) ? `<picture class="pic"><source type="image/avif" srcset="${avifOf(src)}" />${img}</picture>` : img;
}

/** A CSS background of a painting: the WebP, overridden by an AVIF image-set where supported. */
export function paintBg(src) {
  const url = `background-image:url('${src}')`;
  return HAS.has(src) ? `${url};background-image:image-set(url('${avifOf(src)}') type('image/avif'), url('${src}') type('image/webp'))` : url;
}

/** The title painting's phone crop: { img, x0, x1 } in the full painting's pixels. */
export const TITLE_NARROW = VARIANTS.titleNarrow;
