import { ico } from "./forest/ui.js";
import { sfx } from "./sfx.js";
import { flushPending, checkClock } from "./stats.js";
import { store, stillCounts } from "./store.js";
import { renderGate } from "./views/gate.js";
import { renderDelve } from "./views/delve.js";
import { renderLedgerFor } from "./views/ledger.js";
import { renderArchive } from "./views/archive.js";
import { renderCamp } from "./views/camp.js";
import { renderPlace } from "./views/place.js";
import { renderShadows } from "./views/shadows.js";
import { renderAdmin, admin } from "./views/admin.js";
import { showHelp, closeModal } from "./views/modals.js";
import { $, todayDay, toast } from "./util.js";
import { CONFIG } from "./config.js";
import { renderDev } from "./views/dev.js";
import { setLightOverride } from "./forest/light.js";

const view = $("#view");
let cleanup = null;

// The visible height, so the room fits above a phone keyboard.
function syncViewport() {
  const h = window.visualViewport ? window.visualViewport.height : window.innerHeight;
  document.documentElement.style.setProperty("--vvh", `${Math.round(h)}px`);
  // A short screen (a phone with its keyboard up, or a small phone): the room and panel tighten up.
  document.documentElement.classList.toggle("short", h < 600);
  // Wide screens get the full-window forest with the UI beside it.
  const flat = window.innerWidth >= window.innerHeight * 1.2;
  document.documentElement.classList.toggle("wide", window.innerWidth >= 900 && flat);
  // A phone (or small tablet) held sideways: the map puts its panel beside the walk, like a wide screen.
  document.documentElement.classList.toggle("landscape", window.innerWidth < 900 && flat);
  syncTyping();
  // iOS scrolls the page to show a focused input. In a run the page already fits, so pin it.
  if (document.body?.dataset.view === "walk" && window.scrollY) window.scrollTo(0, 0);
}
// The keyboard is up when a text box has focus and the visible height has dropped well below
// its full height for this width. Then the room shrinks to sit above the keyboard.
let fullH = 0;
let fullW = 0;
function syncTyping() {
  const h = window.visualViewport ? window.visualViewport.height : window.innerHeight;
  if (window.innerWidth !== fullW) {
    fullW = window.innerWidth;
    fullH = 0;
  }
  const focused = document.activeElement?.matches?.("input[type=text]");
  fullH = Math.max(fullH, h);
  const typing = focused && h < fullH * 0.8;
  document.documentElement.classList.toggle("typing", Boolean(typing));
  document.documentElement.classList.toggle("tiny", Boolean(typing) && h < 400);
}
document.addEventListener("focusin", syncTyping);
document.addEventListener("focusout", () => setTimeout(syncTyping, 50));
syncViewport();
window.visualViewport?.addEventListener("resize", syncViewport);
window.visualViewport?.addEventListener("scroll", () => document.body.dataset.view === "walk" && window.scrollY && window.scrollTo(0, 0));
window.addEventListener("resize", syncViewport);

// Routes:
//   #/                today's walk (title → the walk → home), or last night's if it's still underway
//   #/day/N           a past walk (it doesn't count toward streaks)
//   #/replay/N        walk a finished day again for practice (never saved)
//   #/archive         every walk so far, and your hoard
//   #/camp            your purse, and the characters to walk as
//   #/admin[/N]       admin (passcode), optionally with day N picked
//   #/admin/play/N    test-play any day, even future ones (days past the schedule wrap round)
//   #/admin/ledger/N  preview a ledger with a sample crowd
let routedToday = null; // the day it was when the page was last routed (see onNewDay)
let todays = 0; // the day whose walk "#/" is showing
function route() {
  todays = 0;
  closeModal();
  cleanup?.();
  cleanup = null;
  window.scrollTo(0, 0);
  // "#/dev/glade?place=bridge&look=goblin" → parts ["dev", "glade"] and the query.
  const [path, query = ""] = location.hash.replace(/^#\/?/, "").split("?");
  const parts = path.split("/").filter(Boolean);
  setLightOverride(null);
  syncLight();
  const today = (routedToday = todayDay());
  const num = (s) => (/^\d+$/.test(s || "") ? Number(s) : NaN);
  const ctx = { view, setCleanup: (fn) => (cleanup = fn) };
  document.body.dataset.view = "page";

  if (today < 1) {
    view.innerHTML = `<div class="page"><div class="page-head"><h1>Pocket Quest</h1><p class="muted">The first walk opens on launch day. Come back soon.</p></div></div>`;
    return;
  }

  switch (parts[0]) {
    case undefined: {
      // A walk begun last night and still underway just after midnight: finish that one first.
      const last = store.run(today - 1);
      if (last && !last.done && last.actions.length && stillCounts(last)) return play(ctx, today - 1, "today");
      return play(ctx, today, "today");
    }
    case "day": {
      const day = num(parts[1]);
      if (!(day >= 1)) return (location.hash = "#/archive");
      if (day >= today) return (location.hash = "#/");
      return play(ctx, day, "archive");
    }
    case "replay": {
      const day = num(parts[1]);
      if (!(day >= 1) || day > today) return (location.hash = "#/");
      // Practice is walking a finished walk again: the first try comes first, wherever it lives.
      if (!store.run(day)?.done) return (location.hash = day === today ? "#/" : `#/day/${day}`);
      return play(ctx, day, "replay");
    }
    case "archive":
      document.body.dataset.view = "page";
      return renderArchive(ctx);
    case "camp":
      document.body.dataset.view = "page";
      return renderCamp(ctx);
    case "place":
      // Placing mode (from Settings): drag the creatures at the forks and copy their spots.
      return renderPlace(ctx);
    case "shadows":
      // Each animal's shadow, on the animal alone (from Settings).
      return renderShadows(ctx);
    case "dev":
      // Test shortcuts: on this computer, or with the admin unlocked.
      if (!admin.unlocked && !/^(localhost|127\.0\.0\.1|\[::1\])$/.test(location.hostname)) return (location.hash = "#/admin");
      return renderDev(ctx, parts[1], new URLSearchParams(query));
    case "admin":
      document.body.dataset.view = "page";
      if (parts[1] === "play" || parts[1] === "ledger") {
        const day = num(parts[2]);
        if (!admin.unlocked || !(day >= 1)) return (location.hash = "#/admin");
        if (parts[1] === "ledger") return renderLedgerFor(ctx, day, "test", { sample: true });
        return play(ctx, day, "test");
      }
      return renderAdmin({ ...ctx, day: num(parts[1]) });
    default:
      location.hash = "#/";
  }
}

/** The pages' painted backdrop follows the light (style.css, body[data-view="page"]). */
function syncLight() {
  document.body.dataset.light = store.lighting === "night" ? "night" : "dusk";
}

/** A day's walk: the title, the walk itself, or home (the ledger) once it's done. */
function play(ctx, day, mode) {
  if (mode === "today") todays = day;
  const rec = mode === "today" || mode === "archive" ? store.run(day) : null;
  if (rec?.done) {
    document.body.dataset.view = "home";
    return renderLedgerFor(ctx, day, mode);
  }
  const start = () => {
    // A title left open over midnight belongs to yesterday: show the new day's instead.
    if (mode === "today" && !store.run(day)?.actions.length && day !== todayDay()) return route();
    document.body.dataset.view = "walk";
    ctx.setCleanup(
      renderDelve({
        ...ctx,
        day,
        mode,
        onDone: () => {
          ctx.setCleanup(null);
          document.body.dataset.view = "home";
          window.scrollTo(0, 0);
          renderLedgerFor(ctx, day, mode, { fresh: true });
        },
      }),
    );
  };
  // Practice and test runs skip the title; so does a walk already begun (its record is saved as you
  // pass the title, so coming back from the ledger or the camp lands on the map, not the title again).
  if (mode === "replay" || mode === "test" || rec) return start();
  document.body.dataset.view = "title";
  ctx.setCleanup(renderGate({ ...ctx, day, mode, onStart: start }));
}

function paintSfx() {
  for (const b of document.querySelectorAll('[data-action="sfx"]')) {
    b.innerHTML = ico(sfx.muted ? "mute" : "sound", 20);
    b.setAttribute("aria-label", sfx.muted ? "Sound effects off" : "Sound effects on");
    b.title = sfx.muted ? "Sound is off" : "Sound is on";
  }
}

document.addEventListener("click", (e) => {
  const action = e.target.closest("[data-action]")?.dataset.action;
  if (action === "help") showHelp();
  if (action === "new-walk") {
    e.preventDefault();
    newWalk();
  }
  if (action === "sfx") {
    sfx.toggle();
    paintSfx();
    sfx.tap();
  }
});
// Browsers only allow sound after a tap: wake the audio on the first one.
document.addEventListener("pointerdown", () => sfx.unlock(), { once: true });
window.addEventListener("pq:paint-sfx", paintSfx);
// The light changed in Settings: the backdrop follows at once (each view redraws its own scene).
window.addEventListener("pq:relight", syncLight);
window.addEventListener("hashchange", route);

/** To today's walk, even from "#/" itself (where setting the hash again would do nothing). */
function newWalk() {
  if (/^#?\/?$/.test(location.hash)) route();
  else location.hash = "#/";
}

// Midnight: a new walk opens. A screen that holds nothing in progress (the title, the map before the
// first step, Past walks) moves on to the new day by itself. Home says the new walk is open (ledger.js),
// and a walk already underway carries on (it counts if it's finished in time: stillCounts in store.js).
function onNewDay() {
  if (routedToday === null || todayDay() === routedToday || document.hidden) return;
  const path = location.hash.replace(/^#\/?/, "").split("?")[0];
  const unbegun = todays && ["title", "walk"].includes(document.body.dataset.view) && !store.run(todays)?.actions.length;
  if (routedToday < 1 || unbegun || path === "archive") route();
}
setInterval(onNewDay, 15000);
document.addEventListener("visibilitychange", onNewDay);
window.addEventListener("focus", onNewDay);

for (const a of document.querySelectorAll('[data-nav="home"]')) a.innerHTML = ico("back", 20);
paintSfx();
flushPending();
route();
// A device clock a day or more out plays the wrong walk: say so (its walks won't count, see delve.js).
checkClock().then((off) => off && toast("This device's date looks wrong, so today's walk won't count. Check the clock."));

// The published site keeps itself on the device (sw.js, made by tools/publish-site.mjs): once the
// page has loaded, so it never competes with the first paint.
if (CONFIG.OFFLINE && "serviceWorker" in navigator && window.isSecureContext) {
  window.addEventListener("load", () => navigator.serviceWorker.register("sw.js").catch(() => {}));
}
